-- العيوب المعالَجة (تغيير فى الشكل لا فى الحرف أو الرقم):
--   1) الأقواس المقلوبة المتبقية بعد الهجرة 208: ")أ(" ← "(أ)"، ") الفصل الثالث (" ← "(الفصل الثالث)"،
--      ")تحت التسوية /مسددة(" ← "(تحت التسوية /مسددة)" ... (بعد حصر الأقواس المقلوبة فقط، ولا يُقلب إلا زوج
--      مكتمل لا يتجاوز 250 حرفاً، يبدأ بحرف، ولا يتبع قوسه الأخير حرف/رقم).
--   2) النسب المبعثرة ") (%25" ← "(25%)" (بترتيب الرقم وعلامة % وإبقاء النقطة التالية).
--   3) حذف ترويسات صفحات الجريدة الرسمية الدخيلة وأرقام صفحاتها من متن قرار رئيس الوزراء 3973/2025 (11 موضعاً).
--   4) الفاصلة والنقطتان الملتصقتان بما قبلهما (" ،وذلك" ← "، وذلك"، " :الآتى" ← ": الآتى")، وحذف تطويل متبقٍ داخل كلمتين.
-- لا يُمَس: عدد الأرقام ولا ترتيبها، ولا أى حرف، ولا النصوص الأخرى. ما بقى من قوائم أرقام مقلوبة الترتيب
--   (مثل "المواد )، 119، 118، 117 (120") فيحتاج مصدراً رسمياً لإعادة ترتيبه، فلم تُمَس.
-- الطريقة: لكل مادة نص نهائى مُعدّ ومُختبَر سلفاً، ولا يُطبَّق إلا إذا كان md5 النص الحالى مطابقاً للنص المتوقع
-- (فلا تُمس مادة تغيّر نصها). التحقق قبل التوليد: لكل مادة الحروف العربية/اللاتينية والأرقام متطابقة حرفاً بحرف
-- بعد استبعاد ترويسات الجريدة، وعلامات الترقيم نفسها (. ، ؛ : - / ,) متطابقة فى العدد.
-- النص القديم يُحفظ فى migration_216_backup للتراجع. نصوص article_versions المطابقة تُحدَّث معها. embeddings لا تُمس.
-- قابلة لإعادة التشغيل: ما أُصلح سابقاً يُتخطى. لا تُفشل الهجرة النشر إذا اختلف نص مادة؛ تُتخطى وتُسجَّل.
