CREATE TABLE IF NOT EXISTS migration_216_backup (
  article_id uuid NOT NULL,
  version_id uuid,
  old_body   text NOT NULL,
  saved_at   timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_216_backup_art ON migration_216_backup (article_id) WHERE version_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_216_backup_ver ON migration_216_backup (version_id) WHERE version_id IS NOT NULL;

CREATE TEMP TABLE m216_fix (
