('board_decision',89,2025,2,0,'3dbee4d75f8e17eb287a426ea443f0f1','fe35f05d0663442b36bf2ec6fde885c2',replace($m216$الشروط الواجب توافرها فى أعضاء مجالس إدارة شركات التأمين<<CR>>
 أو إعادة التأمين<<CR>>
يجب أن يتوافر فى المرشح لعضوية مجلس إدارة أى من شركات التأمين<<CR>>
 أو إعادة التأمين الشروط الآتية :<<CR>>
 1- أن يكون محمود السيرة، حسن السمعة .<<CR>>
 2- ألا يقوم به عارض من عوارض الأهلية .<<CR>>

 3- أن يكون متمتعا بحقوقه المدنية كاملة .<<CR>>
 4- أن يكون حاصلاً على مؤهل عال مناسب من إحدى الجامعات المصرية<<CR>>
 أو الأجنبية شريطة معادلته فى مصر أو موافقة الهيئة عليه .<<CR>>
 5- ألا يكون قد سبق الحكم عليه بحكم بعقوبة جناية، أو بعقوبة جنحة فى<<CR>>
جريمة ماسة بالشرف أو الأمانة أو فى إحدى الجرائم المنصوص عليها فى قوانين<<CR>>
الشركات أو القوانين المنظمة للأنشطة المالية غير المصرفية، أو قانون مكافحة غسل<<CR>>
الأموال، أو حكم بإشهار إفلاسه، وذلك خلال الخمس سنوات السابقة على تاريخ<<CR>>
 تقديم طلب الترشح ما لم يكن قد رد إليه اعتباره .<<CR>>
 6- ألا يكون قد صدر ضده أو ضد إحدى الشركات العاملة فى مجال الأنشطة<<CR>>
المالية غير المصرفية التى كان يشغل رئاسة أو عضوية مجلس إدارتها أو يعمل لديها ،<<CR>>
ثمة تدابير إدارية نتيجة مخالفات جسيمة خلال الثلاث سنوات السابقة على تاريخ تقديم<<CR>>
 طلب الترشح وكان ذلك بسبب إخلاله بواجباته ومسئولياته .<<CR>>
 7- ألا يكون قد سبق فصله عن العمل أو شطبه من سجل إحدى المهن لأمور<<CR>>
 ماسة بالشرف أو الأمانة، ما لم يمض على ذلك ثلاث سنوات .<<CR>>
 8- أن يتمتع بالاستقلالية اللازمة لأداء مهامه وواجباته، وألا يكون لديه مصالح<<CR>>
تتعارض مع واجبات رئاسة أو عضوية مجلس إدارة الشركة أو تؤثر على قدرته فى<<CR>>
القيام بذلك، على أن يتم الإفصاح عن مدى وجود أية صلة قرابة حتى الدرجة الرابعة<<CR>>
 بين المرشحين بأحد المسئولين الرئيسيين بالشركة .<<CR>>
 9- الإلمام بالتشريعات الصادرة فى مجال التأمين، وأن يتوافر لديه شروط<<CR>>
 الخبرة الآتية :<<CR>>
(أ) بالنسبة للمرشح لتولى منصب رئيس مجلس إدارة الشركة: عشر سنوات<<CR>>
على الأقل فى مجال التأمين أو إعادة التأمين أو الخبرة الاكتوارية أو فى<<CR>>
إحدى المجالات القانونية أو المحاسبية أو المالية أو الاستثمارية أو إدارة<<CR>>
الأعمال أو تكنولوجيا المعلومات المتعلقة بمجال عمل الشركة أو المجالات<<CR>>
 الطبية إذا كانت الشركة من شركات التأمين الطبى المتخصص .<<CR>>

(ب) بالنسبة للمرشحين من ذوى الخبرة: خمس عشرة سنة فى مجال التأمين<<CR>>
أو إعادة التأمين أو الخبرة الاكتوارية أو فى إحدى المجالات المالية<<CR>>
أو الاستثمارية المتعلقة بمجال عمل الشركة، ويجب أن يكون العضو<<CR>>
 المنتدب للشركة من ذوى الخبرة .<<CR>>
وللهيئة تخفيض مدة الخبرة المتطلبة فى المرشحين من ذوى الخبرة بناء<<CR>>
 على الشهادات العلمية أو المهنية الحاصل عليها المرشح .<<CR>>
(ج) بالنسبة للمرشحين لعضوية مجلس الإدارة بخلاف المشار إليهم بالبندين<<CR>>
(أ، ب): خمس سنوات على الأقل فى إحدى المجالات المشار إليها بالبند<<CR>>
 (أ) أو أى مجالات أخرى توافق عليها الهيئة .<<CR>>
وفى جميع الأحوال، يجب مراعاة التنوع فى مجالات الخبرة فى تشكيل<<CR>>
 مجلس إدارة الشركة .<<CR>>
 10- ألا يكون عضوا فى مجلس إدارة شركة تأمين أخرى تمارس ذات النشاط<<CR>>
ما لم تكن شركة تابعة أو شقيقة وبموافقة الجمعية العامة للشركة المرشح لعضوية<<CR>>
مجلس إدارتها، وذلك ما لم يقدم تعهدا بالاستقالة من عضوية مجلس إدارة الشركات<<CR>>
 المشار إليها فور فوزه بعضوية مجلس الإدارة .<<CR>>
 11- ألا يشغل المرشح لمنصب العضو المنتدب عضوية مجلس إدارة لأكثر من<<CR>>
ثلاث شركات تساهم فيها الشركة التى يمثلها فى ذات الوقت، وذلك ما لم يقدم تعهدا<<CR>>
بالاستقالة من عضوية مجلس إدارة ما زاد على الشركات المشار إليها فور فوزه<<CR>>
 بعضوية مجلس الإدارة .<<CR>>
ويجوز أن يشغل عضوية مجلس إدارة شركات أخرى بخلاف الشركات المشار<<CR>>
إليها بهذا البند شريطة عدم وجود تعارض فى المصالح وبعد الحصول على عدم<<CR>>
 ممانعة الهيئة .<<CR>>
 12- اجتياز رئيس مجلس الإدارة والعضو المنتدب للمقابلة الشخصية الذى<<CR>>
تعقدها الهيئة فى هذا الشأن، ويجوز للهيئة إجراء مقابلة شخصية مع باقى المرشحين<<CR>>
لعضوية مجلس إدارة الشركة، ويجوز أن تتم هذه المقابلات بإحدى الوسائل<<CR>>
 الإلكترونية .<<CR>>

