('board_decision',89,2025,3,0,'8e220d7d1ba98739bde0f7192ccba74d','cd5f82d9f9dd02fc05760748bc040923',replace($m216$إجراءات اختيار أعضاء مجلس إدارة الشركة<<CR>>
تُتبع الإجراءات الآتية عند اختيار أعضاء مجالس إدارة شركات التأمين<<CR>>
 أو إعادة التأمين :<<CR>>
 1- تقوم الشركة بموافاة الهيئة قبل انعقاد الجمعية العامة بستين يوما على الأقل<<CR>>
بتقرير يتضمن أسماء المرشحين لرئاسة وعضوية مجلس إدارة الشركة وأسباب تحقق<<CR>>
أو تخلف شروط الترشح فى شأنهم والمستندات المؤيدة لذلك ؛ بما فيها صورة بطاقة<<CR>>
الرقم القومى، والسيرة الذاتية لهم، وصور من الشهادات العلمية والمهنية الحاصل<<CR>>
عليها المرشح، على أن تلتزم الشركة والمرشحين بإخطار الهيئة فورا حال حدوث<<CR>>
أى تغيير فى البيانات المقدمة، وكذا إذا تبين للشركة عدم صحة أى من المستندات<<CR>>
 أو البيانات المقدمة .<<CR>>
 2- تقوم الهيئة بفحص طلبات المرشحين والتأكد من استيفاء الشروط المتطلبة<<CR>>
فى شأنهم واستيفاء البند (12) من المادة الثانية من هذا القرار، وللهيئة مخاطبة<<CR>>
الشركة أو المرشحين لاستيفاء أى بيانات أو مستندات ترى ضرورة تقديمها للبت<<CR>>
 فى طلب الترشح .<<CR>>
 3- تقوم الهيئة بإخطار الشركة بأسماء المقبولين ممن تتوافر فيهم شروط الترشح<<CR>>
لعضوية مجلس إدارة الشركة، على أن تلتزم الشركة بإخطار المتقدمين بنتيجة الفحص<<CR>>
 خلال يومى عمل على الأكثر، ونشر أسماء المقبولين على الموقع الإلكترونى لها .<<CR>>
 4- تقوم الشركة بعرض الأسماء الواردة إليها من الهيئة على الجمعية العامة<<CR>>
للانتخاب أو النظر فى تعيين أعضاء مجلس إدارة الشركة بحسب الأحوال، على أن<<CR>>
تقوم الشركة بموافاة الهيئة بتشكيل مجلس إدارتها الجديد خلال عشرة أيام عمل من<<CR>>
 تاريخ انعقاد الجمعية العامة .<<CR>>

