('board_decision',89,2025,4,0,'cfc394c79d1583e513a504f4fffdd818','af2b3fa6758797c3e8e2de5c142768bf',replace($m216$خلو أحد مقاعد أعضاء مجلس إدارة الشركة<<CR>>
فى حال خلو منصب رئيس مجلس إدارة الشركة يتولى العضو المنتدب مهام<<CR>>
 رئيس المجلس فى القيام بمهامه .<<CR>>
وفى حال خلو منصب العضو المنتدب يقوم مجلس إدارة الشركة بترشيح أحد<<CR>>
أعضاء المجلس من ذوى الخبرة لتولى مهام العضو المنتدب أو ترشيح قائم بتسيير<<CR>>
أعمال الشركة من غير أعضاء المجلس شريطة أن تتوافر فيه الشروط الواجب<<CR>>
توافرها فى الأعضاء من ذوى الخبرة على النحو المبين بهذا القرار، وبعد اجتياز<<CR>>
 المقابلة الشخصية التى تعقدها الهيئة معه .<<CR>>
وفى جميع الأحوال، يلتزم مجلس إدارة الشركة بترشيح رئيس مجلس إدارة أو<<CR>>
عضو منتدب بحسب الأحوال تتوافر فيه الشروط المنصوص عليها بهذا القرار خلال<<CR>>
مدة لا تجاوز ثلاثة أشهر من تاريخ خلو المنصب، ويجوز مدها لمدد أخرى بناء على<<CR>>
مبررات تقدمها الشركة وتقبلها الهيئة، على أن تقوم الشركة بموافاة الهيئة بالبيانات<<CR>>
والمستندات المشار إليها بالبند (1) من المادة السابقة ووفقًا للإجراءات المبينة فى<<CR>>
البندين (2 ، 3) من ذات المادة، على أن يعرض ذلك على أول جمعية عامة تالية<<CR>>
 للنظر فى اعتماد تعيين عضو مجلس الإدارة .<<CR>>
كما يجوز لمجلس إدارة الشركة فى حال خلو أحد مقاعد مجلس الإدارة بخلاف<<CR>>
منصبى رئيس المجلس والعضو المنتدب، ترشيح عضو آخر وفقًا للإجراءات<<CR>>
 المنصوص عليها بالفقرة السابقة .$m216$,'<<CR>>',chr(13))),
('board_decision',89,2025,5,0,'ef54cc72ff81be69a148bc1ea48dc78f','0f38852508e95bf005b1c3d3e57785d0',replace($m216$الهيكل الإدارى والقائمين على الإدارة التنفيذية المسئولين عن الأعمال<<CR>>
 والوظائف الفنية<<CR>>
يجب أن يتضمن الهيكل الوظيفى لشركات التأمين أو إعادة التأمين مسئولاً رئيسيا<<CR>>
عن كل من الأنشطة أو الإدارات الآتية: الاكتتاب، والاستثمار، والتعويضات ،<<CR>>
وإعادة التأمين، والخبرة الاكتوارية، والالتزام، والمراجعة الداخلية، والإدارة<<CR>>
المالية، والمخاطر، والتعامل مع شكاوى العملاء، وتكنولوجيا المعلومات والتحول<<CR>>
الرقمى، ومكافحة غسل الأموال وتمويل الإرهاب، واكتتاب فروع التأمين المختلفة ،<<CR>>
 وتعويضات فروع التأمين المختلفة، والإدارة القانونية، والموارد البشرية .<<CR>>

ويجوز للشركات المخاطبة بأحكام هذا القرار أن تعهد بوظيفة المسئول الرئيسى<<CR>>
عن إدارة الخبرة الاكتوارية إلى إحدى شركات الخبرة الاكتوارية أو إلى أحد الخبراء<<CR>>
الاكتواريين، ووظيفة المسئول الرئيسى عن الإدارة القانونية إلى أحد مكاتب المحاماة<<CR>>
المتخصصة فى ذلك المجال، وذلك بعد الحصول على موافقة الهيئة بناء على طلب<<CR>>
 تقدمه الشركة مبينًا به مبررات ذلك .<<CR>>
ويجوز للشركات المشار إليها أن يجمع المسئول عن الاكتتاب لديها بين مهامه<<CR>>
والمهام المقررة للمسئول عن اكتتاب فروع التأمين وكذا أن يجمع المسئول عن<<CR>>
التعويضات بين مهامه والمهام المقررة للمسئول عن تعويضات فروع التأمين المختلفة ،<<CR>>
وذلك شريطة موافاة الهيئة بمهام واختصاصات كل وظيفة ودورة العمل لها على حدة .$m216$,'<<CR>>',chr(13))),
