 الشروط الآتية :<<CR>>
 1- الشروط المنصوص عليها بالبنود من ) 1 إلى (8 بالمادة الثانية من هذا القرار .<<CR>>
 2- ألا تقل خبرته عن خمس سنوات فى مجال التأمين أو إعادة التأمين أو الخبرة<<CR>>
الاكتوارية أو فى إحدى المجالات القانونية أو المحاسبية أو التمويلية أو الاستثمارية<<CR>>
 أو إدارة الأعمال أو تكنولوجيا المعلومات، وذلك بحسب طبيعة الوظيفة المرشح لها .<<CR>>
 3- ألا يكون عاملاً بأى وجه وبأى صفة فى شركة أو جهة أخرى على نحو<<CR>>
 يخل بمهام وظيفته بالشركة .<<CR>>
 4- اجتياز المقابلة الشخصية التى تعقدها الهيئة مع المرشحين لتولى مسئولية<<CR>>
الأنشطة أو الإدارات الآتية: الاكتتاب، الاستثمار، التعويضات، إعادة التأمين ،<<CR>>
الخبرة الاكتوارية، الالتزام، المراجعة الداخلية، الإدارة المالية، المخاطر، التعامل<<CR>>
 مع شكاوى العملاء، وتكنولوجيا المعلومات والتحول الرقمى .<<CR>>

ويجوز للهيئة إجراء مقابلة شخصية مع المرشحين لتولى مهام الأنشطة<<CR>>
أو الإدارات الآتية: اكتتاب فروع التأمين المختلفة، وتعويضات فروع التأمين<<CR>>
 المختلفة، والإدارة القانونية، والموارد البشرية .<<CR>>
