 الأعمال والوظائف الفنية<<CR>>
تلتزم شركات التأمين أو إعادة التأمين بموافاة الهيئة بأسماء المرشحين لشغل أى<<CR>>
 من الوظائف المشار إليها بالمادة الخامسة من هذا القرار، مرفقًا به المستندات الآتية :<<CR>>
 1- صورة بطاقة الرقم القومى للمرشح .<<CR>>
 2- سيرة ذاتية تفصيلية للمرشح .<<CR>>
 3- بيان حالة تفصيلى للمرشح .<<CR>>
 4- صورة من المؤهل الدراسى، والشهادات المهنية والدورات الحاصل<<CR>>
 عليها المرشح .<<CR>>
 5- الإفصاح على النموذج المعد لذلك عن مدى وجود صلة قرابة حتى الدرجة<<CR>>
 الرابعة مع أى من أعضاء مجلس إدارة الشركة أو العاملين بها .<<CR>>
 6- تعهد بالانضمام للمنصة الإلكترونية للمهنيين المنشأة لدى الهيئة فور إتاحتها بها .<<CR>>
 7- أى بيانات أو مستندات أخرى ترى الهيئة ضرورة تقديمها .<<CR>>
وفى جميع الأحوال، تلتزم الشركات المشار إليها بالاطلاع على القائمة المعدة<<CR>>
لدى الهيئة بشأن المخالفين للتشريعات المنظمة للأنشطة المالية غير المصرفية قبل<<CR>>
 موافاة الهيئة بأسماء المرشحين لشغل أى من الوظائف المشار إليها .<<CR>>

