 الأعمال والوظائف الفنية<<CR>>
تقوم الهيئة بفحص أوراق المرشحين لشغل أى من الوظائف المشار إليها بالمادة<<CR>>
الخامسة بهذا القرار وإخطار الشركة بقرارها فى هذا الشأن، وتكون موافقة الهيئة<<CR>>
على شغل أى من تلك الوظائف لمدة ثلاث سنوات قابلة للتجديد بشرط استمرار توافر<<CR>>
 شروط شغل الوظيفة .<<CR>>
وفى جميع الأحوال، لا يجوز للشركة تعيين أى من المرشحين لشغل الوظائف<<CR>>
 المشار إليها إلا بعد الحصول على موافقة الهيئة .<<CR>>
ويجوز للهيئة – بناء على مبررات تقبلها -إعفاء أى من شاغلى الوظائف<<CR>>
