من هامش الملاءة المالية المطلوب، يجوز للهيئة إلزام الشركة بواحد أو أكثر مما يلي :<<CR>>
 1- تجنيب الأرباح القابلة للتوزيع فورا ما يكفى لاستكمال النقص فى هامش<<CR>>
 الملاءة المالية.<<CR>>
 2- زيادة رأس مالها المدفوع وفقًا للخطة التى تضعها الشركة وتوافق عليها<<CR>>
 الهيئة فى حال عدم وجود أرباح كافية لديها لاستيفاء النقص فى هامش الملاءة المالية.<<CR>>
كما يجوز للشركة تغطية عجز هامش الملاءة المالية من خلال حصولها على<<CR>>
قرض مساند من المساهمين وفقًا للشروط والضوابط التى تضعها الهيئة فى هذا الشأن،<<CR>>
 وبمراعاة ما يلي :<<CR>>
 1- عدم التصرف فى القرض المساند إلا بعد الحصول على موافقة مسبقة من الهيئة.<<CR>>
 2- عدم تحميل القرض لأية فوائد أو عوائد على المبلغ الممنوح.<<CR>>
 3- ألا تزيد مدة القرض على خمس سنوات على أن يستهلك القرض على مدار<<CR>>
الخمس سنوات بنسب متساوية خلال تلك المدة، وحال اعتماد الشركة على القرض<<CR>>
المساند لأكثر من خمس سنوات فى تغطية العجز المشار إليه تقوم الهيئة بمطالبة<<CR>>
 الشركة بزيادة رأس مالها وفقًا لما تقره فى هذا الشأن.<<CR>>
 4- أن يتم معالجة القرض المساند بالقوائم المالية وبما لا يخالف معايير<<CR>>
