 إلى الهيئة وفقًا للنموذج المعد منها لهذا الغرض مرفقًا به المستندات الآتية :<<CR>>
 1- دراسة الجدوى الفنية والاقتصادية وخطة عمل الشركة خلال الخمس سنوات<<CR>>
الأولى من بدء نشاطها، مع بيان التجهيزات اللازمة لمباشرة النشاط وتقديرات<<CR>>
