 وفقًا للنموذج المعد من الهيئة لهذا الغرض .<<CR>>
 2- بيان خطتها فى استخدام البرامج الإلكترونية والتطبيقات التكنولوجية فى<<CR>>
تسويق الخدمات المقدمة منها، وبيان مدى توافقها مع قانون تنظيم وتنمية استخدام<<CR>>
 التكنولوجيا المالية فى الأنشطة المالية غير المصرفية والقرارات الصادرة تنفيذًا له .<<CR>>

 3- بيان خطتها فيما يتعلق بالوساطة فى التأمين متناهى الصغر، وفتح فروع<<CR>>
 فى المحافظات والمناطق الريفية .<<CR>>
 4- بيان بطبيعة وخصائص القطاعات التى تستهدف الشركة التعامل معها ،<<CR>>
وبيان أماكن تواجدها، والتغطيات التأمينية المناسبة لها، مع تقدير حجم الأقساط<<CR>>
