 إجمالى إيرادات الشركة .<<CR>>
 5- شهادة تثبت عدم التباس اسم الشركة مع غيرها من الشركات .<<CR>>
 6- ثلاث نسخ من العقد الابتدائى والنظام الأساسى للشركة .<<CR>>
 7- بيان بهيكل مساهمى الشركة من الأشخاص الطبيعيين المالكين لنسبة (5%)<<CR>>
فأكثر من رأس مالها متضمن الاسم، والعنوان، وصورة بطاقة الرقم القومى<<CR>>
 للمصريين أو جواز السفر للأجانب، وحصة كل منهم وخبراتهم السابقة .<<CR>>
 8- بيان بهيكل مساهمى الشركة من الأشخاص الاعتبارية متضمن الاسم والشكل<<CR>>
القانونى والقانون المؤسس وفقًا له والجنسية وطبيعة النشاط الذى يتم ممارسته ،<<CR>>
ورأس المال بالنسبة للشركات، والقائمون على إدارة الشخص الاعتبارى ومن له حق<<CR>>
