التأمين التى تعامل معها خلال آخر خمس سنوات السابقة على تاريخ<<CR>>
 تقديم الطلب .<<CR>>
 3- بالنسبة لأعضاء الجهاز الإنتاجى :<<CR>>
تلتزم شركة التأمين أو إعادة التأمين التى يعمل لحسابها بتحمل المسئولية المدنية<<CR>>
المقررة عن أخطائهم قبل حملة الوثائق أو المستفيدين منها أو الغير فى تأمينات<<CR>>
المسئوليات الصادرة عنها طالما تم إثبات الضرر بسبب تلك الفئات بناء على قرار<<CR>>
 من الهيئة .<<CR>>

 4- بالنسبة للوسطاء بشركة الوساطة :<<CR>>
يكتفى بالنسبة لوسطاء التأمين أو إعادة التأمين لهذه الشركات الذين يعملون<<CR>>
باسم ولحساب شركات الوساطة فى التأمين أو إعادة التأمين والقائمين بأعمال الإدارة<<CR>>
التنفيذية بأن يتم تغطيتهم من خلال وثيقة مسئولية مهنية شاملة وفق البند (1)<<CR>>
 من هذه المادة .$m216$,'<<CR>>',chr(13)));
