('board_decision',69,2025,16,0,'86b63298cfd04613fdac704c0f2106e4','0c84d56b23c20fb3711e0f6e62992fd3',replace($m216$الحالات الواجب على الوسطاء إخطار الهيئة بشأنها<<CR>>
