القرار إخطار الهيئة كتابة بأى تعديلات تطرأ على البيانات أو المستندات المقدمة منهم<<CR>>
رفق طلب القيد أو التجديد أو إعادة قيد بالسجل خلال ثلاثين يوما على الأكثر من<<CR>>
تاريخ التعديل، على أن يرفق بالإخطار بيان بتلك التعديلات ومبرراتها والمستندات<<CR>>
 الخاصة بذلك .<<CR>>
وتلتزم شركات الوساطة بإخطار الهيئة مسبقًا، وبمدة لا تقل عن خمسة عشر يوما ،<<CR>>
