('board_decision',69,2025,18,0,'1a88d3df41c233154875d2244119633c','e3422fe2fbc9540c59e9ae2291358f46',replace($m216$الشروط الواجب توافرها فى القائم بإدارة شركات الوساطة فى التأمين<<CR>>
