 الشروط الآتية :<<CR>>
 1- أن يكون مقيدا بالسجل .<<CR>>
 2- أن يكون قد مارس أعمال الوساطة فى التأمين لمدة لا تقل عن تسع سنوات ،<<CR>>
أو أن يكون قد شغل وظيفة مدير عام فى شركة تأمين لمدة لا تقل عن خمس سنوات ،<<CR>>
أو أن يكون قد زاول عملاً فنيا تأمينيا فى إحدى الجهات المرتبطة بالتأمين أو إعادة<<CR>>
 التأمين لمدة لا تقل عن خمس عشرة سنة .<<CR>>
 3- التفرغ لأعمال الإدارة التنفيذية بالشركة، وعدم الجمع بين هذه الوظيفة<<CR>>
 وبين أى وظيفة أخرى داخل أو خارج الشركة .<<CR>>
 4- اجتياز الاختبار الذى تعقده الهيئة فى هذا الشأن .$m216$,'<<CR>>',chr(13))),
('board_decision',69,2025,19,0,'e1d9561fc29634fbd993a732dd7ac781','453c757ed55a911b1b7a802c4d471392',replace($m216$الشروط الواجب توافرها فى القائم بإدارة شركات الوساطة فى إعادة التأمين<<CR>>
