 الشروط الآتية :<<CR>>
 1- أن يكون مقيدا بالسجل كوسيط إعادة تأمين .<<CR>>

 2- أن يكون لديه خبرة فى أعمال الوساطة فى إعادة التأمين بإحدى شركات<<CR>>
التأمين أو إعادة التأمين أو عمل بإحدى شركات الوساطة فى التأمين أو إعادة التأمين<<CR>>
لمدة لا تقل عن تسع سنوات وبحد أدنى خمس سنوات فى مجال الوساطة فى إعادة<<CR>>
التأمين، أو عمل مديرا عاما لشركة تأمين لمدة لا تقل عن خمس سنوات مقرونة<<CR>>
بخبرة عملية فى مجال إعادة التأمين لا تقل عن خمس سنوات، أو أن يكون قد زاول<<CR>>
عملاً فنيا تأمينيا فى إحدى الجهات المرتبطة بالتأمين أو بإعادة التأمين لمدة لا تقل عن<<CR>>
 خمس عشرة سنة .<<CR>>
 3- التفرغ لأعمال الإدارة التنفيذية بالشركة، وعدم الجمع بين هذه الوظيفة<<CR>>
 وبين أى وظيفة أخرى داخل وخارج الشركة .<<CR>>
 4- اجتياز الاختبار الذى تعقده الهيئة فى هذا الشأن .$m216$,'<<CR>>',chr(13))),
('board_decision',69,2025,20,0,'952f772380d3c0d1b18ba3837d9d1aef','5b8f0f00410a77baee9df6ef5ba47442',replace($m216$وجود مانع لدى القائم بالإدارة التنفيذية<<CR>>
فى حالة وجود مانع لدى القائم بالإدارة التنفيذية لدى شركات الوساطة فى التأمين<<CR>>
أو إعادة التأمين يحول دون مباشرة أعماله، يجوز لمجلس إدارة الشركة أن يكلف<<CR>>
مؤقتًا أحد وسطاء التأمين أو إعادة التأمين بحسب الأحوال من المقيدين بسجلات الهيئة<<CR>>
بتولى مهام القائم بالإدارة التنفيذية لحين تعيين آخر مكانه أو زوال المانع، شريطة أن<<CR>>
يكون عضو مجلس إدارة ومقيد كوسيط بالسجل أو من الوسطاء العاملين بالشركة ،<<CR>>
ويجوز الاستعانة بوسيط خارجى بعد موافقة مجلس إدارة الشركة عليه وتحديد<<CR>>
مسئولياته واختصاصاته مع إخطار الهيئة به وذلك خلال أسبوع من تاريخ خلو<<CR>>
 منصب القائم بالإدارة التنفيذية على أن يجتاز المقابلة التى تعقدها الهيئة .<<CR>>
ويسرى حكم المادة (35) من هذا القرار حال فقد القائم بالإدارة التنفيذية لأحد<<CR>>
شروط قيده لدى الهيئة أو فى حال عدم تكليف أى من المشار إليهم بالفقرة السابقة<<CR>>
لتولى مهام القائم بالإدارة التنفيذية للشركة، أو فى حال عدم تعيين قائم بالإدارة<<CR>>
التنفيذية للشركة خلال ثلاثة أشهر من تاريخ خلو منصبه ويجوز مد هذه المدة لمدد<<CR>>
 أخرى بناء على مبررات تقدمها الشركة وتقبلها الهيئة .<<CR>>

