('board_decision',69,2025,21,0,'4c1f2368a37fe33c1e9a5d8972723c46','4d0f9f7906739d183e87cd91058f8f42',replace($m216$تولى خبراء التأمين الاستشاريين مهام الإدارة التنفيذية<<CR>>
