التنفيذية لأحد خبراء التأمين الاستشاريين المقيدين لدى الهيئة، شريطة استيفاء ما يلى :<<CR>>
 1- أن يكون مقيدا بسجل وسطاء التأمين أو إعادة التأمين بحسب الأحوال .<<CR>>
 2- أن تتوافر لديه خبرة لمدة لا تقل عن خمس سنوات فى مجال إعادة التأمين<<CR>>
 وذلك بالنسبة لشركة الوساطة فى إعادة التأمين .<<CR>>
 3- التعهد بعدم تقديم أية استشارات تأمينية، ونقل قيده إلى جدول<<CR>>
 غير المشتغلين .<<CR>>
 4- اجتياز المقابلة الشخصية التى تعقدها معه الهيئة .<<CR>>
ويسرى على خبراء التأمين الاستشاريين ذات الأحكام السارية فى شأن القائمين<<CR>>
 بالإدارة التنفيذية الواردة بهذا القرار .$m216$,'<<CR>>',chr(13))),
('board_decision',69,2025,22,0,'ac4a064b6bcc4d2b775e9ec6e29fc990','3704adcef4ef32ce9c14680104c8d024',replace($m216$الجمعية العامة لشركات الوساطة فى التأمين وإعادة التأمين<<CR>>
على شركة الوساطة فى التأمين أو إعادة التأمين دعوة الجمعية العامة للانعقاد<<CR>>
فى الزمان والمكان اللذين يعينهم نظام الشركة ويجب أن تعقد الجمعية مرة على الأقل<<CR>>
فى السنة خلال الثلاثة شهور التالية لنهاية السنة المالية للشركة، ولمجلس الإدارة<<CR>>
 أن يقرر دعوة الجمعية العامة كلما دعت الضرورة إلى ذلك .<<CR>>
ويجب على مراقب الحسابات أن يدعو الجمعية العامة للانعقاد فى الأحوال التى<<CR>>
يتراخى فيها رئيس مجلس الإدارة عن دعوة الجمعية العامة للانعقاد خاصة خلال<<CR>>
 الثلاثة أشهر التالية لنهاية السنة المالية للشركة .<<CR>>
وتلتزم الشركة أن تقدم إلى الهيئة صورة من محضر اجتماع الجمعية العامة<<CR>>
 فى موعد أقصاه ثلاثين يوما من تاريخ انعقاد الجمعية لاعتماده .<<CR>>
وتلتزم الشركة بإدراج ما ترى الهيئة عرضه كبند من بنود جدول أعمال الجمعية<<CR>>
العامة للشركة، وعلى رئيس الجمعية تلاوة ملخص لتقرير الهيئة فى حالة عدم<<CR>>
 حضور ممثل عن الهيئة .<<CR>>

$m216$,'<<CR>>',chr(13))),
('board_decision',69,2025,23,0,'40c8cb5d7fc9789969dd976d0ea2bde9','f5ab332f40fb4102ced9241a2a7e81e4',replace($m216$مواعيد إعداد وعرض وتقديم القوائم المالية والمستندات المرفقة بها للهيئة<<CR>>
تلتزم الشركة بموافاة الهيئة قبل شهر من موعد انعقاد الجمعية العامة بالقوائم<<CR>>
المالية السنوية والإفصاحات المرفقة بها وفقًا لمعايير المحاسبة المصرية، وتقرير<<CR>>
بشأنها من أحد مراقبى الحسابات المقيدين بالقسم الأول من سجل مراقبى الحسابات<<CR>>
المنظم بقرار مجلس إدارة الهيئة رقم 244 لسنة 2023 المشار إليه، وتقرير مجلس<<CR>>
الإدارة عن نشاط الشركة، وموعد ومكان انعقاد الجمعية العامة وجدول أعمالها ،<<CR>>
 وجميع المستندات التى تقدم للمساهمين أو من فى حكمهم عن أعمال الشركة .<<CR>>
وللهيئة إبداء ملاحظاتها على القوائم المالية، وكذا على أى من البيانات<<CR>>
والمستندات الواردة بهذا القرار وإخطار الشركة بملاحظاتها، على أن يعرض ذلك<<CR>>
 على الجمعية العامة للشركة .<<CR>>
وتلتزم الشركة بموافاة الهيئة بالقوائم المالية السنوية لها خلال خمسة عشر يوما<<CR>>
 من تاريخ انتهاء الثلاثة أشهر التالية لانتهاء السنة المالية مرفق بها المستندات الآتية :<<CR>>
 1- تقرير مراقب الحسابات عن تلك القوائم حال تعديلها من قبل الجمعية<<CR>>
 العامة للشركة .<<CR>>
 2- حجم العمليات التى توسطت الشركة فيها خلال العام، وحجم العمولات<<CR>>
 التى حصلت عليها .<<CR>>
 3- مقدار العمولات المستحقة لها من كافة شركات التأمين أو إعادة التأمين على<<CR>>
 حدة عن السنة المالية المنقضية، ومقدار مديونية كل شركة .<<CR>>
 4- أسماء شركات التأمين أو إعادة التأمين التى تعاملت معها خلال السنة<<CR>>
 المالية المنقضية .$m216$,'<<CR>>',chr(13))),
('board_decision',69,2025,24,0,'52af29e9d64e21732566e3b41fc87dc3','00d2e47d50d6b09a5fbb4f480ad9777a',replace($m216$الهيكل التنظيمى لشركات الوساطة فى التأمين وإعادة التأمين<<CR>>
يجب أن يتضمن الهيكل التنظيمى والإدارى لشركات الوساطة فى التأمين وإعادة<<CR>>
