 التعديلات التى تمت على الوثيقة .<<CR>>
 تاريخ تجديد الوثيقة .<<CR>>
 اسم وسيط التأمين .<<CR>>
 2- سجل المطالبات: وتقيد به الوثائق التى توسطت فى إبرامها وتمت عليها<<CR>>
 مطالبات، ويشمل البيانات الآتية كحد أدنى :<<CR>>
 اسم العميل /عنوانه /رقم هاتفه /البريد الإلكترونى إن وجد .<<CR>>
 رقم الوثيقة /نوع الوثيقة /تاريخ إصدارها /اسم شركة التأمين .<<CR>>
 تاريخ بدء التأمين .<<CR>>

 تاريخ تلقى شركة الوساطة للمطالبة وقيمتها .<<CR>>
 تاريخ تقديم المطالبة لشركة التأمين وقيمتها .<<CR>>
