 موقف المطالبة (تحت التسوية /مسددة) .<<CR>>
 3- سجل الوسطاء: وتقيد به بيانات الوسطاء الملتحقين بالعمل لدى الوسيط<<CR>>
 ويشمل البيانات الآتية كحد أدنى :<<CR>>
 اسم الوسيط /عنوانه /رقم هاتفه/البريد الإلكترونى إن وجد .<<CR>>
