 تاريخ آخر تجديد قيد .<<CR>>
 تاريخ التعيين .<<CR>>
 تاريخ انهاء العلاقة التعاقدية .<<CR>>
 التدابير والجزاءات الموقعة على الوسيط من الهيئة والشركة .<<CR>>
