 6- شهادة تفيد عدم صدور أحكام بإشهار الإفلاس ضد الشركة .<<CR>>
 7- بيان بهيكل المساهمين مع تعهد بالالتزام بتوفيق أوضاع الهيكل وفقا<<CR>>
 للقرارات الصادرة عن الهيئة فى هذا الشأن .<<CR>>
 8- بيان بأعضاء مجلس إدارة الشركة وإقرارات بعدم صدور أى أحكام جنائية<<CR>>
 أو إشهار إفلاس ضدهم .<<CR>>
 9- تقديم قوائم مالية سنوية أو ربع سنوية (شريطة أن تكون معدة وفقًا للفحص<<CR>>
