 عن مجلس إدارة الهيئة فى هذا الشأن، على أن يتضمن على وجه الأخص ما يلى :<<CR>>
 1- اسم الصندوق وعنوان مركزه الرئيسى، والغرض من إنشائه .<<CR>>
 2- تاريخ تأسيس الصندوق، وتاريخ احتساب المزايا وتحصيل الاشتراكات ،<<CR>>
 وتاريخ التسجيل .<<CR>>

 3- تعريف وتحديد أجر الاشتراك بالنسبة لتحصيل الاشتراكات وصرف<<CR>>
 المزايا التأمينية .<<CR>>
 4- شروط الانضمام لعضوية الصندوق وتحديد رسم الانضمام والحد الأقصى<<CR>>
 لسن الانضمام، وتحديد قيمة الاشتراكات ورسوم العضوية .<<CR>>
 5- تعريف العضو المؤسس .<<CR>>
 6- الأحوال التى تزول فيها صفة العضوية ومنها :<<CR>>
 (أ) بلوغ سن التقاعد .<<CR>>
 (ب) الوفاة .<<CR>>
 (ج) العجز المنهى للخدمة (جزئى /كلي) .<<CR>>
 (د) النقل (إجبارى /اختياري) .<<CR>>
 (ه) الاستقالة من الخدمة .<<CR>>
 (و) الفصل من الخدمة .<<CR>>
 (ز) المعاش المبكر .<<CR>>
 (ح) الاستقالة أو الانسحاب من الصندوق .<<CR>>
 (ط) الفصل من الصندوق .<<CR>>
 (ي) أى أسباب أخرى يقترحها الصندوق وتوافق عليها الهيئة .<<CR>>
 7- معالجة حالات الأعضاء الذين تنتهى خدمتهم بالعجز الجزئى المنهى للخدمة ،<<CR>>
والذين ينقلون إجباريا إلى جهات عمل أخرى، وحالات الإعارة أو الندب<<CR>>
 أو الإجازات بدون مرتب .<<CR>>
 8- معالجة الحالات التى تسترد فيها العضوية، وبيان حقوق والتزامات<<CR>>
 الأعضاء فى هذه الحالات .<<CR>>
 9- بيان القواعد والإجراءات التى تنظم حالات الخروج الجماعى، أيا كان سببه<<CR>>
وعلى سبيل المثال: الخروج الجماعى الاختيارى أو بسبب الانسحابات أو الاستقالات<<CR>>
 الجماعية أو بسبب العجز الصحى .<<CR>>
 10- تحديد الجزاءات المترتبة على مخالفة العضو لأحكام النظام الأساسى<<CR>>
للصندوق ؛ وعلى الأخص فيما يتعلق بالتأخير عن سداد الاشتراكات والتوقف<<CR>>
 عن سدادها .<<CR>>

 11- جداول الاشتراكات ومواعيد استحقاقها .<<CR>>
 12- المزايا المالية والتعويضات والمعاشات المحددة التى يلتزم الصندوق<<CR>>
 بسدادها ومواعيد استحقاقها .<<CR>>
 13- تحديد الموارد المالية للصندوق، والتى تبنى عليها الدراسات الإكتوارية .<<CR>>
 14- قواعد استثمار أموال الصندوق .<<CR>>
 15- الحد الأقصى للنسبة المئوية التى تخصص من موارد الصندوق<<CR>>
 للمصروفات الإدارية .<<CR>>
 16- القواعد الخاصة بتشكيل مجلس الإدارة واختصاصاته .<<CR>>
 17- القواعد الخاصة بعقد الجمعية العامة العادية وغير العادية والقرارات<<CR>>
 التى تختص بإصدارها والإجراءات والشروط التى تتبع فى ذلك .<<CR>>
 18- الشروط والإجراءات المتبعة فى تعديل النظام الأساسى للصندوق .<<CR>>
 19- القواعد الخاصة باختصاصات المدير التنفيذى والمدير المالى للصندوق .<<CR>>
 20- قواعد وإجراءات تعيين مراقبى الحسابات وتقدير مكافآتهم .<<CR>>
 21- أحوال وقواعد وإجراءات تحويل أموال الصندوق إلى صندوق آخر أو إلى وثيقة<<CR>>
