 فى صندوق آخر أو تصفيته وكيفية التصرف فى أمواله عند الحل أو التصفية .<<CR>>
 22- الوثائق والمكاتبات والسجلات الخاصة بالصندوق وما يقوم مقامها والتى<<CR>>
 يتعين على الصندوق إمساكها .<<CR>>
 23- قواعد الرقابة الداخلية والامتثال .$m216$,'<<CR>>',chr(13))),
('board_decision',237,2024,4,0,'8bb4912230fc69339709ffa1071a740b','64b5a9b90af36a625eb9187b07e87426',replace($m216$ضوابط تعديل النظام الأساسى لصناديق التأمين الخاصة<<CR>>
يقدم طلب تعديل النظام الأساسى لصناديق التأمين الخاصة على النموذج المعد<<CR>>
 من الهيئة لهذا الغرض مرفقًا به المستندات الآتية :<<CR>>
 1- دراسة اكتوارية بشأن التعديلات المطلوبة (فى الحالات التى تتطلب إعداد<<CR>>
دراسة اكتوارية)، على أن يتم الالتزام عند إعدادها بكافة الضوابط والإجراءات<<CR>>
الصادرة عن الهيئة، وكذا أسطوانة مدمجة بالبيانات التفصيلية لأعضاء الصندوق التى<<CR>>
 اعتمد عليها الخبير الاكتوارى عند إعداد الدراسة الإكتوارية .<<CR>>

 2- محضر اجتماع الجمعية العامة غير العادية متضمنًا عدد أعضاء الصندوق<<CR>>
والحاضرين منهم ومدى توافر النصاب القانونى لاجتماع الجمعية وكافة التعديلات<<CR>>
المطلوبة وتاريخ سريانها ونتيجة تصويت الأعضاء على تلك التعديلات وتاريخ بدء<<CR>>
العمل بالتعديلات، مع ضرورة صياغة المحضر بأسلوب واضح خاليا من أى كشط<<CR>>
أو تصحيح وأن يكون موقعا من رئيس الاجتماع ومراقب الحسابات وأمين سر<<CR>>
 الاجتماع ومعتمدا بخاتم الصندوق .<<CR>>
 3- ما يفيد سداد الدعم أو مساهمة الجهة (إن وجدت) على أن يكون ذلك معتمدا<<CR>>
 من الجهة التابع لها الصندوق .<<CR>>
 4- ما يفيد سداد مصروفات النشر على الموقع الإلكترونى الذى تخصصه الهيئة<<CR>>
 لهذا الغرض والموقع الإلكترونى للصندوق .<<CR>>
 5- كشوف أجور الأعضاء معتمدة من الصندوق والخبير الاكتوارى (إن وجدت) .<<CR>>
 6- أى مستندات أخرى ترى الهيئة ضرورة تقديمها .<<CR>>
ويجب أن يدرج بطلب تعديل النظام الأساسى كافة التعديلات التى وافق عليها<<CR>>
أعضاء الجمعية العامة غير العادية للصندوق وتناولتها الدراسة الإكتوارية بالتفصيل ،<<CR>>
وتاريخ سريان التعديلات طبقًا لموافقة الجمعية العامة غير العادية، كما يجب أن<<CR>>
يرفق بالطلب إقرار من رئيس مجلس إدارة الصندوق أو من ينوب عنه بصحة البيانات<<CR>>
 المقدمة للهيئة وموقعا منه ومختوم بخاتم الصندوق .<<CR>>
ويصدر قرار تعديل النظام الأساسى من رئيس الهيئة أو من يفوضه، وينشر<<CR>>
