('board_decision',237,2024,5,0,'107dcb0d7b4302299e834a1b42aed246','008d8865fa40169827052f699de21ec7',replace($m216$حالات وضوابط تصفية وشطب قيد صناديق التأمين الخاصة<<CR>>
 أولاً -حالات تصفية الصندوق :<<CR>>
 تصدر الهيئة قرار تصفية الصندوق فى الحالات الآتية :<<CR>>
 1- موافقة الجمعية العامة غير العادية بالأغلبية المتطلبة لذلك .<<CR>>
 2- إذا تبين من نتيجة الفحص الاكتوارى المنصوص عليه بالمادة (74)<<CR>>
 من قانون التأمين الموحد أن أموال الصندوق لا تكفى للوفاء بالتزاماته .<<CR>>

 3- إذا ثبت أن الصندوق لا يسير وفقًا لأحكام قانون التأمين الموحد أو القرارات<<CR>>
 المنفذة له أو لنظامه الأساسى .<<CR>>
 4- إذا كانت إدارة الصندوق يشوبها غش أو تدليس .<<CR>>
وفى الحالات الثلاث الأخيرة ينذر الصندوق بالمخالفات ويمنح مهلة ثلاثين يوما<<CR>>
 لإبداء دفاعه وفى حالة عدم تصحيح وضعه يصفى الصندوق .<<CR>>
 ثانيا -ضوابط تصفية الصندوق :<<CR>>
يصدر قرار تصفية الصندوق من رئيس الهيئة أو من يفوضه، ويجب<<CR>>
 أن يتضمن القرار ما يلى :<<CR>>
 1- تعيين لجنة تصفية الصندوق من ثلاثة أعضاء يكون من بينهم رئيسا ،<<CR>>
 تكون مهمتها مباشرة أعمال التصفية وإنهاء إجراءاتها .<<CR>>
 2- تحديد مصروفات التصفية اللازمة، على أن يكون من ضمنها مصروفات<<CR>>
 نشر قرار الشطب الموقع الإلكترونى الذى تخصصه الهيئة لهذا الغرض .<<CR>>
 3- تحديد المدة اللازمة لانتهاء لجنة التصفية من أعمالها .<<CR>>
 4- أن يتم توزيع ناتج التصفية على أعضاء الصندوق وقت التصفية .<<CR>>
ويجوز مد مدة التصفية بناء على طلب من لجنة التصفية المشار إليها وتزاد<<CR>>
مصروفاتها إذا اقتضى الأمر ذلك لحين انتهاء اللجنة من أعمالها، وتعين جهة العمل<<CR>>
عضوا أو أكثر فى لجنة التصفية إذا اقتضت الضرورة ذلك أو إذا رأت اللجنة أن ذلك<<CR>>
 لازم لإتمام إجراءات التصفية بعد موافقة الهيئة .<<CR>>
وعلى القائمين على إدارة الصندوق تسليم جميع المستندات والسجلات والأموال<<CR>>
الخاصة بالصندوق إلى اللجنة بمجرد طلبها ويحظر عليهم التصرف فى أى شأن<<CR>>
 من شئون الصندوق إلا بأمر كتابى منها .<<CR>>
وتؤول صافى أموال الصندوق إلى الأعضاء فى تاريخ التصفية ويوزع عليهم<<CR>>
 ناتج التصفية وفقًا لتقرير الخبير الإكتوارى واعتماد الهيئة .<<CR>>
 ثالثًا -حالات شطب قيد الصندوق :<<CR>>
 تصدر الهيئة قرار شطب قيد الصندوق فى الحالات الآتية :<<CR>>
 1- إذا توقف الصندوق عن مباشرة أعماله، ومنها عدم قيامه بتحصيل<<CR>>
 الاشتراكات من الأعضاء أو تصفية الجهة المنشأ بها الصندوق .<<CR>>

 2- إذا اندمج الصندوق فى صندوق آخر أو تم تحويله إلى وثيقة تأمين جماعية<<CR>>
 بذات الأعضاء .<<CR>>
 3- بعد الانتهاء من إجراءات تصفية الصندوق .<<CR>>
 رابعا -ضوابط شطب الصندوق :<<CR>>
يصدر قرار شطب قيد الصندوق من رئيس الهيئة أو من يفوضه، ويجب أن يتضمن<<CR>>
القرار اسم الصندوق وتاريخ الشطب، وينشر قرار الشطب على الموقع الإلكترونى<<CR>>
 الذى تخصصه الهيئة لهذا الغرض بعد سداد مقابل مصروفات النشر المقرر .$m216$,'<<CR>>',chr(13))),
