('board_decision',278,2024,2,0,'3dbd802051899a5227cf8f75057b77d1','5b8965445b93991ce75eb3ce1cfef1c8',replace($m216$يشترط أن يتوافر فى العضوين المرشحين من ذوى الخبرة بمجالس إدارة<<CR>>
 صناديق التأمين الخاصة ما يلى :<<CR>>
 1- أن يكون محمود السيرة حسن السمعة .<<CR>>
 2- أن يكون لديهم خبرة لا تقل عن سبع سنوات فى مجال التأمين أو الاستثمار<<CR>>
أو القانون، على أن يكون أحدهما على الأقل لديه خبرة فى مجال التأمين<<CR>>
 أو الاستثمار .<<CR>>

 3- عدم الجمع بين عضوية مجلس إدارة الصندوق والعمل به .<<CR>>
 4- التعهد بإخطار مجلس الإدارة عن كافة المعلومات والبيانات التى تتعلق<<CR>>
بوجود أى من حالات تعارض المصالح مع الصندوق، وكذا الإفصاح عن أية مصالح<<CR>>
مادية أو تعاملات أو أمور تخصهم يكون من شأنها التأثير على الصندوق وأوجه<<CR>>
استثمارات أمواله، مع عدم اشتراك العضو المعنى الذى تتعلق حالة تعارض المصالح<<CR>>
 به فى حضور الاجتماع والتصويت على القرار .<<CR>>
 5- ألا يكون قد سبق الحكم عليه بحكم نهائى بعقوبة جنائية، أو بعقوبة جنحة فى<<CR>>
جريمة ماسة للشرف أو الأمانة أو فى إحدى الجرائم الجسيمة المنصوص عليها<<CR>>
بالقوانين المنظمة للأنشطة المالية غير المصرفية أو المنصوص عليها فى قانون البنك<<CR>>
المركزى والجهاز المصرفى أو قانون مكافحة غسل الأموال أو حكم بإشهار إفلاسه<<CR>>
 خلال الخمس سنوات السابقة على ترشيحه، وذلك ما لم يكن رد إليه اعتباره .<<CR>>
 6- ألا تكون الهيئة قد أصدرت ضده أو ضد الصندوق أو إحدى الشركات<<CR>>
العاملة فى مجال الأنشطة المالية غير المصرفية التى كان يشغل عضوية مجلس<<CR>>
إدارتها أو يعمل لديها أى تدبير -باستثناء التنبيه -خلال الثلاث سنوات السابقة على<<CR>>
 ترشيحه وكان ذلك بسبب إخلاله بواجباته أو مسئولياته .<<CR>>
 7- التعهد بالالتزام بمراعاة كافة التشريعات المنظمة لعمل صناديق التأمين<<CR>>
الخاصة وكذا النظام الأساسى للصندوق، وبذل عناية الرجل الحريص فى مباشرته<<CR>>
لجميع الأعمال المتعلقة بالصندوق ؛ وعلى وجه الأخص تخصيص وقت كافٍ<<CR>>
للاضطلاع بمسئولياته بما فى ذلك التحضير المسبق لاجتماعات مجلس الإدارة ولجانه<<CR>>
 وحضور تلك الاجتماعات .<<CR>>
وتزول صفة العضوية عن عضو مجلس الإدارة من ذوى الخبرة بمجلس إدارة<<CR>>
الصندوق حال فقده لأى من الشروط أو إخلاله بأى من التعهدات المشار إليها بهذه المادة .<<CR>>

$m216$,'<<CR>>',chr(13))),
('board_decision',278,2024,3,0,'0344a1e2d454f4fdf77b153bc24f00bb','b5059faadb0fc55f3021736558e797b7',replace($m216$تتبع الإجراءات الآتية عند اختيار العضوين من ذوى الخبرة بمجلس إدارة صندوق<<CR>>
 التأمين الخاص :<<CR>>
 1- يقوم مجلس إدارة الصندوق بترشيح اثنين من ذوى الخبرة من داخل الجهة<<CR>>
المنشأ بها الصندوق أو خارجها لعضوية مجلس إدارة الصندوق، على أن يكون ذلك<<CR>>
 الترشيح بأغلبية ثلثى أعضاء مجلس إدارة الصندوق .<<CR>>
 2- تلتزم صناديق التأمين الخاصة بإخطار الهيئة قبل الدعوة للجمعية العامة<<CR>>
بشهر على الأقل بأسماء المرشحين من ذوى الخبرة والمستندات المؤيدة لخبراتهما<<CR>>
للتأكد من استيفائهما للشروط المتطلبة فيهما، وكذا لإجراء المقابلة الشخصية مع<<CR>>
المرشحين عن الصناديق التى يبلغ حجم أموالها خمسمائة مليون جنيه فأكثر، ويجوز<<CR>>
للهيئة إجراء المقابلة الشخصية مع المرشحين عن الصناديق التى يقل حجم أموالها عن<<CR>>
 خمسمائة مليون جنيه .<<CR>>
وعلى الصناديق توجيه الدعوة لعقد الجمعية العامة لها خلال أسبوعين من تاريخ<<CR>>
موافقة الهيئة على المرشحين المشار إليهما، على أن تنعقد الجمعية خلال مدة لا تقل<<CR>>
 عن ثلاثين يوما من تاريخ توجيه الدعوة .<<CR>>
وفى حال عدم موافقة الهيئة على المرشحين المشار إليهما أو على أى منهما<<CR>>
يلتزم الصندوق بترشيح آخرين وفقًا للإجراءات المشار إليها بهذه المادة، تمهيدا<<CR>>
 للعرض على الجمعية العامة للصندوق للنظر فى اختيارهما .<<CR>>
ويجب أن تتضمن الدعوة للجمعية العامة للصندوق أسماء العضوين المرشحين من ذوى<<CR>>
الخبرة، على أن يرفق بالدعوة السيرة الذاتية لهذين المرشحين موضحا بها الخبرات العلمية<<CR>>
 والعملية لكل منهما واستيفاء الشروط الواردة بالمادة الثانية من هذا القرار .<<CR>>
 3- فى حال عدم موافقة الجمعية العامة للصندوق على العضوين المرشحين من<<CR>>
ذوى الخبرة أو على أحدهما، يتولى مجلس إدارة الصندوق خلال أسبوعين من تشكيله<<CR>>
ترشيح أسماء أخرى من داخل الجهة المنشأ بها الصندوق أو خارجها لاستكمال<<CR>>

الأعضاء من ذوى الخبرة بمجلس إدارة الصندوق، على أن يكون ذلك الترشيح<<CR>>
بأغلبية ثلثى الأعضاء، وتتبع ذات الإجراءات المشار إليها بهذه المادة فيما يتعلق<<CR>>
 بإخطار وموافقة الهيئة .<<CR>>
ويتولى مجلس إدارة الصندوق خلال أسبوعين من تاريخ موافقة الهيئة، دعوة<<CR>>
الجمعية العامة للصندوق للانعقاد خلال مدة لا تقل عن خمسة عشر يوما وذلك للنظر<<CR>>
فى اختيار المرشحين من ذوى الخبرة لعضوية مجلس إدارة الصندوق، على أن يرفق<<CR>>
بالدعوة السيرة الذاتية لكل منهم موضحا بها الخبرات العلمية والعملية واستيفاء<<CR>>
 الشروط الواردة بالمادة الثانية من هذا القرار .<<CR>>
 4- إذا خلا منصب عضو مجلس الإدارة من ذوى الخبرة لأى سبب من الأسباب<<CR>>
يقوم المجلس بإتباع ذات الإجراءات المشار إليها بهذه المادة لترشيح من يحل محله<<CR>>
 وتكون مدة العضو الجديد مكملة لمدة سلفه .<<CR>>
وفى جميع الأحوال، تتبع ذات الإجراءات المشار إليها بهذه المادة حال تجديد<<CR>>
 ترشيح الأعضاء من ذوى الخبرة فى مجلس إدارة الصندوق .$m216$,'<<CR>>',chr(13))),
