('pm_decision',3973,2025,1,0,'945b9f24a2486886fe0dff742459710a','5dfd41a75808c2bcb90fa9c5b92f75f9',replace($m216$في تطبيق أحكام هذا النظام، يعمل بالتعاريف الواردة بالمادة (1) من قانون تنظيم<<CR>>
المسئولية الطبية وسلامة المريض المشار إليه، كما يقصد بالكلمات والعبارات التالية<<CR>>
 المعاني الموضحة قرين كل منها :<<CR>>
