 الناجمة عن الأخطاء الطبية .<<CR>>
الإصابة البدنية: كل ضرر يصيب الجسم البشري ويؤثر علي سلامة الأنسجة<<CR>>
أو الأعضاء أو الوظائف الحيوية بصورة لا تصل إلى العجز ويكون ناجما<<CR>>
 عن خطأ طبي .<<CR>>
