 حق استلامه من الصندوق .$m216$,'<<CR>>',chr(13))),
('pm_decision',3973,2025,10,0,'f44b2e86582b357dd908d121413c3417','f36d33e539617f5cec3560dceba912d7',replace($m216$يتولى إدارة الصندوق مجلس إدارة يشكل من رئيس وعضوية ستة أعضاء<<CR>>
على أن يكون اثنان منهم من ذوي الخبرة في مجال التأمين أو الاستثمار توافق<<CR>>
 عليهما الهيئة .<<CR>>

ويصدر بتشكيل مجلس الإدارة قرار من الوزير المختص، ويحدد القرار بدلات<<CR>>
 الحضور والمكافأة المقررة لرئيس وأعضاء المجلس .<<CR>>
 وتكون مدة عضوية مجلس الإدارة أربع سنوات قابلة للتجديد .<<CR>>
وينعقد مجلس الإدارة بدعوة من رئيسه مرة كل ثلاثة أشهر على الأقل، وكلما<<CR>>
دعت الضرورة إلى ذلك، ولا يكون انعقاده صحيحا إلا بحضور خمسة من أعضائه<<CR>>
على الأقل، وتصدر قراراته بأغلبية أصوات الحاضرين، وفي حالة التساوي يرجح<<CR>>
 رأي الجانب الذي منه الرئيس .<<CR>>
ويجوز للوزير المختص دعوة مجلس الإدارة للانعقاد للنظر في الموضوعات<<CR>>
التي يحددها، ويعتبر مستقيلاً من المجلس كل عضو يتخلف عن الحضور ثلاث<<CR>>
 جلسات متتالية أو أكثر من نصف جلسات المجلس خلال العام دون عذر مقبول .<<CR>>
ولرئيس الهيئة دعوة مجلس الإدارة للانعقاد كلما رأى ضرورة للنظر<<CR>>
في الموضوعات التي يرى عرضها على المجلس، ويجب وعلى مجلس الإدارة<<CR>>
 أن يبت في هذه الموضوعات خلال شهر على الأكثر من تاريخ إبلاغه بها .<<CR>>
وللهيئة أن توفد مندوبا عنها لحضور اجتماعات مجلس الإدارة كلما<<CR>>
رأت ضرورة لذلك، ويكون له حق الاشتراك في مناقشات المجلس دون أن يكون<<CR>>
 له حق التصويت .$m216$,'<<CR>>',chr(13))),
('pm_decision',3973,2025,12,0,'49c9fb5f35c950626fa66b7ba743b309','a6358b450937730ebdd1a396e1aac843',replace($m216$مجلس الإدارة هو السلطة العليا المهيمنة على شئونه وتصريف أموره<<CR>>
وله في سبيل ذلك أن يتخذ ما يراه لازما من قرارات لمباشرة اختصاصاته وعلى<<CR>>
 الأخص ما يأتي :<<CR>>
 1- وضع اللوائح المالية والإدارية والموارد البشرية للصندوق بعد موافقة الهيئة ،<<CR>>
على أن يصدر بها قرار من الوزير المختص وتنشر بالوقائع المصرية وعلى الموقع<<CR>>
 الإلكتروني للهيئة والصندوق .<<CR>>

 2- وضع الهيكل التنظيمي للصندوق .<<CR>>
 3- تحديد السجلات والدفاتر المالية والإدارية التي يتعين على الفروع<<CR>>
 الإمساك بها، وكذا قواعد وضوابط سير العمل بها .<<CR>>
 4- إقرار نظام للرقابة الداخلية يهدف إلى :<<CR>>
(أ) التحقق من التزام الصندوق والعاملين به بتطبيق أحكام القوانين واللوائح<<CR>>
 والقرارات السارية .<<CR>>
 (ب) حماية أصول وموارد الصندوق .<<CR>>
 (ج) وضع قواعد المساءلة والمحاسبة داخل الصندوق .<<CR>>
 5- تحديد أوجه استثمار أموال الصندوق القابلة للاستثمار بمراعاة الأحكام<<CR>>
المقررة بقانون التأمين الموحد المشار إليه، وكذا الضوابط والقرارات الصادرة<<CR>>
 عن مجلس إدارة الهيئة في هذا الشأن .<<CR>>
 6- الموافقة على المركز المالي والموازنة التقديرية والحساب الختامي للصندوق .<<CR>>
 7- اعتماد التقارير (ربع السنوية -السنوية) التي ترفع إليه عن نشاط الصندوق .<<CR>>
شروعات اللوائح والقرارات المتعلقة<<CR>>
 داء الرأي في كافة م<<CR>>
 8- إب<<CR>>
 باختصاصات الصندوق .<<CR>>
 9- النظر فيما يرى الوزير المختص أو الهيئة عرضه من مسائل تدخل<<CR>>
 في اختصاصات الصندوق .<<CR>>
ولمجلس الإدارة أن يستعين بمن يراه من ذوي الخبرة والمتخصصين لمعاونته<<CR>>
