('pm_decision',3973,2025,13,0,'c66d60c9fde2369a9fb604d64661ca53','6243d15ac608b73eed31bc57d3372a40',replace($m216$توثق اجتماعات مجلس الإدارة من خلال إعداد محضر اجتماع لكل جلسة<<CR>>
يتضمن مكان وتوقيت الاجتماع وإثبات حضور أعضاء المجلس والموضوعات التي تم<<CR>>
مناقشتها بالاجتماع وملخصا لمناقشات أعضاء المجلس والقرارات المتخذة في هذا<<CR>>
الشأن وإثبات ما يبديه الأعضاء من تحفظات على أن يكون لعضو مجلس الإدارة<<CR>>

حال رفض إثبات تحفظه تقديم شكوى للهيئة مثبتًا بها مضمون التحفظ خلال أسبوع<<CR>>
 على الأكثر من تاريخ الاجتماع .<<CR>>
 ويجب توقيع المحضر من رئيس المجلس وكافة أعضاء المجلس الحاضرين .<<CR>>
ويكون لكل عضو من أعضاء مجلس الإدارة طلب الاطلاع على أي محضر<<CR>>
 من محاضر مجلس الإدارة .<<CR>>
ويلتزم الصندوق بإرفاق محضر اجتماع مجلس الإدارة بعد استيفاء كافة<<CR>>
 التوقيعات المتطلبة قانونًا عليه، بسجل محاضر اجتماعات مجلس الإدارة .<<CR>>
ويجوز للصندوق حفظ محاضر اجتماعات مجلس الإدارة من خلال سجلات<<CR>>
إلكترونية بما يسمح بتخزينها وتوثيقها والاحتفاظ بها وعدم تغييرها واستخراجها بشكل<<CR>>
