 وعدم الاختراق على النحو الذي تحدده الهيئة .$m216$,'<<CR>>',chr(13))),
('pm_decision',3973,2025,14,0,'b1461a285d39d6595f48848bee85b4ba','fb90a71e2477bfe5dd49340b51cf13d9',replace($m216$يجب أن يتوافر للصندوق نظام مكتوب متكامل للرقابة الداخلية توافى به الهيئة<<CR>>
 وذلك بمراعاة الآتي :<<CR>>
 1- أن يقوم مجلس الإدارة بتحديد الاختصاصات والفصل بين المسئوليات<<CR>>
 والمهام بالصندوق بما يمنع تعارض المصالح .<<CR>>
