('pm_decision',3973,2025,15,0,'232d3b68dfce407d3d54c52dfdd7847e','7676c8e5bed185f0127d171f1b665d14',replace($m216$يكون للصندوق مدير تنفيذي متفرغ يصدر بتعينه وتحديد معاملته المالية قرار من<<CR>>
