 إدارته قبل ثلاثة أشهر على الأقل من بدء السنة المالية الخاصة به .<<CR>>
 8- إعداد التقارير (ربع السنوية -السنوية) عن نشاط الصندوق للعرض<<CR>>
 على مجلس الإدارة للنظر في إقرارها .<<CR>>
 9- ما يرى مجلس الإدارة إسناده إليه وتكليفه به من اختصاصات .<<CR>>
ويكون المدير التنفيذي للصندوق مسئولاً مسئولية مباشرة أمام مجلس الإدارة<<CR>>
 ويحضر جلساته دون أن يكون له صوت معدود .<<CR>>

