('pm_decision',3973,2025,18,0,'8eb56005247561695cd2468b77084a69','dcb5fb115d6685f497f2fd6b4e440885',replace($m216$أموال الصندوق أموال خاصة، وتعد أمواله أموالاً عامة في تطبيق أحكام الباب<<CR>>
الرابع من الكتاب الثاني من قانون العقوبات، ويعد القائمون على إدارته موظفين<<CR>>
 عموميين في تطبيق أحكام البابين الثالث والرابع من قانون العقوبات .<<CR>>
وتودع أموال الصندوق في حساب خاص أو أكثر لدى أحد البنوك المسجلة لدى<<CR>>
البنك المركزي المصري يخصص للصرف منه على أغراض الصندوق وفق أحكام<<CR>>
