('pm_decision',3973,2025,20,0,'c4c36cb1140b60ce05a3a9f69398d919','9b26780f28db12bd7ea000f950b1168f',replace($m216$يكون للصندوق حساب إيرادات ومصروفات، يقيد في جانب الإيرادات<<CR>>
الاشتراكات المحصلة على مستوي الجمهورية، وعائد استثمار أموال الصندوق وأية<<CR>>
إيرادات أخرى، ويقيد في جانب المصروفات التعويضات المدفوعة وجميع<<CR>>
المخصصات الفنية الواجب تجنيبها بناء على فحص اكتواري سنوي، يقدم الصندوق<<CR>>
به تقريرا من خبير اكتواري من بين المقيدين في سجلات الهيئة، يرفق بالميزانية<<CR>>
ويراعى فيه توضيح أن المخصصات الفنية قد تم تقديرها وفق الأسس الفنية السليمة ،<<CR>>
ويلتزم الصندوق بموافاة الهيئة بنتيجة هذا الفحص، بالإضافة إلى المصروفات الأخرى<<CR>>
 ويرحل (الفائض /العجز السنوي) إلى الميزانية في القوائم المالية .$m216$,'<<CR>>',chr(13))),
('pm_decision',3973,2025,21,0,'c407c57928ff10a54cddcc281777b345','aea8147eea7b4a69885b4f3275f5d9db',replace($m216$مع عدم الإخلال بالمواعيد المنصوص عليها في قانون التأمين الموحد<<CR>>
المشار إليه والقرارات الصادرة تنفيذًا له، يلتزم الصندوق بموافاة الهيئة بالبيانات<<CR>>
 والمستندات الآتية :<<CR>>
 1- القوائم المالية السنوية والدورية وفقًا للمواعيد المقررة من قبل الهيئة .<<CR>>
 2- تقرير مراقب الحسابات متضمنًا توضيح ما إذا كانت الحسابات الختامية<<CR>>
قد أعدت وفقًا لمعايير المحاسبة المصرية وقرارات مجلس إدارة الهيئة المعمول بها<<CR>>
في هذا الشأن ومدى تعبيرها عن المركز المالي للصندوق تعبيرا صحيحا من واقع<<CR>>
سجلاتها والبيانات الأخرى التي رأى ضرورة الحصول عليها وإنها قد وضعت تحت<<CR>>
تصرفه، وعلى أن يتضمن التقرير – حال وجود تحفظات -بيان مدى تأثيرها على<<CR>>

المركز المالي للصندوق، ويجب على مراقب الحسابات أن يخطر الصندوق كتابة بأي<<CR>>
