 بإخطار الهيئة بذلك .<<CR>>
 3- تقرير مجلس الإدارة عن حالة الصندوق ونشاطه خلال العام .<<CR>>
 4- تقرير مجلس الإدارة عن أداء الاستثمار .<<CR>>
 5- بيان عدد الاشتراكات الجديدة وقيمتها وعدد المشتركين وقيمة اشتراكاتهم<<CR>>
 وفقًا للنموذج الذي تعده الهيئة في هذا الشأن .<<CR>>
 6- بيان بعدد المطالبات التي قدمت للصندوق خلال العام وقيمتها ومقدار<<CR>>
 التعويضات التي تم سدادها خلال العام وتلك التي ما تزال تحت التسوية .<<CR>>
 7- وفى حال التعامل مع شركات التأمين يتم موافاة الهيئة ببيان تلك الشركات<<CR>>
 والحصص المسندة إليها .$m216$,'<<CR>>',chr(13))),
('pm_decision',3973,2025,22,0,'321073ef5c1cbdc0015d448b2efaf400','bb09beaa5d01a0ed24d8a66f57eb0d72',replace($m216$يقدم الصندوق تقريرا اكتواريا إلى الهيئة بمركزه المالي يعده أحد الخبراء<<CR>>
الاكتواريين كل خمس سنوات على الأكثر يوضح فيه مدى كفاية أموال الصندوق<<CR>>
لمقابلة التزاماته وفقًا للأسس الفنية التي تعتمدها الهيئة في هذا الخصوص، ويتم إعداد<<CR>>
هذا التقرير وفقًا للشروط والضوابط التي يصدرها مجلس إدارة الهيئة، ولمجلس إدارة<<CR>>
الهيئة أن يطلب تقديم هذا التقرير في أي وقت قبل مضى خمس سنوات بحيث لا تقل<<CR>>
المدة عن سنة من تاريخ آخر تقرير، على أن ترسل صورة منه إلى الهيئة خلال ستة<<CR>>
أشهر من انتهاء الفترة التي أعد عنها التقرير مصحوبة بشهادة من الخبير الاكتوارى<<CR>>
تثبت أن المسئولين عن إدارة الصندوق قد وضعوا تحت تصرفه جميع البيانات<<CR>>
والمعلومات التي طلبها ويراها ضرورية لأداء مهامه، ويلتزم الخبير بإخطار الهيئة<<CR>>
بأي خطأ أو مخالفات قد تتكشف لديه أثناء إعداد التقرير الاكتواري، وللهيئة مد هذا<<CR>>
الميعاد لفترة لا تزيد على ثلاثة أشهر، وإذا تبين للهيئة أن تقرير الخبير الاكتوارى<<CR>>
لا يعبر عن حقيقة المركز المالي للصندوق فيلتزم الصندوق بإعادة إعداد التقرير<<CR>>
 بواسطة خبير اكتواري آخر على نفقة الصندوق .<<CR>>
 ويلتزم الصندوق في جميع الحالات بنفقات إعادة الفحص .<<CR>>

