  $m216$,'<<CR>>',chr(13))),
('law',155,2024,1,0,'8d2630a82872deec535726f9722cd056','e76f090d8375707e72023040ae293beb',replace($m216$تعريفات: في تطبيق أحكام هذا القانون،يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها: الهيئة:الهيئة العامة للرقابة المالية. عقد التأمين:عقد يلتزم المؤمن بمقتضاه أن يؤدى إلى المؤمن له أو إلى المستفيد الذي اشترط التأمين لصالحه مبلغًا من المال أو إيرادا مرتبا أو أى عوض مالى آخر في حالة وقوع الحادث أو تحقق الخطر المبين بالعقد وذلك نظير قسط أو أقساط دورية أو أية دفعات مالية أخرى يؤديها المؤمن له للمؤمن،ويشار إليه بلا وثيقة. عقد إعادة التأمين:عقد يلتزم بمقتضاه معيد التأمين بأن يعوض الطرف الثاني المؤمن وهو شركة التأمين عن كل أو جزء من الخسارة التي يتحملها بموجب عقد التأمين الأصلي،وذلك في مقابل التزام الطرف الثاني بسداد قسط إعادة التأمين إلى معيد التأمين. عقد التأمين التكافلي:عقد يهدف إلى تحقيق التعاون بين مجموعة من المشتركين يتعرضون لخطر واحد أو أخطار معينة،حيث يقوم كل منهم بدفع مبلغ مالى على سبيل التبرع يسمى الاشتراك بما يؤدى إلى تكوين صندوق يسمى صندوق المشتركين يتم من خلاله دفع التعويض لمن يستحقه،ويكون هذا الصندوق منفصلاً بشكل تام عن حسابات شركة التأمين التكافلي المتضمنة حسابات المساهمين. الفائض التأميني في مجال التأمين التكافلي:ما تبقى من صافى أقساط المشتركين المؤمن لهم وعوائدها والإيرادات الأخرى المتعلقة بوثائق التأمين بعد خصم جميع المصروفات وصافى التعويضات المدفوعة والمخصصات الفنية خلال السنة.<<CR>>
تأمينات الحياة:جميع عمليات التأمين التي يكون فيها الخطر المؤمن ضده يتعلق بحياة الأشخاص،ويكون الغرض منها دفع مبالغ بسبب وفاة شخص معين أو عجزه عجزا كليا أو جزئيا دائما أو مؤقتًا أو بلوغه سنًا معينة أو ضمان معاش يدفع له أو للمستفيدين منه مدى الحياة أو خلال فترة محددة،كما يشمل أيضا ذات التأمينات التي ترتبط المزايا الخاصة بها باستثمارات في الأوراق والأدوات المالية. تأمينات الحوادث الشخصية طويلة الأجل:جميع عمليات التأمين التي تزيد مدتها على سنة،والتي يكون فيها الخطر المؤمن ضده متعلقًا بالشخص وناتجا عن حادث وترتب عنه الوفاة أو العجز. تأمينات العلاج الطبي طويلة الأجل:جميع عمليات التأمين التي تزيد مدتها على سنة،ويكون الغرض منها صرف مزايا نقدية للأشخاص المؤمن عليهم في حالات العجز الناتج عن المرض،وكذا تغطية تكاليف العلاج الطبي. نشاط شركات إدارة برامج الرعاية الصحية:النشاط الذى تتولى من خلاله الشركة مسئولية جميع الأعمال الإدارية المرتبطة بوثائق التأمين الطبي التي تصدرها شركات التأمين،وذلك كطرف ثالث بين شركة التأمين والعميل،وذلك على النحو الذي تحدده الهيئة. عمليات تكوين الأموال:العمليات التي يكون الغرض منها تكوين مال من مشتركين يصرف فى تاريخ محدد مقابل قسط أو أقساط دورية،دون أن يرتبط ذلك باحتمالات الحياة أو الوفاة. الأطراف المرتبطة:الأشخاص الذين يجمع بينهم اتفاق بغرض الاستحواذ أو السيطرة الفعلية على إحدى الشركات الخاضعة لأحكام هذا القانون،سواء كان هذا الاتفاق مكتوبا أو غير مكتوب. ويعد من الأطراف المرتبطة الأشخاص الطبيعيون وأى من أزواجهم وأقاربهم حتى الدرجة الثانية،والأشخاص الاعتبارية والكيانات والاتحادات والروابط والتجمعات المالية المكونة من شخصين أو أكثر والتي تكون غالبية أسهم أو حصص إحداها مملوكة مباشرة أو بطريق غير مباشر للطرف الآخر أو يكون مالكها شخصا واحدا،كما يعد من الأطراف المرتبطة الأشخاص الخاضعون للسيطرة الفعلية لشخص آخر.<<CR>>
صندوق التأمين الخاص:كل نظام بين مجموعة من الأفراد تربطهم مهنة أو عمل واحد أو أي صلة اجتماعية أخرى ويتألف بغير رأسمال،ويكون الغرض منه أن يؤدى إلى أعضائه أو المستفيدين منه تعويضات أو مزايا تأمينية أو اجتماعية أو معاشات دورية وفقًا لنظامه الأساسي المعتمد من الهيئة والضوابط أو المعايير التي يصدرها مجلس إدارة الهيئة. صناديق التأمين الحكومية:الصناديق التي تتولى عمليات التأمين ضد الأخطار التى لا تقبلها عادة شركات التأمين أو تلك التي ترى الحكومة مزاولتها بنفسها لهدف قومي أو اجتماعي. نظام المزايا المحددة:النظام الذي تحدد فيه الميزة التأمينية سلفًا من خلال دراسة اكتوارية للمركز المالي للصندوق بما يكفل تحقيق التوازن بين المزايا والموارد. نظام الاشتراكات المحددة:النظام الذي تحدد فيه حقوق المشترك بالرصيد التراكمي المتجمع في حسابه عند الاستحقاق،ولا تكون فيه المزايا محددة مسبقًا. النظام المختلط:النظام الذي يجمع بين نظامي المزايا المحددة والاشتراكات المحددة. الحوسبة السحابية:النموذج الذي يمكن من الوصول الشبكي من أي مكان وبشكل مناسب وعند الطلب إلى مجموعة مشتركة من المصادر المادية أو الافتراضية كالشبكات والخوادم ووسائط التخزين والتطبيقات والخدمات التي يمكن توفيرها بسرعة واستخدامها بأقل جهد أو السداد الإلكتروني أو الأنشطة والإعلانات الإلكترونية الخاصة بأى من المنشآت أو الأفراد الخاضعين لإشراف ورقابة الهيئة بما في ذلك آليات ضمان حماية بيانات العملاء وسهولة استرجاعها وقواعد وضوابط الرقابة عليها من الهيئة. مجمعة التأمين:كيانات تؤسسها مجموعة من شركات التأمين أو إعادة التأمين بهدف الاكتتاب في أخطار معينة. الكيان:أى شركة أو منشأة أو مؤسسة أيا كان شكلها القانوني،مصرية أو أجنبية،تسيطر أو تستحوذ بشكل مباشر أو غير مباشر على نسبة (10%) أو أكثر من حجم نشاط التأمين بالسوق،أو يمثل نشاط التأمين بالنسبة لها وما يرتبط به من خدمات نسبة تزيد على (50%) من ملكية شركاتها التابعة داخل جمهورية مصر العربية التي تعمل في تلك الأنشطة أو الخدمات.$m216$,'<<CR>>',chr(13))),
('law',155,2024,3,0,'5c740d533a760566ab637d6e97f942a4','50ac479a0b45be83d56f3d6b809a9671',replace($m216$يتكون هيكل قطاع التأمين من:ً أولا -المنشآت التي تزاول التأمين وإعادة التأمين،وهي:<<CR>>
1- شركات التأمين وشركات إعادة التأمين.<<CR>>
2- شركات التأمين التكافلي وإعادة التأمين التكافلي.<<CR>>
3- شركات التأمين الطبي المتخصصة.<<CR>>
4- شركات التأمين متناهى الصغر.<<CR>>
5- مجمعات التأمين.<<CR>>
6- صناديق التأمين الحكومية.<<CR>>
7- صناديق التأمين الخاصة.ً ثانيا -المهن والأنشطة المرتبطة بالتأمين،وهي:<<CR>>
1- الخبراء الاكتواريون.<<CR>>
2- خبراء التأمين الاستشاريون.<<CR>>
3- خبراء تقييم الأخطار.<<CR>>
4- خبراء معاينة وتقدير الأضرار.<<CR>>
5- وسطاء التأمين.<<CR>>
6- وسطاء إعادة التأمين.<<CR>>
7- شركات إدارة برامج التأمين الطبي.ً ثالثا -الاتحادات والأجهزة المعاونة ومكاتب التمثيل،وهي:<<CR>>
1- اتحاد شركات التأمين.<<CR>>
2- اتحادات المهن والأنشطة المرتبطة بالتأمين.<<CR>>
3- الأجهزة المعاونة التى تنشأ وفقًا لحكم المادة (122) من هذا القانون.<<CR>>
4- مكاتب تمثيل منشآت التأمين أو إعادة التأمين أو الأنشطة المرتبطة بهما. ولمجلس إدارة الهيئة الموافقة على الترخيص بأى أنشطة أو خدمات تأمين أخرى وفقًا لمتطلبات السوق،وذلك كله وفقًا للمعايير والقواعد التي يقررها،وعلى ألا يقل رأسمالها المصدر والمدفوع عن الحد المقرر بالنسبة لشركات التأمين الطبي المتخصصة. (الفصل الثاني) نشاط التأمين$m216$,'<<CR>>',chr(13))),
('law',155,2024,6,0,'0ce7cad1c4bc85aa6a676271bce8da22','a4af2cf40ddedfebe203d889a82b288f',replace($m216$تسقط بالتقادم الدعاوى الناشئة عن نشاط التأمين وإعادة التأمين وما يرتبط به من خدمات بانقضاء ثلاث سنوات من وقت حدوث الواقعة التى تولدت عنها هذه الدعاوى. ولا تسرى المدة المشار إليها بالفقرة الأولى من هذه المادة في الأحوال الآتية: (أ) في حالة إخفاء بيانات متعلقة بالخطر المؤمن ضده،أو تقديم بيانات غير صحيحة أو غير دقيقة عن هذا الخطر إلا من اليوم الذي علمت فيه شركة التأمين بذلك. (ب) في حالة وقوع الحادث المؤمن ضده إلا من اليوم الذي علم فيه ذوو الشأن بوقوعه.$m216$,'<<CR>>',chr(13))),
('law',155,2024,8,0,'1bb907ebcd7541f2ab6f375297797712','ac7ae95e2687caa79d18c1f731d31fb8',replace($m216$لا يلتزم المؤمن فى تعويض المؤمن له إلا عن الضرر الناتج من وقوع الخطر المؤمن منه بشرط ألا يجاوز ذلك قيمة التأمين. (الفصل الثالث) أحكام خاصة ببعض أنواع التأمين تأمينات الأشخاص وعمليات تكوين الأموال$m216$,'<<CR>>',chr(13))),
('law',155,2024,19,0,'9c49e733a3b59928ba348a835ad8502a','54578895fcfcf0773f1134a5a498fe27',replace($m216$إذا خفض التأمين فلا يجوز أن ينزل عن الحدود الآتية:<<CR>>
1- في العقود المبرمة مدى الحياة لا يجوز أن يقل مبلغ التأمين المخفض عن القيمة التي كان يستحقها المؤمن له لو كان قد دفع ما يعادل الاحتياطى الحسابي في تاريخ التخفيض مخصوما منه (1%) من مبلغ التأمين الأصلي،باعتبار أن هذا المبلغ هو مقابل التأمين الذى يجب دفعه مرة واحدة في تأمين من ذات النوع وطبقًا لتعريفة التأمين التي كانت مرعية في عقد التأمين الأصلي.<<CR>>
2- في العقود المتفق فيها على أداء مبلغ التأمين بعد عدد معين من السنين، لا يجوز أن يقل مبلغ التأمين المخفض عن جزء من مبلغ التأمين الأصلى بنسبة ما دفع من أقساط.$m216$,'<<CR>>',chr(13))),
('law',155,2024,37,0,'897cf9d4683db7d2f9ac3cfdde78a96e','c2a67b573281da772a694908bc3c1d1c',replace($m216$يعد تأمينًا متناهى الصغر كل تأمين يستهدف ذوى الدخول المنخفضة في مجالات تأمين الممتلكات والأشخاص لحمايتهم من أخطار قد يتعرضون لها وبحد أقصى للتغطية مبلغ مائتي ألف جنيه،ويجوز لمجلس إدارة الهيئة زيادته سنويا بنسبة لا تزيد على (25%) وذلك في الفروع المنصوص عليها بالمادة (2) من هذا القانون.<<CR>>
وتحدد قرارات مجلس إدارة الهيئة أنواع هذا التأمين والحد الأقصى لمبالغ التأمين وأسس الاكتتاب والشروط والقواعد الخاصة بهذا النوع من التأمين.$m216$,'<<CR>>',chr(13))),
('law',155,2024,47,0,'26597096f0511316c0e3dec5348d8750','a8bb9e033dcff763c5bfd7aaed1f0a38',replace($m216$تؤدى مجمعة التأمين المعنية مبلغ التأمين المحدد عن الحوادث المشار إليها في المادة (40) من هذا القانون إلى المستحق أو ورثته وذلك دون الحاجة إلى اللجوء للقضاء في هذا الخصوص.<<CR>>
ويكون مبلغ التأمين الذي تؤديه مجمعة التأمين المعنية مائة ألف جنيه في حالات الوفاة أو العجز الكلى المستديم ويحدد مقدار مبلغ التأمين في حالات العجز الجزئي المستديم بمقدار نسبة العجز كما يحدد التعويض عن الأضرار التي تلحق بممتلكات الغير بحد أقصى عشرون ألف جنيه. ولمجلس إدارة الهيئة،استنادا إلى الدراسات الفنية والاكتوارية التي تعد في هذا الشأن،زيادة مبالغ التأمين المذكورة وبما لا يزيد على (50%) منها في كل حالة، وذلك بعد أخذ رأى وزارة الداخلية وموافقة رئيس مجلس الوزراء. ويحدد مجلس إدارة الهيئة كيفية وشروط أداء مبلغ التأمين للمستحقين في كل من الحالات المشار إليها،على أن يصرف مبلغ التأمين في مدة لا تجاوز ثلاثين يوما من تاريخ إبلاغ شركة التأمين أو الصندوق المشار إليه بالمادة (61) من هذا القانون بوقوع الحادث واستيفاء المستندات اللازمة لفحص الطلب.$m216$,'<<CR>>',chr(13))),
('law',155,2024,57,0,'4ed9e2cc56204d8ccbf054444681db80','893352c7f4f299e9ca549a9feaa1ab1e',replace($m216$لا يترتب على حق الرجوع المقرر لمجمعة التأمين المعنية وفقًا لأحكام المادتين (55، 56) من هذا القانون الإخلال بحق المضرور فى الرجوع على المسئول عن الحقوق المدنية. (الفصل الرابع) نشاط مجمعات التأمين$m216$,'<<CR>>',chr(13))),
('law',155,2024,59,0,'01a5c970fb91304af1c4b63c16d23434','744633a05cd5d0af4ba8a07061dbc853',replace($m216$يضع الأعضاء المؤسسون للمجمعة النظام الأساسي لها،ويصدر بإنشاء مجمعة التأمين والتصديق على نظامها قرار من مجلس إدارة الهيئة. وتسجل المجمعة في سجل خاص لدى الهيئة بعد أداء رسم مقداره مائة ألف جنيه، يسدد وفقًا لطرق السداد المقررة قانونا وتكتسب الشخصية الاعتبارية الخاصة من تاريخ نشر قرار التسجيل في الوقائع المصرية. ويجب إخطار الهيئة بأية تعديلات تطرأ على النظام الأساسي وبمبررات هذا التعديل،ولا يجوز العمل بهذه التعديلات إلا بعد اعتمادها من مجلس إدارة الهيئة ونشرها بالوقائع المصرية. (الفصل الخامس) نشاط صناديق التأمين الحكومية$m216$,'<<CR>>',chr(13))),
('law',155,2024,62,0,'7d0780874e85ecc6252d4355e6aa35c8','17e9c0c60be80ef551dc1921ba21a9a0',replace($m216$يصدر رئيس مجلس الوزراء بناء على اقتراح من مجلس إدارة الهيئة قرارا بتصفية الصندوق الحكومي في الحالات التالية:<<CR>>
1- إذا تبين من نتيجة فحص المركز المالي للصندوق أن أمواله لا تكفى للوفاء بالتزاماته.<<CR>>
2- إذا ثبت أن الصندوق لا يسير وفقًا لأحكام هذا القانون أو القرارات المنفذة له أو لنظامها الأساسي بحسب الأحوال. وينذر الصندوق بالمخالفات ويمنح مهلة ثلاثين يوما لإبداء دفاعه وفى حالة عدم تصحيح وضعه يصفى الصندوق. ويحدد القرار قواعد وإجراءات التصفية والجهة التي تئول إليها هذه الأموال، ويكون لها ما للصندوق من حقوق وتتحمل بالتزاماته.<<CR>>
(الفصل السادس) نشاط صناديق التأمين الخاصة أحكام عامة$m216$,'<<CR>>',chr(13))),
('law',155,2024,71,0,'99584b23b0db987d81b8241e24524365','eb5a9999079ea8975ce98eeadcd48486',replace($m216$تتكون موارد الصندوق مما يأتي:<<CR>>
1- اشتراكات الأعضاء.<<CR>>
2- مساهمة الجهة المنشأ بها الصندوق (إن وجدت).<<CR>>
3- عائد استثمار أموال الصندوق.<<CR>>
4- أية موارد أخرى يوافق عليها مجلس إدارة الصندوق وتقرها الهيئة.$m216$,'<<CR>>',chr(13))),
('law',155,2024,75,0,'703e944599661e05803bb1143cf5185f','fd4307feeaaf7f190d29774a3a931938',replace($m216$تتمتع الصناديق المسجلة وفقًا لأحكام هذا القانون بالمزايا الآتية: (أ) الإعفاء من رسوم الشهر والتوثيق التى يقع عبء أدائها عليها في عقود الملكية والرهن والعقود الخاصة بالحقوق العينية الأخرى،وكذلك من رسوم التصديق على التوقيعات. (ب) الإعفاء من رسوم الدمغة المفروضة على جميع العقود والمحررات والمطبوعات والسجلات.<<CR>>
(ج) الإعفاء من الضريبة على العقارات المبنية المملوكة للصندوق،والمستخدمة في أداء الأنشطة الأساسية الخاصة به. (د) إعفاء عائد وناتج التعامل في الأوراق المالية من ضريبة الدخل فيما عدا أذون الخزانة والسندات الحكومية كما يعفى إيراد القروض والودائع بجميع أنواعها المخصصة للصناديق من هذه الضريبة. كما تعفى اشتراكات العاملين فى صناديق التأمين الخاصة،والتي تنشأ طبقًا لأحكام هذا القانون من الدخول فى وعاء الضريبة على الدخل المقررة عليهم.$m216$,'<<CR>>',chr(13))),
('law',155,2024,76,0,'04116d1f5e259b3d082519d0c7336a9c','88920d5acbd8ae74516a69957c7faf6c',replace($m216$على الصندوق أن يحتفظ فى مركز إدارته بالوثائق والمكاتبات والسجلات الخاصة به،وتحدد الهيئة السجلات وما يقوم مقامها والتي يتعين على الصندوق إمساكها وما تحويه من بيانات والمدى الزمني للاحتفاظ بها. ولكل عضو من أعضاء الصندوق حق الاطلاع على سجلات الصندوق ومستنداته في حدود بياناته الشخصية. إدارة الصندوق (الجمعية العامة -مجلس الإدارة -مدير الاستثمار)$m216$,'<<CR>>',chr(13))),
('law',155,2024,82,0,'22902d0f830588c457b5fa5da0b82442','611cff45b022090e7b2566db2e333e1b',replace($m216$يكون اجتماع الجمعية العامة العادية للصندوق صحيحا بحضور الأغلبية المطلقة لأعضائه،فإذا لم يكتمل العدد أجل الاجتماع إلى جلسة أخرى تعقد خلال مدة أقلها ساعة وأقصاها خمسة عشر يوما من تاريخ الاجتماع الأول،ويكون الانعقاد في هذه الحالة صحيحا إذا حضره بأنفسهم عدد لا يقل عن خمسمائة عضو أو عن (10%) من عدد الأعضاء أيهما أقل. وتصدر قرارات الجمعية العامة العادية بالأغلبية المطلقة للأعضاء الحاضرين. ويجوز لعضو الجمعية العامة أن ينيب عنه كتابة على النموذج المعد لهذا الغرض من الهيئة عضوا آخر يمثله فى حضور الجمعية العامة على أن يعتمد ذلك من مدير الصندوق وقبل انعقاد الجمعية العامة بحد أقصى اليوم السابق على انعقاد الجمعية، ولا يجوز أن ينوب العضو عن أكثر من عضو واحد.$m216$,'<<CR>>',chr(13))),
('law',155,2024,83,0,'2e5ce08e7f737cb2099a3207719144c8','d841fc077f1af5c71eca8bfc36e949ac',replace($m216$يكون اجتماع الجمعية العامة غير العادية صحيحا بحضور ثلثي عدد أعضاء الصندوق،فإذا لم يكتمل النصاب يؤجل الاجتماع إلى جلسة أخرى تعقد خلال مدة أقلها ساعة وأقصاها خمسة عشر يوما من تاريخ الاجتماع الأول،ويكون الانعقاد في هذه الحالة صحيحا إذا حضره بأنفسهم عدد لا يقل عن ألف عضو أو عن (25%) من عدد الأعضاء أيهما أقل.<<CR>>
وتصدر قرارات الجمعية العامة غير العادية بأغلبية أصوات الأعضاء الحاضرين فيما عدا ما يتعلق بتصفية الصندوق أو إدماجه أو تحويل أمواله إلى صندوق آخر، فيشترط حضور ثلثي عدد أعضاء الصندوق أو ألف وخمسمائة عضو بأنفسهم أيهما أقل، ويصدر القرار بموافقة ثلاثة أرباع عدد أعضاء الصندوق الحاضرين.$m216$,'<<CR>>',chr(13))),
('law',155,2024,108,0,'43c5fc03cd640bae52ac84dc6a994aa1','7c1871c3f302459a4402be20baa36ee3',replace($m216$يلتزم رئيس وأعضاء مجلس إدارة الصندوق وجميع القائمين على الإدارة التنفيذية به بمراعاة كل القوانين واللوائح والقرارات المنظمة لصناديق التأمين الخاصة والنظام الأساسى للصندوق،وعليهم بذل العناية والحرص فى مباشرتهم لجميع الأعمال المتعلقة بالصندوق وفى إدارتهم لأمواله بغية تعظيم العائد على الأموال المستثمرة. (الفصل السابع) نشاط الاتحادات والأجهزة المعاونة ومكاتب التمثيل اتحاد التأمين$m216$,'<<CR>>',chr(13))),
('law',155,2024,116,0,'27eb6c463e31766ddec2460e6b4f9668','355057bfee28105d1cab484eb90da7c0',replace($m216$تنشأ اتحادات غير هادفة للربح للأشخاص المرخص لهم من الهيئة بمزاولة المهن التأمينية أو الأنشطة المرتبطة بالتأمين المسجلين بسجلات الهيئة،وتتمتع هذه الاتحادات بالشخصية الاعتبارية المستقلة،وتعد من أشخاص القانون الخاص، وتسجل في سجل خاص بالهيئة. ويجوز أن يضم الاتحاد أكثر من مهنة أو نشاط من الأنشطة المرتبطة بالتأمين، ولا يجوز إنشاء أكثر من اتحاد للمهنة أو النشاط الواحد.<<CR>>
ويكون تأسيس الاتحادات المشار إليها بالفقرة الأولى من هذه المادة من عدد لا يقل عن (51%) من الأشخاص المرخص لهم من الهيئة بمزاولة المهن التأمينية أو الأنشطة المرتبطة بها وفقًا لطبيعة نشاط الاتحاد شريطة ألا تقل حصتهم السوقية أو حجم أعمالهم عن (51%) من إجمالي حجم النشاط فى السوق المعنية، وتتولى الهيئة التأكد من توافر متطلبات التأسيس وقيام هؤلاء الأشخاص بتشكيل الجمعية التأسيسية لإعداد مشروع النظام الأساسي،وعرضه على الهيئة للنظر في اعتماده،ونشره بالوقائع المصرية وعلى الموقع الإلكتروني للهيئة. ويلتزم الأشخاص المرخص لهم من الهيئة بمزاولة المهن التأمينية أو الأنشطة المرتبطة بالتأمين المسجلون بسجلات الهيئة بالاشتراك في عضوية الاتحاد المعنى بالنشاط بمجرد تسجيله بالهيئة،ومراعاة نظامه الأساسي.$m216$,'<<CR>>',chr(13))),
('law',155,2024,124,0,'c18dd47ea226a05413c6aac59d524310','3fa47d7d2cbbaa95a428b2b3c9905e7a',replace($m216$لا يجوز للخبير الاكتوارى من الأشخاص الطبيعيين أن يزاول أعماله إلا بعد الحصول على ترخيص بذلك من الهيئة ويسجل فى السجل المعد لذلك بالهيئة، ويتم قيد اسمه وفقًا للشروط والقواعد والإجراءات التي يضعها مجلس إدارة الهيئة، والتي من بينها على وجه الخصوص ما يلى: أن يكون حاصلاً على إحدى الدرجات أو الدبلومات الآتية: (أ) درجة زميل أو رفيق من أحد المعاهد الآتية: معهد وكلية الخبراء الاكتواريون بالمملكة المتحدة. جمعية الخبراء الاكتواريون بالولايات المتحدة الأمريكية. (ب) درجة مهنية تالية لمرحلة الدراسة الجامعية الأولى فى العلوم الاكتوارية من إحدى جمعيات أو معاهد الخبراء الاكتواريين،معادلة للشهادات الواردة في البند (أ)، التي يعتمدها مجلس إدارة الهيئة.<<CR>>
ويسرى القيد لمدة خمس سنوات قابلة للتجديد،ويقدم طلب التجديد في سجل الخبراء الاكتواريين وفقًا للشروط والأوضاع التي يحددها مجلس إدارة الهيئة، على أن يتم اتخاذ إجراءات التجديد خلال ثلاثة الأشهر الأخيرة على الأقل من الموعد المذكور. ويؤدى طالب القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز عشرة آلاف جنيه للشخص الطبيعي،يسدد وفقًا لطرق السداد المقررة قانونًا.$m216$,'<<CR>>',chr(13))),
('law',155,2024,146,0,'9d832fb618a878d8eb40b866180db4a7','4cce8662f6fd395f8129be5c12ee83fb',replace($m216$يضع مجلس إدارة الهيئة الشروط والقواعد والضوابط التي تلتزم بها شركات التأمين لعمل المتدربين لديها بصفة مؤقتة بالجهاز الإنتاجى وتسجيلهم بالسجل المعد لهذا الغرض بالهيئة،ويحدد مجلس إدارة الهيئة الرسوم الواجب سدادها بهذا السجل بما لا يجاوز نصف الرسم المقرر بالنسبة لوسطاء التأمين،تسدد وفقًا لطرق السداد المقررة قانونًا.<<CR>>
(الفصل التاسع) أحكام ختامية$m216$,'<<CR>>',chr(13))),
('law',155,2024,158,0,'5d1f5f07c69c49f328816196b8a559c8','e85002d914f423d56ea550ec787580d0',replace($m216$يشترط لإصدار الترخيص المنصوص عليه فى المادة (157) من هذا القانون توافر الشروط التي يضعها مجلس إدارة الهيئة،وعلى الأخص منها: 1- أن يكون طالب الترخيص شركة مساهمة مصرية،وألا يقل رأسمالها المصدر والمدفوع عن الحد الذي يقرره مجلس إدارة الهيئة،وبما لا يقل عن الحد الوارد بأحكام هذا القانون بحسب نوع الشركة وغرضها. 2- أن يتفق هيكل ملكية الشركة مع ضوابط هيكل ملكية الشركات الخاضعة لأحكام هذا القانون.<<CR>>
3- أن يتوافر فى القائمين على إدارة الشركة الخبرة والكفاءة اللازمة لعملها على النحو الذي ينص عليه هذا القانون وما يصدر به قرار عن مجلس إدارة الهيئة. 4- أن يتوافر لدى الشركة التجهيزات والبنية التكنولوجية وأنظمة المعلومات اللازمة لمباشرة النشاط وفقًا للمتطلبات التى تحددها الهيئة. شركة ة ال اطر وإدارة وحوكم ة والمخ ة الداخلي ط الرقاب اءة خط - 5 كف والاستراتيجية والسياسة التى ينوى اتباعها فى تصريف شئونه. 6- الالتزام ببدء العمل للنشاط خلال ستة أشهر على الأكثر من تاريخ الحصول على الترخيص،ويجوز بموافقة الهيئة مدها لمدة ستة أشهر أخرى،وذلك فى ضوء المبررات التى تقدمها الشركة وتقبلها الهيئة. وتلتزم شركات التأمين وإعادة التأمين،بالإضافة لما تقدم بموافاة الهيئة كالآتى: (أ) شهادة من أحد البنوك المسجلة لدى البنك المركزى المصرى تثبت أن الشركة قد أودعت لديه فى جمهورية مصر العربية أموالاً لا تقل قيمتها عن خمسمائة ألف جنيه عن كل فرع من فروع التأمين التى ترغب الشركة فى مزاولتها، وبحد أقصى ثلاثة ملايين جنيه لجميع هذه الفروع،ولا يجوز للشركة التصرف فى هذه الأموال إلا بموافقة الهيئة. (ب) نماذج الوثائق التى تصدرها الشركة عن كل فرع من فروع التأمين المطلوب الترخيص لها بمزاولته والمزايا والقيود والشروط والأسعار الخاصة بهذه الوثائق. فإذا كان نشاط الشركة مباشرة إحدى العمليات المنصوص عليها فى البند أولاً من الفقرة الأولى من المادة (2) من هذا القانون،فيجب أن يرفق بهذه الوثائق: شهادة من أحد الخبراء الاكتواريين المقيدين فى السجل المعد لذلك بالهيئة بأن أسس أسعار هذه العمليات والمزايا والقيود التى تخولها الوثائق سليمة وصالحة للتنفيذ. جدول يحدد قيمة الاسترداد أو التخفيض،ويجب أن ينص على هذا الجدول فى كل وثيقة من الوثائق المذكورة. ترتيبات إعادة التأمين وطبيعتها. أية مستندات أخرى يحددها مجلس إدارة الهيئة للترخيص لها بمزاولة النشاط.$m216$,'<<CR>>',chr(13))),
('law',155,2024,164,0,'d892e1a471545b8a2720bd7e3355e437','a5ce909f04d868a38180576f1f4b2ac8',replace($m216$على كل شخص طبيعي أو اعتبارى وأطرافه المرتبطة يتملك ما يزيد على (5%) وأقل من (10%) من أسهم رأس المال المصدر أو من حقوق التصويت لأى شركة تأمين أو إعادة تأمين أن يخطر الهيئة بذلك خلال خمسة عشر يوما على الأكثر من تاريخ إتمام التملك طبقًا للنموذج الذي تعده الهيئة لهذا الغرض.$m216$,'<<CR>>',chr(13))),
('law',155,2024,166,0,'f07465703c58e5fe9728a96b89e9858c','d8b1f82d7f8c367c114ce700772f0151',replace($m216$إذا تملك شخص وأطرافه المرتبطة بالميراث أو الوصية (10%) فأكثر من رأسمال الشركة المصدر أو من حقوق التصويت ولم يطلب استمرار تملكه طبقًا لحكم المادة (167) من هذا القانون،فلا يكون له الحق فى التصويت بالنسبة التي تجاوز العشرة في المائة،ويتعين عليه أن يوفق أوضاعه طبقًا للشروط والإجراءات التي تضعها الهيئة خلال مدة لا تجاوز سنتين من تاريخ أيلولة هذه الزيادة إليه،ويجوز للهيئة مدها لفترة مماثلة حال تعثر بيع الأسهم. ويسرى عليه حال عدم توفيق أوضاعه خلال هذه المدة حكم الفقرة الثالثة من المادة (165) من هذا القانون.$m216$,'<<CR>>',chr(13))),
('law',155,2024,167,0,'4e28971d8168e2b623ecc9ca78b4ab9a','e496481cdfbf03e24aa2142aa1d2b4da',replace($m216$يجب أن يقدم طلب الموافقة على تملك نسبة (10%) أو ما يزيد على تلك النسبة من رأس المال المصدر للشركة أو من حقوق التصويت إلى الهيئة،قبل موعد إتمام التملك بستين يوما على الأقل،وذلك على النموذج المعتمد من الهيئة ويرفق بالطلب تقرير يبين ملاءته المالية وسبب الرغبة في تملك الأسهم والأهداف التي يرمى مقدم الطلب إلى تحقيقها منه وخططه فى إدارة الشركة والسياسة التي ينوي اتباعها في تصريف شئونها ونسبة مساهماته وأطرافه المرتبطة فى أى شركة أو منشأة أخرى. فإذا كان التملك بطريق الميراث أو الوصية أو نتيجة لتخصيص أسهم مطروحة في اكتتاب عام،يتعين تقديم طلب استمرار التملك خلال ثلاثين يوما من تاريخ علم الطالب بما آل إليه بطريق الميراث أو الوصية أو الاكتتاب العام. ويتم النشر عن الطلب المنصوص عليه فى الفقرتين الأولى والثانية من هذه المادة على الموقع الإلكترونى الذى تخصصه الهيئة لهذا الغرض وذلك خلال ثلاثين يوما من تاريخ تقديمه على النموذج الذي تعده الهيئة لهذا الغرض. ولكل ذى مصلحة أن يتقدم إلى الهيئة باعتراض مسبب على الطلب خلال خمسة عشر يوما من تاريخ النشر.$m216$,'<<CR>>',chr(13))),
('law',155,2024,169,0,'9bcee276b4530ad1fb84b8450598779c','4566865bf18451d3422ddefb09abaa86',replace($m216$يخطر صاحب الشأن بقرار قبول أو رفض الطلب المشار إليه في المادة (167) من هذا القانون خلال ستين يوما من تاريخ تقديمه،بكتاب موصى عليه مصحوب بعلم الوصول أو بأية وسيلة أخرى. وتكون الموافقة سارية لمدة ستة أشهر من تاريخ إبلاغ طالب التملك بها، وإلا اعتبرت كأن لم تكن،ويجوز لمجلس إدارة الهيئة مد هذه المهلة لفترة مماثلة. وفى حالة صدور قرار برفض استمرار تملك الطالب للنسبة التي آلت إليه بطريق الميراث أو الوصية أو نتيجة لتخصيص أسهم مطروحة في اكتتاب عام أو بأي وسيلة أخرى،تتم مطالبته من الهيئة بالتصرف فيها خلال سنتين من تاريخ إخطاره بقرار الرفض إذا كان التملك بالميراث أو الوصية وخلال ثلاثة أشهر إذا كان التملك عن طريق الاكتتاب العام. ويجوز للهيئة مد هذه المهلة لمدة أخرى مماثلة،ويسرى في شأنه حال عدم تصرفه فيها خلال هاتين المدتين حكم الفقرة الثالثة من المادة (165) من هذا القانون.<<CR>>
(الفصل الثالث) الرقابة والإشراف شركات التأمين وإعادة التأمين إدارة وحوكمة الشركات$m216$,'<<CR>>',chr(13))),
('law',155,2024,178,0,'c218043e34dcba734ef16106b16cd62a','7122b43cc0eae49e242a57cab56437b5',replace($m216$يكون لحملة الوثائق وللمستفيدين منها التى تبرمها الشركة وتنفذها فى جمهورية مصر العربية امتياز على الأموال المخصصة طبقًا للمادتين (174، 175) من هذا القانون يأتى فى المرتبة بعد الامتياز المقرر فى الفقرة (أ) من المادة (1141) من القانون المدنى،وتؤشر الجهة المختصة بالشهر والتوثيق،بناء على طلب الهيئة، بهذا الامتياز على هامش كل تسجيل أو قيد خاص بهذه الأموال على أن تخطر الهيئة بكل تأشير يتم.$m216$,'<<CR>>',chr(13))),
('law',155,2024,186,0,'7571929659b0e70303995f6d8248bd44','7a671aeac98621e7fe03384b07fabe09',replace($m216$على الشركة أن تقدم للهيئة كل سنة مالية البيانات والحسابات اللازمة، وذلك فى الموعد الذى يحدده مجلس إدارة الهيئة،وعلى الأخص منها: (أ) ملخص اتفاقيات إعادة التأمين. (ب) بيان بأموال الشركة المخصصة الواجب الاحتفاظ بها فى جمهورية مصر العربية وفقًا لأحكام هذا القانون مؤيد بالمستندات التى تطلبها الهيئة. وتعد هذه البيانات طبقًا للنماذج التى تصدرها الهيئة وتشمل جميع العمليات التى تقوم بها الشركة فى جمهورية مصر العربية وفى الخارج كل على حدة. ويجب أن تكون هذه البيانات التى تقدم طبقًا لأحكام هذا القانون موقعة من الممثل القانونى للشركة ومن مديرها المالى. ويجب أن يرفق بهذه البيانات تقرير عن أعمال الشركة فى جمهورية مصر العربية عن تلك السنة.$m216$,'<<CR>>',chr(13)));
INSERT INTO m216_fix VALUES
('law',155,2024,194,0,'47d799dad3ca0ef3cf541f0f9611033b','4ab927ffa430e191ba1fde6ac1f85369',replace($m216$تلتزم شركة التأمين التكافلى التى تعمل بنموذج المضاربة بما يلى: 1- توزيع الفائض التأمينى على المشتركين بما لا يقل عن (50%) وذلك وفقًا لآليات التوزيع الواردة بالنظام الأساسى للشركة بعد أخذ رأى لجنة الرقابة الشرعية. 2- تجنيب الفائض التأمينى الخاص بالمشتركين فى حساب خاص،ويراعى فيه توزيع الجزء الذى لم تتمكن الشركة من توزيعه على المشتركين فى أوجه الخير أو التبرع الذى تحدده الشركة وفقًا للضوابط والقواعد التى يصدربها قرار عن مجلس إدارة الهيئة. 3- مراعاة الإعلان المسبق بمنتجات تلك الشركات عن أسس ومعايير التكافل وأبرزها نسب توزيعات الفائض وآلياته على المشتركين. 4- عدم الإخلال بالمخصصات الفنية الواجب على الشركة الاحتفاظ بها وفقًا لأحكام المادة (174) من هذا القانون،وعلى الشركة تكوين احتياطى لتغطية عجز حساب التكافل.$m216$,'<<CR>>',chr(13))),
('law',155,2024,195,0,'073d95961f3751b6f96cddf07cef143b','d36c3e9ad72bb3f74e8a9a22a8e9cb68',replace($m216$فى حالة وجود عجز فى حساب التكافل يتعين على مساهمى الشركة تقديم قرض حسن لهذا الحساب،ويعتبر الالتزام بتقديم القرض المشار إليه التزاما شاملاً حده الأقصى (50%) من مجموع حقوق المساهمين فى الشركة،ويكون استرداد هذا القرض من الفائض أو الفوائض التى قد تتحقق فى الفترات اللاحقة،وفى حالة عدم تقديم المساهمين لهذا القرض خلال ثلاثين يوما من تاريخ إنذار الشركة بمعرفة الهيئة يتم العرض على مجلس إدارة الهيئة لاتخاذ أى من التدابير الواردة بأحكام المادة (201) من هذا القانون.$m216$,'<<CR>>',chr(13))),
('law',155,2024,197,0,'84ad2c1c3af409afffd1ccabd460ef65','35724595064c06bea879463d1b841612',replace($m216$لا يجوز تحويل وثائق التأمين التكافلى إلا إلى شركة تأمين تكافلى أخرى تمارس نفس نوع وفروع التأمين التكافلى. ولا يجوز دمج شركة التأمين التكافلى إلا بشركة تأمين تكافلى أخرى تمارس نوع التأمين ذاته. ويجوز لكل من شركات التأمين التجارى تعديل نظامها الأساسى للعمل وفقًا لصيغة التأمين التكافلى،كما يجوز لشركات التأمين التكافلى تعديل نظامها الأساسى للعمل وفقًا لصيغة التأمين التجارى،على أن تقدم طلبا بذلك إلى الهيئة حسب النموذج الذى تعتمده،على أن يتضمن خطة توضح الإجراءات التى ستتبعها الشركة الراغبة فى التعديل لتوفيق أوضاعها وفقًا للضوابط والإجراءات الصادرة عن مجلس إدارة الهيئة،بشرط ألا تتجاوز فترة الخطة مدة سنتين من تاريخ موافقة الهيئة عليها وتكون قابلة للتمديد لمدة أخرى بقرار من الهيئة إذا اقتضت الضرورة ذلك. وفيما عدا ما تقدم من نصوص فى هذا الفصل،تخضع شركة التأمين التكافلى وإعادة التأمين التكافلى لسائر الأحكام الواردة فى هذا القانون بشأن شركة التأمين وإعادة التأمين وذلك فى كل ما لم يرد بشأنه نص خاص. (الفصل الرابع) صندوق ضمان حملة الوثائق$m216$,'<<CR>>',chr(13))),
('law',155,2024,198,0,'a8f3150ca345fbc7b9f121893dc48c16','f596f3b718342af30575a4d7e835282f',replace($m216$صندوق ضمان حملة الوثائق والمستفيدين منها،شخص اعتبارى من أشخاص القانون الخاص له ميزانية مستقلة ويخضع لإشراف الهيئة،ومقره فى مدينة القاهرة، ويهدف إلى تعويض حملة الوثائق والمستفيدين منها نتيجة لعدم قدرة الشركة على الوفاء بالتزاماتها. ولرئيس مجلس الوزراء بعد أخذ رأى الهيئة تعديل النظام الأساسى للصندوق الصادر قبل العمل بأحكام هذا القانون.<<CR>>
(الفصل الخامس) التحول الرقمى بقطاع التأمين$m216$,'<<CR>>',chr(13))),
('law',155,2024,200,0,'f9d73c6f9fedf071d2039813f6b23a32','913478cb519e16262395f91be8173e3e',replace($m216$مع عدم الإخلال بحكم المادة (67) من هذا القانون،يجب على جميع الأشخاص الاعتبارية المخاطبة بأحكام هذا القانون أن تنشئ لها موقعا إلكترونيا مرخصا من الهيئة يحتوى على الإفصاح والشفافية الكافية للمتعاملين معها عن أحكامها،وخاصة الغرض من إنشائها ونوع وصيغة التأمين الذى تزاوله وأهم القرارات الصادرة عن إدارتها وذلك وفقًا للضوابط التى يضعها مجلس إدارة الهيئة. (الفصل السادس) الإجراءات والتدابير الرقابية$m216$,'<<CR>>',chr(13))),
('law',155,2024,201,0,'df577b674bc287651b7fc10e12cabec4','3e5bf3daaaf1234d607f36a938a75668',replace($m216$يجوز لمجلس إدارة الهيئة تحقيقًا لاستقرار السوق،أو حماية لحقوق المتعاملين مع الشركة من حملة الوثائق والمستفيدين منها،أو فى حالة تعرض الشركة لمشكلات مالية تؤثر على مركزها المالى،إلزام الشركة بتعزيز ملاءتها المالية وفقًا لجدول زمنى محدد،وعلى الشركة الالتزام بقرار مجلس إدارة الهيئة الصادر فى هذا الخصوص وإلا جاز لمجلس إدارة الهيئة اتخاذ تدبير أو أكثر من التدابير الآتية: 1- دعوة مجلس إدارة الشركة إلى الانعقاد للنظر فى أمر المخالفات المنسوبة إلى الشركة واتخاذ اللازم نحو إزالتها ويحضر اجتماع مجلس الإدارة فى هذه الحالة ممثل أو أكثر عن الهيئة.<<CR>>
2- تعيين عضو مراقب فى مجلس إدارة الشركة للمدة التى يحددها مجلس إدارة الهيئة ويكون له المشاركة فى مناقشات المجلس وإبداء الرأى فيما يعرض من موضوعات دون أن يكون له صوت معدود. 3- تجنيب الفائض القابل للتوزيع على المساهمين أو جزء منه لدعم المركز المالى للشركة. 4- إلزام الشركة بإعادة هيكلة نشاط أو أكثر من أنشطتها. 5- تقييد قبولها عمليات جديدة أو تجديدها عمليات قائمة أو كليهما معا لمدة محددة بالنسبة لكل أو بعض فروع التأمين المرخص لها بمزاولتها. 6- تنحية واحد أو أكثر من القائمين على الإدارة التنفيذية بالشركة. 7- إلزام الشركة بزيادة رأسمالها المدفوع بالقدر الذى تراه الهيئة لتدعيم قدرتها على الوفاء بالتزاماتها. 8- عزل عضو أو أكثر من أعضاء مجلس الإدارة وتعيين مفوض لإدارة الشركة بصفة مؤقتة لحين تعيين مجلس إدارة جديد بالأداة المقررة قانونًا. 9- تحويل وثائقها بما لها من حقوق وما عليها من التزامات لشركة تأمين أخرى. 10- إدماج الشركة فى شركة تأمين أخرى. 11- إلغاء ترخيص الشركة المتعثرة. (الفصل السابع) إنهاء النشاط تحويل الوثائق ووقف العمل وإلغاء الترخيص تحويل الوثائق$m216$,'<<CR>>',chr(13))),
('law',155,2024,204,0,'f11d1d5ba0f9876bae05c5652e43e0c3','40cd1691e2f17928009ff9097f51b4e7',replace($m216$يجوز للهيئة إلغاء الترخيص بمزاولة النشاط كليا أو جزئيا فى أى من الأحوال الآتية:<<CR>>
1- إذا كانت الشركة قد تحصلت على الترخيص بصورة تخالف القانون.<<CR>>
2- إذا دأبت الشركة على مخالفة أحكام هذا القانون أو القرارات المنفذة لها. 3- إذا ثبت للهيئة أن الشركة غير قادرة على الوفاء بالتزاماتها. 4- إذا ثبت للهيئة أن الشركة تهمل باستمرار فى تنفيذ المطالبات المستحقة التى تقدم إليها أو تتكرر منها المنازعة دون وجه حق فى مطالبات جدية. 5- إذا نقص رأس المال المدفوع عن الحد الأدنى المقرر فى المادة (162) من هذا القانون ولم تقم الشركة باستكماله رغم مطالبتها بذلك. 6- إذا لم تحتفظ الشركة فى جمهورية مصر العربية بالأموال الواجب تخصيصها طبقًا لحكم المادة (175) من هذا القانون أو إذا لم تقم باستكمالها خلال سنة من تاريخ مطالبتها بذلك. 7- إذا تكرر امتناع الشركة عن تقديم دفاترها ومستنداتها للمراجعة أو الفحص الذى تقوم به الهيئة أو مراقبو الحسابات أو رفضت إعطاء الكشوف والبيانات الواجب تقديمها طبقًا للقانون رغم مطالبتها كتابة أكثر من مرة على مدى ثلاثة أشهر. 8- إذا صدر قرار بالموافقة على تحويل وثائق الشركة مع الالتزامات المترتبة عليها إلى شركة أخرى عن كل العمليات التى زاولتها فى جمهورية مصر العربية طبقًا لحكم المادة (202) من هذا القانون. 9- إذا توقفت الشركة عن مزاولة نشاطها فى جمهورية مصر العربية وحررت أموالها طبقًا للمادة (203) من هذا القانون. 10- إذا صدر حكم بإشهار إفلاس الشركة. 11- إذا خالفت الشركة شرطًا من شروط الترخيص لها بمزاولة النشاط ولم تقم بتصحيح المخالفة على الرغم من مطالبتها بذلك خلال فترة يحددها مجلس إدارة الهيئة. ولا يصدر قرار إلغاء الترخيص بمزاولة النشاط إلا بعد إخطار الشركة بكتاب مسجل مصحوبا بعلم الوصول لتقدم أوجه دفاعها كتابة خلال ثلاثين يوما من تاريخ الإخطار،ويتم إلغاء الترخيص بمزاولة النشاط كليا أو جزئيا بقرار من مجلس إدارة الهيئة وينشر على الموقع الإلكترونى الذى تخصصه الهيئة لهذا الغرض. ولا ينسحب أثر إلغاء الترخيص بمزاولة النشاط جزئيا إلا إلى العمليات المنصوص عليها فى القرار الصادر به.<<CR>>
وفى جميع الأحوال،لا يجوز للشركة التى صدر فى شأنها قرار إلغاء الترخيص بمزاولة النشاط كليا أن تتصرف فى أموالها والضمانات المقدمة منها إلا بعد اتباع الإجراءات الصادرة عن مجلس إدارة الهيئة نفاذًا لأحكام المادة (203) من هذا القانون، ويترتب على القرار الصادر بإلغاء الترخيص بمزاولة النشاط وقف الشركة عن مباشرة النشاط فى فروع التأمين المنصوص عليها فيه. ويجوز لرئيس مجلس إدارة الهيئة أن يسمح للشركة بمباشرة العمليات القائمة وقت إلغاء الترخيص بمزاولة النشاط بالشروط التى يعينها لذلك،كما يجوز له أن يقرر تصفية أعمال الشركة. وتجرى التصفية طبقا للقواعد التى يقررها مجلس إدارة الهيئة بما يضمن الوفاء بالتزامات الشركة وذلك تحت إشراف لجنة من ثلاثة أعضاء يعينهم رئيس المجلس. (الفصل الثامن) أحكام ختامية$m216$,'<<CR>>',chr(13))),
('law',155,2024,214,0,'050b805d4b7dd4bf82b0f4f8fdb1b853','ac952797af8b8016181bbc74b532f23d',replace($m216$تشكل لجنة أو أكثر لنظر التظلمات التى يقدمها أصحاب الشأن من القرارات الإدارية الصادرة تطبيقًا لأحكام هذا القانون،ويصدر بتشكيل كل لجنة قرار من مجلس إدارة الهيئة،وتكون برئاسة أحد نواب رئيس مجلس الدولة وعضوية اثنين من مستشارى مجلس الدولة يختارهما رئيس المجلس،وممثل عن الهيئة يختاره رئيسها،وعضو من ذوى الخبرة يختاره مجلس إدارة الهيئة،ويكون للمتظلم الحضور أمام اللجنة بنفسه أو من يمثله. ويكون التظلم من القرار أمام هذه اللجنة خلال ثلاثين يوما من تاريخ صدور القرار أو انتهاء الأجل الخاص بصدوره،على أن تصدر اللجنة قرارها فى التظلم فى ميعاد لا يجاوز ثلاثين يوما من تاريخ استيفاء المستندات والبيانات المطلوبة، ويكون قرارها نهائيا ونافذًا وملزما لأطرافه. ولا تقبل الدعوى التى ترفع إلى المحكمة المختصة إلا بعد اللجوء إلى اللجنة المشار إليها والبت فى التظلم.<<CR>>
ويترتب على تقديم التظلم إلى اللجنة وقف المدد المقررة قانونًا لسقوط أو تقادم الحقوق أو لرفع الدعوى،وذلك حتى انقضاء ميعاد البت فى التظلم. ويشمل قرار تشكيل اللجنة اختصاصاتها ومكافآت أعضائها وإجراءات النظر فى التظلم والبت فيه ومواعيد تلك الإجراءات. ويلتزم المتظلم بسداد رسم للتظلم يصدر بتحديد ضوابطه قرار من رئيس مجلس إدارة الهيئة بما لا يجاوز مبلغ عشرين ألف جنيه،ويرد هذا الرسم إلى المتظلم حال إلغاء القرار خلال ثلاثين يوما على الأكثر من تاريخ صدور الإلغاء. (الفصل الثاني) العقوبات$m216$,'<<CR>>',chr(13))),
('law',155,2024,224,0,'a265dcbf246bf3186c25b32b13a7226a','777e265b3a13e08220287cca47c98d02',replace($m216$تسرى أحكام المادة السادسة عشرة من قانون تنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية رقم 10 لسنة 2009 على الجرائم التى ترتكب بالمخالفة لأحكام هذا القانون والقرارات الصادرة نفاذًا له.<<CR>>
جدول الرسوم الملحق بالقانون الرسم الإجراءات المقرر جنيه - 1 يحصل مبلغ 100 جنيه من المؤمن لهم نظير اطلاعهم على بيانات وثائقهم، أو حصولهم على نسخة إضافية منها بناء على طلبهم. 2- تكون رسوم الاطلاع واستخراج الصور أو الشهادات أو المستخرجات بالهيئة كما يلى: (أ) الاطلاع على الأوراق والبيانات: 50 عن كل شركة من الشركات الخاضعة للقانون أو اتحاد............................... (ب) طلب صورة أو شهادات أو مستخرجات من الأوراق والبيانات الواجب تقديمها طبقًا للقانون أو من القرارات الصادرة تنفيذًا له عن الصفحة الواحدة.................. (ج) طلب شهادات أو مستخرجات من السجلات المنصوص عليها فى القانون: عن كل شركة من الشركات الخاضعة للقانون....................................... عن كل خبير أو وسيط من الخبراء أو الوسطاء المنصوص عليهم فى المواد )، 60 (71، 67، 64 من هذا القانون،وذلك بالنسبة لكل شهادة أو مستخرج............. 50 - 3 طلب الترخيص بإجراء السحب بالنسبة لعمليات التأمين على الحياة وتكوين الأموال.<<CR>>
4- النشر على الموقع الإلكترونى الذى تحدده الهيئة: 150 ) أ ( قرار تسجيل شركة التأمين. )ب( قرار تعديل بيانات التسجيل. )ج( القرار الصادر بتحويل وثائق الشركة والتزاماتها إلى شركة أخرى. )د ( ما يحدده مجلس إدارة الهيئة من قرارات أخرى واجبة النشر.<<CR>>
ولمجلس إدارة الهيئة تعديل الرسوم المقررة فى هذا الجدول بما لا يجاوز عشر أمثالها.<<CR>>
