 4- نظم الضبط الداخلى المتبعة فى تحديد العمليات غير العادية، أو العملاء<<CR>>
 المشتبه فيهم، ووضعها تحت نظر مسئول مكافحة غسل الأموال وتمويل الإرهاب .<<CR>>
 5- وضع إجراءات للكشف عن أسماء جميع العملاء والمستفيدين الحقيقيين وأى<<CR>>
أطراف أخرى مطلوب الكشف عنهم على القوائم السلبية فى بداية التعامل وبشكل<<CR>>
 دورى واتخاذ الإجراءات اللازمة فى هذا الشأن .<<CR>>
 6- وضع إجراءات داخلية للتحقق من الالتزام التام بأحكام إجراءات العناية<<CR>>
 الواجبة العملاء الصادرة عن الوحدة .<<CR>>
 7- الالتزام بالتسجيل على الموقع الالكترونى للوحدة ومتابعة ما يرد من تحديثات<<CR>>
