 فور وقوعها .<<CR>>
 10- النظم التى تكفل قيام المراجع الداخلى أو لجان المراجعة، بحسب الأحوال ،<<CR>>
بالتنسيق مع المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب، بفحص<<CR>>
النظم الموضوعة للتأكد من كفاءتها وفعاليتها فى مكافحة عمليات غسل الأموال وتمويل<<CR>>
 الإرهاب، واقتراح ما يلزم من إجراءات وقائية أو ما تحتاجه من تحديث وتطوير .<<CR>>
 11- قواعد الاحتفاظ بالمستندات والسجلات التى يجب على الأشخاص<<CR>>
 الاعتبارية المخاطبين بأحكام هذا القرار إمساكها وتحديد طرق الاحتفاظ بها .<<CR>>
 12- وضع خطط وبرامج تدريب العاملين بهدف توعيتهم ورفع كفاءتهم فيما<<CR>>
