باللائحة التنفيذية لقانون مكافحة غسل الأموال، وينبغى على المخاطبين بأحكام هذا<<CR>>
 القرار القيام بما يلى :<<CR>>
 1- الالتزام بالتعليمات التى تصدرها الوحدة بشأن متطلبات الإخطار عن<<CR>>
 العمليات المشتبه فيها .<<CR>>
 2- موافاة الوحدة على الفور بأى بيانات أو معلومات تتاح لهم أو يتحصلوا عليها<<CR>>
تكون من شأنها تعزيز أو نفى كل أو بعض أسباب ودواعى الاشتباه التى اشتملت<<CR>>
عليها إخطارات الاشتباه الذى سبق إرسالها للوحدة، مع إرفاق صور المستندات<<CR>>
 المؤيدة لها (إن وجدت) .<<CR>>
 3- اتخاذ الإجراءات التى تضمن الاستفادة من التغذية العكسية التى يتلقوها من<<CR>>
الوحدة مما ينعكس إيجابا على إخطارات الاشتباه المرسلة للوحدة ونظم وإجراءات<<CR>>
 مكافحة غسل الأموال وتمويل الإرهاب لديهم .<<CR>>
 4- أن يتوافر لديهم إجراءات ونظم تمكن العاملين لديهم من تحديد كافة العمليات<<CR>>
التى يشتبه فى أنها تشكل متحصلات أو تتضمن غسل أموال أو تمويل إرهاب بما فى<<CR>>
ذلك محاولات إجراء هذه العمليات، بغض النظر عن قيمتها، وتضمن الإخطار<<CR>>
الفورى داخليا للمدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب عن تلك<<CR>>
 العمليات من خلال قنوات واضحة ومؤمنة تمكن العاملين من ذلك .<<CR>>
 5- أن يكون لديهم إجراءات ونظم تضمن سرعة فحص كافة تقارير الاشتباه<<CR>>
الداخلية، وتضمن توفير التغذية العكسية والإرشادات والتعليمات بشأنها لرفع جودتها .<<CR>>
 6- التقييم الدورى للإجراءات والنظم المشار إليها فى البند السابق وقنوات تلقى<<CR>>
تقارير الاشتباه الداخلية للإخطار الفورى عنها وسرعة فحصها وتوفير التغذية العكسية<<CR>>
والإرشادات والتعليمات بشأنها، واتخاذ ما يلزم على وجه السرعة لزيادة فعاليتها<<CR>>
