على المخاطبين بأحكام هذا القرار مراعاة المؤشرات الاسترشادية الآتية<<CR>>
بحد أدنى عند التعرف على العمليات المشتبه فى أنها تتضمن غسل أموال<<CR>>
 أو تمويل إرهاب :<<CR>>
 مؤشرات عامة لكافة الأنشطة :<<CR>>
 1- العملاء الذين يمتنعون عن توفير معلومات كافية، أو يقدمون معلومات<<CR>>
غير صحيحة، سواء كانت شخصية أو عن النشاط أو عن المستفيدين الحقيقيين<<CR>>
من التعامل على الحساب، أو يمتنعون عن التوقيع على نموذج اعرف عميلك<<CR>>
أو التردد فى الإدلاء بالبيانات التفصيلية الواردة به، أو عدم قدرتهم على تجديد<<CR>>
 سريان بطاقة الرقم القومى .<<CR>>
 2- العملاء الذين يقومون بتقديم وثائق هوية بها شبهة تزوير .<<CR>>
 3- العملاء الذين يواجهون صعوبة فى وصف طبيعة نشاطهم أو يفتقرون إلى<<CR>>
 المعلومات العامة فيما يتعلق بذلك النشاط .<<CR>>
 4- العملاء الذين يهتمون -بصورة غير عادية -بالاستفسار عن النظم المطبقة<<CR>>
للتعرف على العمليات غير العادية أو معايير الاشتباه أو إجراءات الإخطار الخاصة<<CR>>
 بالعمليات المشتبه فيها .<<CR>>
 5- التغير المفاجئ فى مستوى معيشة أحد موظفى المؤسسة دون مبرر واضح .<<CR>>
 6- العمليات التى تتم من خلال جهات محلية أو أجنبية لا تهدف للربح<<CR>>
بما لا يتماشى من حيث النمط أو الحجم مع غرض ونشاط تلك الجهات وخاصة إذا<<CR>>
