 وجود مبرر واضح من العميل .<<CR>>
 2- العمليات التى تتم بمبالغ كبيرة بما لا يتناسب مع نشاط العميل أو مستوى دخله .<<CR>>
 3- اتجاه العميل نحو العمليات أو الصفقات التى تشير إلى افتقاره للحس<<CR>>
الاستثمارى، وعلى سبيل المثال عدم الاهتمام بالحصول على أفضل سعر للورقة<<CR>>
 المالية المتعامل عليها بيعا وشراء.<<CR>>
 4- العملاء الذين يبدون لا مبالاة تجاه المخاطر أو العمولات أو غيرها من<<CR>>
 تكاليف العمليات على الأوراق المالية .<<CR>>
 5- تكرار طلبات تحويل مبالغ من حساب العميل إلى حسابات أخرى بالشركة<<CR>>
 دون مبرر واضح .<<CR>>
 6- العمليات المتكررة التى لا يتناسب مجموعها خلال فترة زمنية معينة مع<<CR>>
 نشاط العميل .<<CR>>
 7- عدم اهتمام العميل فى معظم الأحيان بما تقدمه الشركة من نصائح استثمارية .<<CR>>
 8- العمليات التى يتم تمويلها عن طريق شيكات مصرفية أو أية أدوات مالية<<CR>>
 قابلة للتداول بصفة متكررة ودون مبرر واضح .<<CR>>
 9- تعمد العميل القيام بعمليات متعددة تقل قيمتها عن الحد المقرر من قبل الهيئة<<CR>>
 للسماح بالتعامل النقدى وذلك بقصد تجنب التعامل من خلال البنوك .<<CR>>
 مؤشرات خاصة بالتأمين :<<CR>>
 1- العملاء الذين يبدون لا مبالاة تجاه سعر التأمين أو العمولات أو غيرها<<CR>>
 من تكاليف التغطية التأمينية .<<CR>>

 2- عدم إبداء طالب التأمين اهتماما بالتغطيات المشمولة بالوثيقة مع إبداء اهتمام<<CR>>
 كبير بتاريخ الإلغاء المبكر للعقد .<<CR>>
 3- شراء وثائق تأمين أو طلب زيادة قيمتها بمبالغ كبيرة بما لا يتناسب مع نشاط العميل .<<CR>>
 4- تكرار شراء وثائق تأمين بمبالغ لا يتناسب مجموعها خلال فترة زمنية معينة<<CR>>
 مع نشاط العميل .<<CR>>
 5- طلب العميل تغطية تأمينية خارج نطاق النشاط المعتاد له .<<CR>>
 6- توافر معلومات تفيد قيام طالب التأمين بالحصول على وثائق تأمينية من عدة<<CR>>
 شركات لذات التغطية التأمينية .<<CR>>
 7- التعاقد على وثيقة بقسط وحيد أو بمبلغ كبير بما يخالف نمط التعاملات<<CR>>
 السابقة للعميل .<<CR>>
 8- طلب العميل زيادة قيمة وثيقة التأمين بمبلغ كبير يسدد على دفعة واحدة .<<CR>>
 9- التعاقد على وثائق بمبالغ كبيرة وطلب استردادها أو تغيير المستفيد بعد فترة<<CR>>
 قصيرة من التعاقد دون مبرر واضح .<<CR>>
 10- طلب العميل اقتراض الحد الأقصى من قيمة وثيقة ذات قسط وحيد بعد فترة<<CR>>
 قصيرة من التعاقد وسداد قيمتها دون مبرر واضح .<<CR>>
 11- سداد قيمة أو أقساط وثيقة التأمين بواسطة تحويلات من أطراف أجنبية<<CR>>
 أو طلب استرداد وتحويل قيمتها لأطراف أجنبية .<<CR>>
 12- تغيير المستفيدين المحددين فى وثيقة التأمين بحيث يتم تضمنين أشخاص<<CR>>
 لا يوجد لهم صلة واضحة بالعميل ودون مبرر واضح .<<CR>>
 13- طلب الاسترداد المبكر لقيمة الوثيقة أو تغيير تاريخ استحقاقها، وبخاصة<<CR>>
 عندما يؤدى ذلك إلى تحمل خسائر مادية دون مبرر واضح .<<CR>>
 مؤشرات خاصة بالتمويل العقارى :<<CR>>
 1- عمليات التمويل الكبيرة التى ليس لها هدف اقتصادى واضح .<<CR>>
 2- عدم مبالاة العميل بكبر مبلغ قسط التمويل أو تكلفة التمويل .<<CR>>

 3- طلبات التمويل العقارى بضمان أصول مملوكة لآخرين أو تقديم العملاء<<CR>>
 ضمانات إضافية مملوكة لآخرين مع عدم وجود صلة واضحة تربطهم بهم .<<CR>>
 4- طلب الحصول على تمويل عقارى مقابل ضمانات من بنك يعمل خارج<<CR>>
 البلاد بدون سبب واضح لذلك .<<CR>>
 5- السداد المبكر بصورة غير متوقعة للمديونيات من قبل العميل أو أطراف<<CR>>
 أخرى خاصة بالنسبة للعملاء المتعثرين دون معرفة مصدر الأموال .<<CR>>
 6- الإيداعات النقدية الكبيرة بصورة غير عادية بما لا يتناسب مع نشاط العميل .<<CR>>
 7- الإيداعات النقدية المتكررة التى لا يتناسب مجموعها خلال فترة زمنية معينة<<CR>>
مع نشاط العميل بما فى ذلك حالات السداد المعجل لمبالغ كبيرة أو المتكررة خلال<<CR>>
 فترات قصيرة لاسيما إذا كان من المتعثرين .<<CR>>
 8- الإيداعات النقدية الكبيرة أو المتكررة التى تودعها جهات مختلفة لحساب أحد<<CR>>
 العملاء دون أن يكون هناك ثمة علاقة بين هذه الجهات والعميل .<<CR>>
 9- حالات السداد الكامل فى ذات عام منح التمويل .<<CR>>
 10- العملاء الذين يشترون عقارات بمبالغ كبيرة تفوق أسعار التقييم بدرجة<<CR>>
 كبيرة ويقومون بتغطية فرق السعر من مواردهم الخاصة .<<CR>>
 مؤشرات خاصة بالتأجير التمويلى :<<CR>>
 1- العمليات التى تتم مع عملاء يقومون بسداد أقساط التأجير التمويلى<<CR>>
من حسابات يحتفظون بها لدى دول لا تتوافر لديها نظم تشريعية فى مجال مكافحة<<CR>>
 غسل الأموال أو تمويل الإرهاب .<<CR>>
 2- عدم مبالاة العميل بكبر مبلغ قسط التأجير التمويلى أو تكلفة التمويل .<<CR>>
 3- العمليات الكبيرة التى ليس لها هدف اقتصادى واضح .<<CR>>
 4- الإيداعات النقدية الكبيرة أو المتكررة التى تودعها جهات مختلفة لحساب أحد<<CR>>
 العملاء دون أن يكون هناك ثمة علاقة بين هذه الجهات والعميل .<<CR>>

 مؤشرات خاصة بالتخصيم :<<CR>>
 1- عدم مبالاة العميل بتكلفة التمويل .<<CR>>
 2- عدم مطابقة الأوراق المخصمة للبيانات الواردة عن المدينين .<<CR>>
 3- تغير حجم الأوراق المخصمة بشكل غير مبرر .<<CR>>
 4- عدم التناسق بين حجم المبيعات والأوراق المخصمة .<<CR>>
 5- أن يكون العميل وكيلاً لأصيل غير معروف .<<CR>>
 6- تقديم العميل لأوراق مخصمة ليس لها علاقة بنشاطه الرئيسى .<<CR>>
 7- التفاوت الكبير بين سعر شراء البضاعة فى الورقة المخصمة وبين السعر<<CR>>
 السوقى السائد لها .<<CR>>
 8- وجود الأوراق المخصمة بقيم كبيرة مقارنة بالمتوسط المعتاد للعميل.<<CR>>
 9- عدم التطابق بين حجم وقيم الأوراق المخصمة وبين حجم المبيعات الحقيقى للعميل .<<CR>>
 10- الحصول على تمويل مقابل ضمانات من بنك يعمل خارج البلاد بدون سبب<<CR>>
 واضح لذلك .<<CR>>
مؤشرات خاصة بنشاط تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر :<<CR>>
 1- السداد المعجل لقيمة التمويل بشكل خاص خلال الأشهر الأولى من منح<<CR>>
 التمويل ولكامل قيمته دون مبرر واضح ومقبول .<<CR>>
 2- عدم الاهتمام بمعرفة تكاليف التمويل وسعر العائد والمصاريف<<CR>>
 الإدارية وخلافه .<<CR>>
 3- ثبوت وجود مستفيد آخر حقيقى من التمويل بخلاف العميل الذى قام<<CR>>
 بصرف التمويل .<<CR>>
 4- حصول العميل على عدة تمويلات من أماكن مختلفة خلال فترة قصيرة .<<CR>>
 5- اكتشاف تورط واحد أو أكثر من أفراد عائلة العميل فى أنشطة إجرامية<<CR>>
 إرهابية، وبشكل خاص فى الأقاليم والمراكز المحلية .<<CR>>
 6- الانتماء إلى عائلات معروف عنها تورط واحد أو أكثر من أفرادها<<CR>>
 فى أنشطة إجرامية إرهابية، وبشكل خاص فى الأقاليم والمراكز المحلية .<<CR>>

 مؤشرات خاصة بالتمويل الاستهلاكى :<<CR>>
 1- إجراء تعاقدات لشراء السلع أو الخدمات بشكل مبالغ فيه وبدون مبرر .<<CR>>
 2- قيام العميل بالسداد المبكر بصورة غير متوقعة للمديونيات سواء من قبل<<CR>>
 العميل أو أطراف أخرى خاصة بالنسبة للعملاء المتعثرين .<<CR>>
 3- الإيداعات النقدية الكبيرة أو المتكررة التى يودعها أشخاص أو جهات مختلفة<<CR>>
 لحساب أحد العملاء دون أن يكون هناك علاقة بينهم تبرر ذلك .<<CR>>
 4- ثبوت وجود مستفيد حقيقى من السلع أو الخدمات المتعاقد عليها بخلاف<<CR>>
 العميل الذى قام بالتعاقد عليها .<<CR>>
 5- ثبوت وجود تحويلات للسداد من خلال أشخاص غير المستفيد الحقيقى<<CR>>
 من السلع أو الخدمات المتعاقد عليها .<<CR>>
 6- اكتشاف تورط و احد أو أكثر من أفراد أسرة العميل فى أنشطة إجرامية إرهابية .<<CR>>
 (الفصل الثالث)<<CR>>
