('board_decision',161,2024,13,0,'5fcfed875b5547eb0509b9fd1b7950dc','a474a67efad556609e2ceecdacd25a3a',replace($m216$الالتزامات بشأن العقوبات المالية المستهدفة المرتبطة بالقوائم السلبية<<CR>>
يتعين على المخاطبين بأحكام هذا القرار الالتزام بما تضمنته الإرشادات<<CR>>
التفصيلية الصادرة عن الوحدة بشأن تنفيذ قرارات مجلس الأمن الخاصة بالعقوبات<<CR>>
المالية المستهدفة ذات الصلة بالإرهاب وتمويله وتمويل انتشار أسلحة الدمار الشامل،<<CR>>
وعلى وجه الأخص فيما يتعلق بقوائم عقوبات مجلس الأمن المتعلقة بالإرهاب وتمويله<<CR>>
وتمويل أسلحة الدمار الشامل وقائمتى الكيانات الإرهابية والإرهابيين بما فى ذلك<<CR>>
 الواردة بالملحق رقم (1) المرفق بهذا القرار، وذلك على النحو الآتى:<<CR>>
 1- أن تتضمن السياسة الداخلية أو إجراءات عمل الجهة، أهمية تطبيق العقوبات<<CR>>
المالية المستهدفة دون تأخير وما يتبع ذلك من إجراءات وهى التجميد أو رفع التجميد<<CR>>
 الفورى، وكذا ما يفيد إخطار الوحدة والهيئة بذلك.<<CR>>

 2- أن تتضمن سياسة إدارة المخاطر وقبول العملاء المطبقة بالجهة، المخاطر<<CR>>
المتعلقة بالأشخاص والجهات المدرجين على القوائم السلبية وتحديد الإجراءات<<CR>>
 المناسبة للتعامل معها، على أن يتم مراجعة وتحديث هذا التصنيف بشكل دورى.<<CR>>
 3- تعميم الإرشادات الصادرة عن الوحدة على كافة فروع الجهات المخاطبة بهذا<<CR>>
 القرار، والفهم الجيد لتلك الإرشادات لدى العاملين بها.<<CR>>
 4- تعميم إجراءات العناية الواجبة بالعملاء على كافة فروع الجهات المخاطبة<<CR>>
بهذا القرار، والالتزام بتنفيذ ما ورد بإجراءات العناية الواجبة بعملائها المعدة من<<CR>>
 جانب الوحدة فيما يتعلق بالقوائم السلبية.<<CR>>
 5- أن تتضمن أنظمة الجهة وسجلاتها وبرامجها الداخلية نظاما فعالاً يمكنها من<<CR>>
الكشف عن أسماء الأشخاص المدرجين على قوائم عقوبات مجلس الأمن وقائمتى<<CR>>
الكيانات الإرهابية والإرهابيين والقوائم الصادرة بموجب أحكام نهائية أو بموجب<<CR>>
قرارات صادرة من النائب العام أو إدارة الكسب غير المشروع أو لجنة إجراءات<<CR>>
التحفظ والحصر والإدارة والتصرف فى أموال الجماعات الإرهابية والإرهابيين أو أى<<CR>>
قرارات تصدر من جهات رقابية بالدولة، وعلى تلك الجهات التحقق من قدرة تلك<<CR>>
الأنظمة المطبقة فى اكتشاف حالات مطابقة لبعض الحالات مثل: الاسم، رقم بطاقة<<CR>>
الهوية، الجنسية، تاريخ الميلاد وغيرها من المعلومات، وينبغى أن يراعى بشأن هذا<<CR>>
 النظام ما يلى:<<CR>>
(أ) تحديد الأشخاص والكيانات المدرجة أسماؤهم على قوائم مجلس الأمن<<CR>>
ذات الصلة وقائمتى الكيانات الإرهابية والإرهابيين والقوائم الصادرة من<<CR>>
 النائب العام.<<CR>>
(ب) التجميد الفورى ودون تأخير، دون إشعار مسبق، لجميع الأموال والأوراق<<CR>>
 والأدوات المالية أو الأصول الأخرى المملوكة لهذه الأشخاص والكيانات .<<CR>>
(ج) يتم رفع التجميد عن الأموال أو الأصول فور تلقى ما يفيد رفع اسم الكيان<<CR>>
أو الشخص المدرج من القوائم السلبية، على أن يسمح بالتعامل على تلك<<CR>>
 الأموال أو الأصول فور تلقى ما يفيد ذلك.<<CR>>

(د) وجوب الرجوع إلى القوائم السلبية عند الدخول فى علاقة عمل جديدة مع أى<<CR>>
شخص طبيعى أو اعتبارى واتباع إجراءات العناية الواجبة الصادرة عن<<CR>>
الوحدة للتأكد من مدى إدراجه على هذه القوائم، وكذلك مقارنة كافة أطراف<<CR>>
أى عملية بتلك القوائم، ويشمل ذلك؛ فتح حساب أو إبرام تعاقد للحصول<<CR>>
على تمويل أو وثائق تأمين أو إبرام أى عقود للحصول على أى من<<CR>>
الخدمات المالية غير المصرفية، وغيرها وفقا لطبيعة عمل كل جهة، وذلك<<CR>>
 قبل تنفيذ هذه العمليات.<<CR>>
(ه) التحديث الفورى للمعلومات المتعلقة بالقوائم السلبية وما يطرأ عليهما<<CR>>
من تعديلات وفقًا للآلية الموضوعة باللائحة التنفيذية لقانون مكافحة<<CR>>
 غسل الأموال.<<CR>>
 6- متابعة أى تغيرات قد تطرأ على القوائم السلبية بشكل يومى، والتحديث<<CR>>
الفورى لأنظمة الجهة وبرامجها الداخلية وفقًا لتلك التغيرات، بالإضافة إلى ما يتم<<CR>>
 إرساله من الهيئة من تحديثات فى هذا الشأن .<<CR>>
 7- عدم التعامل بشكل مباشر أو غير مباشر مع أى شخص طبيعى أو اعتبارى<<CR>>
من الأسماء المدرجة على القوائم، ويشمل ذلك؛ العملاء الحاليين والعملاء الجدد<<CR>>
 والعملاء العارضين والمستفيدين الحقيقيين وكافة الأطراف المتعلقة بأى عملية.<<CR>>
 8- الالتزام بتجميد الأموال والأوراق والأدوات المالية أو الأصول الأخرى أيا<<CR>>
كانت صورتها (حسابات، ودائع، بوالص تأمين، وغيرها) الخاصة بالأشخاص<<CR>>
 والكيانات المدرجة على القوائم فورا دون تأخير، على أن يشمل التجميد ما يلى:<<CR>>
(أ) جميع الأموال أو الأوراق والأدوات المالية أو الأصول الأخرى التى يمتلكها<<CR>>
أو يتحكم فيها الشخص أو الكيان المسمى وعدم قصرها على التى يمكن<<CR>>
 حصر استخدامها على عمل إرهابى أو مؤامرة أو تهديد بعينه .<<CR>>
(ب) الأموال أو الأوراق والأدوات المالية أو الأصول الأخرى التى تمتلكها<<CR>>
الأشخاص أو الكيانات المسماة، بالكامل أو بالاشتراك مع غيرهم،<<CR>>
 أو يتحكمون فيها، بشكل مباشر أو غير مباشر.<<CR>>
(ج) الأموال أو الأوراق والأدوات المالية أو الأصول الأخرى المكتسبة من أو الناشئة<<CR>>
عن أموال أو أصول أخرى مملوكة للأشخاص أو الكيانات المسماة أو يتحكمون<<CR>>
 فيها بشكل مباشر أو غير مباشر .<<CR>>

(د) الأموال أو الأوراق والأدوات المالية أو الأصول الأخرى الخاصة<<CR>>
بالأشخاص والكيانات التى تنوب عن الأشخاص أو الكيانات المسماة<<CR>>
 أو تعمل بتوجيه منها.<<CR>>
 9- الامتناع عن إتاحة أى أموال أو أوراق وأدوات مالية أو أصول أخرى<<CR>>
أو موارد اقتصادية أو خدمات مالية أو أى خدمات أخرى ذات صلة، بشكل مباشر<<CR>>
أو غير مباشر، لصالح الأشخاص والكيانات المدرجة بالقوائم السلبية ولصالح الكيانات<<CR>>
المملوكة لهؤلاء الأشخاص أو الكيانات المدرجة أو التى يتحكمون فيها بشكل مباشر<<CR>>
أو غير مباشر، وكذلك لصالح الأشخاص والكيانات التى تنوب عن الأشخاص<<CR>>
 أو الكيانات المدرجة أو تعمل بتوجيه منها.<<CR>>
 10- الاستمرار فى إضافة أية فوائد أو غيرها من الأرباح أو العائدات<<CR>>
 أو الدفعات المستحقة على الحسابات المجمدة شرط إبقائها مجمدة .<<CR>>
 11- تنفيذ الإخطارات الواردة للجهات المخاطبة بهذا القرار من جهات الرقابة<<CR>>
فى الدولة بشأن الأموال والأصول الأخرى، المجمدة فيما يتعلق بالإعفاءات بشكل<<CR>>
فورى دون تأخير، ويشمل ذلك القرارات الخاصة بطلبات صرف النفقات الأساسية<<CR>>
 أو صرف النفقات الاستثنائية.<<CR>>
 12- إخطار الوحدة بأية أموال أو أصول أخرى تم تجميدها أو تم رفع تجميدها،<<CR>>
