بالجهات العاملة فى مجال الأنشطة المالية غير المصرفية بمهام وظيفته أو مخالفته<<CR>>
لأى من القوانين أو القواعد المنظمة لعمله أو فى حال فقده لأحد شروط قيده بالسجل،<<CR>>
 وبعد التحقيق معه، أن يتخذ ما يراه مناسبا من التدابير الآتية:<<CR>>
 1- التنبيه.<<CR>>
 2- الإنذار.<<CR>>
 3- شطب القيد من السجل، مع عدم جواز إعادة القيد إلا بعد انقضاء فترة لا تقل<<CR>>
 عن سنة ولا تزيد على ثلاث سنوات.<<CR>>
 4- إلغاء الترخيص وشطب القيد من السجل مع عدم جواز إعادة الترخيص<<CR>>
 والقيد مرة أخرى.<<CR>>
 (المادة الحادية والعشرون)<<CR>>
 التزامات المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب<<CR>>
 يلتزم المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب بالمهام الآتية:<<CR>>
 1- فحص العمليات غير العادية التى تستخرج من الأنظمة الداخلية للمؤسسات<<CR>>
المالية، والعمليات الواردة بتقارير الاشتباه الداخلية، والعمليات التى أثير الاشتباه فيها<<CR>>
 بناء على معلومات وردت من أية جهة أخرى أو معلومات نمت إلى عمله.<<CR>>
 2- إخطار الوحدة بالعمليات التى يشتبه فى أنها تشكل متحصلات أو تتضمن<<CR>>
غسل أموال أو تمويل إرهاب، بما فى ذلك محاولات إجراء هذه العمليات، بغض<<CR>>
 النظر عن قيمتها وبالشكل الذى يكفل الحفاظ على سرية المعلومات بها.<<CR>>
 3- اتخاذ القرارات بشأن حفظ العمليات التى تم فحصها وتبين له عدم وجود أية<<CR>>
 شبهة بشأنها على أن يتضمن القرار الأسباب التى استند إليها فى الحفظ.<<CR>>
 4- اقتراح ما يراه لازما من تطوير وتحديث للسياسة المتبعة فى الجهة التى<<CR>>
يعمل بها بشأن مجال مكافحة غسل الأموال وتمويل الإرهاب وكذا النظم والإجراءات<<CR>>
المتبعة بها فى هذا المجال وذلك بهدف زيادة فاعليتها وكفاءتها ومواكبتها المستجدات<<CR>>
 المحلية والعالمية.<<CR>>

 5- الإشراف العام مكتبيا وميدانيا، بنفسه أو من خلال الاستعانة بالإدارات<<CR>>
بالجهة التى يعمل بها للتأكد من مدى التزام المركز الرئيسى لها وفروعها بتطبيق<<CR>>
أحكام القانون ولائحته التنفيذية والقواعد والضوابط الرقابية ذات الصلة بمكافحة غسل<<CR>>
 الأموال وتمويل الإرهاب والنظم والإجراءات الداخلية الموضوعة فى هذا الشأن .<<CR>>
 6- التعاون والتنسيق مع الإدارات المعينة بالجهة التى يعمل بها فى شأن وضع<<CR>>
خطط التدريب الداخلية والخارجية فى مجال مكافحة غسل الأموال وتمويل الإرهاب<<CR>>
 للعاملين بها، واقتراح البرامج التدريبية اللازمة لتنفيذ هذه الخطط، ومتابعة التنفيذ.<<CR>>
 7- التسجيل على موقع الوحدة لاستلام التحديثات الخاصة بالتعديلات على قوائم<<CR>>
 مجلس الأمن وقائمتى الكيانات الإرهابية والإرهابيين المحلية.<<CR>>
 8- متابعة الموقع الإلكترونى للوحدة بصفة يومية لتعميم أى تحديث قد يطرأ<<CR>>
على قوائم العقوبات المالية المستهدفة أو أى إرشادات أو إجراءات محدثة يتم إصدارها<<CR>>
 من الوحدة، وذلك دون انتظار ورود أى إخطار أو تعميم من الهيئة فى هذا الشأن .<<CR>>
 9- متابعة التزام الجهة وفروعها بالرجوع إلى القوائم السلبية عند إجراء أى<<CR>>
عملية أو الدخول فى علاقة عمل جديدة مع شخص أو جهة للتأكد من الإدراج على<<CR>>
 تلك القوائم من عدمه .<<CR>>
 10- التحديث الفورى للمعلومات المتعلقة بالقوائم السببية وما يطرأ عليها<<CR>>
 من تعديلات.<<CR>>
 11- فحص ومطابقة كافة العملاء الحاليين للجهة عند إجراء كل تحديث للقوائم<<CR>>
 السلبية للتأكد من عدم وجودهم ضمن عملاء الجهة وحظر التعامل معهم.<<CR>>
 12- التأكد من عدم التعامل مع أى شخص طبيعى أو اعتبارى من الأسماء المدرجة<<CR>>
 بالقوائم السلبية والتى يتم مراجعتها بشكل يومى، ويتم التحقق فى الحالات الآتية :<<CR>>
(أ) مراجعة أسماء العملاء الجدد وتحديد المستفيد الفعلى فى حال بدء علاقة عمل<<CR>>
مع العميل قبل القيام بإجراءات فتح الحساب أو الحصول على تمويل أو<<CR>>
وثائق تأمين بحسب الأحوال، بحيث يتم مراجعة كافة الأطراف المتعاملة<<CR>>
على الحساب والمتمثلة فى (العميل، المساهم، الضامن، المرخص له<<CR>>
بالتوقيع، الشريك، الوكيل، الولى، الوصى ...إلخ) أو أى أطراف أخرى<<CR>>
 متعاملة على حساب العميل.<<CR>>
 (ب) عند تحديث العملاء القائمين لبياناتهم.<<CR>>

 13- متابعة إجراءات تطبيق العقوبات المالية المستهدفة دون تأخير وما يتبع ذلك<<CR>>
 من إجراءات التجميد الفورى ورفع التجميد وإخطار الوحدة والهيئة بذلك.<<CR>>
 14- مراجعة الأنظمة المطبقة للكشف بالقوائم وفقًا للنظم المعمول بها بكل جهة،<<CR>>
 والتأكد من دورية التحديث الذى يتم على هذه القوائم.<<CR>>
 15- التأكد من تعميم إجراءات العناية الواجبة بالعملاء على كافة فروع الجهة.<<CR>>
 16- الاحتفاظ بالمستندات الدالة على قيام الجهة بالكشف عن عملائها بالقوائم<<CR>>
السلبية سواء قوائم عقوبات مجلس الأمن ذات الصلة بالإرهاب وتمويله وتمويل انتشار<<CR>>
 أسلحة الدمار الشامل أو قائمتى الكيانات الإرهابية والإرهابيين.<<CR>>
 17- إعداد تقرير دورى مرة على الأقل كل سنة عن أوجه نشاطه وتقييمه لنظم<<CR>>
وإجراءات مكافحة غسل الأموال وتمويل الإرهاب فى الجهة التى يعمل بها، وعن<<CR>>
العمليات غير العادية والمشتبه فيها وما اتخذ فى شأنها من إجراءات مشفوعا بما يراه<<CR>>
من اقتراحات فى هذا الشأن، ويقدم التقرير إلى مجلس إدارة الجهة لإبداء ما يراه من<<CR>>
ملاحظات وما يقرر اتخاذه من إجراءات فى شأنه، على أن يرسل هذا التقرير إلى<<CR>>
الوحدة والهيئة مشفوعا بملاحظات وقرارات مجلس إدارة الجهة فى شأنه فى موعد<<CR>>
أقصاه نهاية شهر يناير من العام التالى للفترة المعد عنها التقرير وذلك وفقًا للنموذج<<CR>>
 المعد من الوحدة فى هذا الشأن .<<CR>>
 18- إمداد الوحدة بما تطلبه من المعلومات والبيانات والإحصائيات اللازمة<<CR>>
لمباشرتها لاختصاصاتها، وتيسير الاطلاع على السجلات والمستندات فى سبيل مباشرتها<<CR>>
أعمال التحرى والفحص أو لتضمينها قاعدة البيانات المنشأة فى الوحدة، كما يلتزم بموافاة<<CR>>
الهيئة بأى من البيانات أو الإحصائيات اللازمة فى هذا الشأن، وذلك دون الإخلال<<CR>>
 بالقوانين المنظمة للأنشطة المالية غير المصرفية .<<CR>>
 19- توفير التغذية العكسية والإرشادات والتعليمات بشأن تقارير الاشتباه الداخلية<<CR>>
 لرفع جودتها .<<CR>>
ويلتزم الأشخاص الطبيعيون المرخص لهم بمزاولة أى أعمال تتصل بأحد الأنشطة<<CR>>
المالية غير المصرفية على النحو الوارد بالقوانين المنظمة لها، بالقيام بمهام المدير<<CR>>
 المسئول عن مكافحة غسل الأموال وتمويل الإرهاب المشار إليها بهذه المادة .<<CR>>

 (المادة الثانية والعشرون)<<CR>>
 ضمانات وصلاحيات مسئول مكافحة غسل الأموال وتمويل الإرهاب<<CR>>
يجب أن يتمتع المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب<<CR>>
بالاستقلال فى أداء مهامه وأن يتاح له كافة الوسائل الكفيلة للقيام بهذه المهام على نحو<<CR>>
 يحقق الغرض منها، ويستلزم ذلك ما يلى :<<CR>>
 1- الالتزام بعدم إسناد أى أعمال إليه تتعارض مع مهامه باعتباره مسئولاً عن<<CR>>
 مكافحة غسل الأموال وتمويل الإرهاب .<<CR>>
 2- أن يكون له الحق فى الحصول على كافة المعلومات والاطلاع على كافة<<CR>>
السجلات أو المستندات التى يراها لازمة لمباشرة مهامه فى فحص تقارير العمليات غير<<CR>>
العادية وحالات الاشتباه التى ترد إليه، والاتصال بمن يلزم من العاملين بالجهة التى يعمل<<CR>>
 بها لتنفيذ تلك المهام .<<CR>>
 3- أن يكون له الحق فى تقديم تقارير إلى الإدارة العليا بالجهة التى يعمل بها أو إلى<<CR>>
مجلس إدارتها أو إلى أية لجنة تابعة لهما بما يساعد على زيادة كفاءة وفاعلية نظم<<CR>>
 وإجراءات مكافحة غسل الأموال وتمويل الإرهاب والتزام العاملين بها .<<CR>>
 4- أن تكفل له السرية والحماية التامة لجميع إجراءات تلقيه تقارير العمليات غير<<CR>>
