 فى تطبيق كافة الضوابط والإجراءات المتعلقة بعمليات غسل الأموال وتمويل الإرهاب .<<CR>>
 (المادة الثالثة والعشرون)<<CR>>
يلغى قرار مجلس إدارة الهيئة رقم 2 لسنة 2021 بشأن الضوابط الرقابية فى مجال<<CR>>
مكافحة غسل الأموال وتمويل الإرهاب للجهات العاملة فى مجال الأنشطة المالية<<CR>>
 غير المصرفية، كما يلغى كل حكم يخالف أحكام هذا القرار .<<CR>>

 (المادة الرابعة والعشرون)<<CR>>
ينشر هذا القرار فى الوقائع المصرية وعلى الموقع الإلكترونى للهيئة والبورصة<<CR>>
 المصرية، ويعمل به من اليوم التالى لتاريخ نشره فى الوقائع المصرية .<<CR>>
 رئيس مجلس إدارة<<CR>>
 الهيئة العامة للرقابة المالية<<CR>>
 د .محمد فريد صالح<<CR>>

 ملحق رقم (1)<<CR>>
 التعريفات بالعقوبات المالية المستهدفة المرتبطة بالقوائم السلبية<<CR>>
 1- حدد مجلس الأمن أسماء الأشخاص والكيانات المطبق عليها العقوبات والقيود<<CR>>
المالية المستهدفة Targeted Financial Sanctionsونظمها فى صورة قوائم للجزاءات<<CR>>
(العقوبات)، وهى قوائم عقوبات ذات صلة بالإرهاب وتمويله، وقوائم عقوبات ذات صلة<<CR>>
بتمويل انتشار أسلحة الدمار الشامل، وذلك وفقًا لمجموعة من المعايير بموجب قرارات<<CR>>
مجلس الأمن، ويقوم المجلس بمتابعة طلبات اقتراح أسماء جديدة للإدراج والمقدمة من<<CR>>
 الدول المختلفة وكذلك طلبات رفع الأسماء وطلبات الإعفاء من التجميد.<<CR>>
 2- أصدرت مجموعة العمل المالى توصيتها السادسة بشأن إلزام الدول بتطبيق<<CR>>
أنظمة العقوبات المالية المستهدفة الصادرة بموجب الفصل السابع من ميثاق الأمم المتحدة<<CR>>
وفقًا لقرارات مجلس الأمن وتحديدا تلك التى تتعلق بمنع وقمع الإرهاب وتمويله ومن أهم<<CR>>
تلك القرارات: القرارات أرقام (1267/1989/2253) والقرارات اللاحقة له فيما يخص<<CR>>
العقوبات المتعلقة بالأشخاص والكيانات التابعة للقاعدة وداعش، والقرار رقن (1988)<<CR>>
فيما يخص الأشخاص والكيانات المتعلقة بحركة طالبان، وتلزم تلك القرارات الدول بأن<<CR>>
تجمد دون تأخير الأموال أو الأصول أو الموارد الاقتصادية الخاصة بأى شخص أو كيان<<CR>>
 مدرج بموجب هذه القرارات .<<CR>>
 3- أصدرت مجموعة العمل المالى توصيتها السابعة لتلزم الدول بتطبيق أنظمة<<CR>>
العقوبات المالية المستهدفة وفقًا لقرارات مجلس الأمن التى تتعلق بمنع وقمع انتشار أسلحة<<CR>>
الدمار الشامل وتمويله ولاسيما القرار رقم (1718) والقرارات اللاحقة له فيما يتعلق<<CR>>
بفرض الحظر على الأسلحة وتجميد الأصول وحظر السفر على الأشخاص المشاركين فى<<CR>>
البرنامج النووى لجمهورية كوريا الشعبية الديمقراطية، والقرار رقم (2231) فى الشأن<<CR>>
الإيرانى والقرارات السابقة واللاحقة له، وتلزم تلك القرارات الدول بأن تجمد دون تأخير<<CR>>
الأموال والأصول الأخرى التى تخص أى شخص أو كيان محدد من قبل مجلس الأمن<<CR>>

وأن تتأكد من عدم إتاحة أى أموال أو أصول أخرى بصورة مباشرة أو غير مباشرة له<<CR>>
 أو لصالحه أو لمنفعته.<<CR>>
 4- أكد قرار مجلس الأمن رقم (1373) على ضرورة قيام الدول بالتصدى للأعمال<<CR>>
الإرهابية والإرهابيين داخل حدود الدولة وخارجها، وأشار إلى أن ذلك يتطلب وضع<<CR>>
تدابير تضمن منع الأعمال الإرهابية وتجريمها، وتجميد الأموال والأصول الأخرى<<CR>>
الخاصة بالإرهابيين والكيانات الإرهابية، وبناء عليه، تم إصدار عدد من القوانين لتحقيق<<CR>>
التنفيذ الفعال لهذا القرار، ومن أهمها قانون تنظيم قوائم الكيانات الإرهابية والإرهابيين،<<CR>>
والذى تم بموجبه إعداد قائمتى الكيانات الإرهابية والإرهابيين، وتحديد الآثار المترتبة على<<CR>>
إدراج أسماء أشخاص أو كيانات على أى من هاتين القائمتين ومن بينها تجميد الأموال<<CR>>
 والأصول الأخرى.$m216$,'<<CR>>',chr(13))),
('regulation',286,2021,1,0,'cec6cc45d7b14d8b19d4ee154e57f5fd','9897be83474e28d877caafeb6bb1f08f',replace($m216$فى تطبيق أحكام هذه اللائحة ، يُقصد بالألفاظ والعبارات التالية المعنى المبين قرين كل منها :
الوزير : وزير المالية .
رئيس المصلحة : رئيس مصلحة الضرائب المصرية .
القانون : قانون الإجراءات الضريبية الموحد الصادر بالقانون رقم 206 لسنة 2020 .
المصلحة : مصلحة الضرائب المصرية .
المنطقة : المنطقة التى يقع فى دائرة اختصاصها مأمورية الضرائب المختصة .
المأمورية المختصة : مأمورية الضرائب التى يقع فى دائرتها مركز مزاولة نشاط الممول أو المكلف أو التى أصدرت البطاقة الضريبية أو شهادة التسجيل ، وإذا تعددت منشآت الممول أو المكلف وفروعها تكون المأمورية المختصة هى المأمورية التى يقع فى دائرتها المركز الرئيسى للنشاط من واقع السجل التجارى ، ويجوز لرئيس المصلحة بقرار منه تعيين مأمورية مختصة لأنشطة أو ممولين أو مكلفين محددين .
الإيصال الالكترونى : المحرر الإلكترونى الصادر من بائع السلعة أو مؤدى الخدمة للمستهلك للسلعة أو المستفيد من الخدمة وفقًا للضوابط والأحكام المحددة بهذه اللائحة .
مقدم الخدمة : الشخص الاعتبارى الحاصل على ترخيص تنفيذ النظام الإلكترونى ، ويتمثل دوره الأساسى كوسيط فى تلقى الفواتير الإلكترونية من مصدرها ، وإرسالها للمصلحة بعد التحقق من استيفائها الشروط الشكلية المقررة قانونًا .
نظام التكويد : نظام يُستخدم فى تصنيف السلع والخدمات ، يتم بموجبه تعيين كود مميز لكل سلعة أو خدمة ليستخدم فى إصدار الفاتورة أو الإيصال الإلكترونى ، ويصدر بتحديد نوع التكويد قرار من رئيس المصلحة .
الشخص المرتبط : كل شخص يرتبط بممول بعلاقة تؤثر فى تحديد وعاء الضريبة بشكل مباشر أو غير مباشر ، سواء من خلال الإدارة أو السيطرة أو الملكية ، وبوجه عام يكون الشخصان مرتبطين إذا كانت العلاقة بينهما تصل إلى حد إمكانية قيام أحد الشخصين أو قيام كلا الشخصين بالتصرف وفقًا لتوجيهات أو طلبات أو اقتراحات أو إرادة الشخص الآخر أو شخص ثالث .
ويُعامل الأشخاص التالى بيانهم بوصفهم أشخاصًا مرتبطين :
1 - الزوج والزوجة والأصول والفروع أو فيما بينهما أو بين بعضهم البعض .
2 - شركة الأشخاص والشركاء المتضامنون والموصون فيها .
3 - شركة الأموال والشخص الذى يملك فيها بشكل مباشر أو غير مباشر (50%) على الأقل من حقوق التصويت أو الإدارة فى الشركة ، أو من حقوق توزيع الأرباح ، أو من حقوق رأس المال .
4 - أى شركتين أو أكثر يملك أو يحوز شخص آخر (50%) على الأقل من حقوق التصويت أو الإدارة فى الشركتين ، أو من حقوق توزيع الأرباح فى الشركتين ، أو من حقوق رأس المال فى الشركتين .
وعند تطبيق البنود ( 2 ) أو ( 3 ) أو ( 4 ) من الفقرة السابقة ، فإن الملكية أو الحيازة التى تنسب إلى شخص ما من قِبَل شخص مرتبط لا يجوز أن تنسب إلى شخص آخر مرتبط .
ولا يعتبر شخصين مرتبطين لمجرد أن أحدهما يعد عاملاً أو عميلاً لدى الشخص الآخر أو أن كليهما يعد عاملاً أو عميلاً لدى شخص ثالث ، ما لم يؤثر هذا الارتباط فى تحديد وعاء الضريبة بشكل مباشر أو غير مباشر .$m216$,'<<CR>>',chr(13))),
('regulation',286,2021,16,0,'bf36387f072f34e44d4ae70a8b384288','e8bbdc0828ba390f1ab6c1c221c5fe95',replace($m216$فى تطبيق أحكام المادة ( 13 ) من القانون ، يؤدى الممول مبلغا للمصلحة يعادل (1%) من قيمة المعاملات التى لم يفصح عنها فى إقراره السنوى لضريبة الدخل ، ولا يتجاوز عن تحصيل هذا المبلغ حتى ولو قام الممول بالإفصاح عن هذه المعاملات ضمن الملف المحلى أو الرئيسى .$m216$,'<<CR>>',chr(13))),
('regulation',286,2021,39,0,'d2f3159c867ba46f45096938029783e5','2d5c0b72979861f632b06459548b51b1',replace($m216$يسرى ترخيص مقدم الخدمة لمدة ثلاث سنوات من تاريخ الحصول عليه ، وفى حالة رغبة مقدم الخدمة تجديد ترخيصه لمدة أخرى يتعين عليه تقديم طلب للمصلحة قبل انتهاء مدة الترخيص بثلاثة أشهر على الأقل وبشرط سريان الضمان المالى واستيفاء كافة الشروط اللازمة للترخيص .
وعلى المصلحة اعتماد طلب التجديد خلال مدة الأشهر الثلاثة المشار إليها .
وفى حالة عدم رغبة مقدم الخدمة فى تجديد ترخيصه يتعين عليه تقديم طلب للمصلحة قبل انتهاء مدة الترخيص بثلاثة أشهر على الأقل .
ويجب على مقدم الخدمة حال رغبته فى إنهاء الترخيص قبل انتهاء مدته ، تقديم طلب للمصلحة قبل تاريخ إنهاء الترخيص بثلاثة أشهر وسداد نسبة (15%) من قيمة الضمان المالى الذى يصدر بتحديده قرار من الوزير .$m216$,'<<CR>>',chr(13))),
('law',14,2025,1,0,'3b43ee02bbf18825c14d35bbea865c6b','b7a92ae5017d19199f5377d8c45a412d',replace($m216$يقصد فى تطبيق أحكام هذا القانون بالكلمات والمصطلحات الآتية المعانى المبينة قرين كل منها:<<CR>>
1- العامل:كل شخص طبيعى يعمل لقاء أجر لدى صاحب عمل تحت إدارته أو إشرافه.<<CR>>
2- المتدرج:كل من التحق لدى صاحب عمل بقصد تعلم مهنة أو صنعة أو حرفة لقاء أجر.<<CR>>
3- صاحب العمل:كل شخص طبيعى أو اعتبارى يستخدم عاملاً أو أكثر لقاء أجر.<<CR>>
4- الأجر:كل ما يحصل عليه العامل لقاء عمله نقدا كان أو عينًا، ويشمل الآتى: الأجر الأساسى:الأجر المنصوص عليه فى عقد العمل،وما يطرأ عليه من علاوات. الأجر المتغير:باقى ما يحصل عليه العامل من عناصر الأجر،وعلى الأخص: (أ) العمولة أو النسبة المئوية:مبلغ من المال يدفع للعامل مقابل ما يقوم بإنتاجه،أو بيعه،أو تحصيله طوال قيامه بالعمل المقرر له هذه النسبة. (ب) العلاوات:مبلغ مالى أو نسبة من الأجر الأساسى تُمنح للعامل لمواجهة ظروف اقتصادية أو اجتماعية أو فنية ما لم تضم إلى الأجر الأساسى. (ج) المنح:ما يعطى للعامل زيادة على أجره،متى كانت مقررة فى عقود العمل الفردية،أو الجماعية،أو الأنظمة الأساسية للعمل،أو ما جرت العادة بمنحه.<<CR>>
(د) المكافأة:كل ما يصرف للعامل نقدا كان أو عينًا نظير إجادة،أو تميز، أو كفاءة فى أداء العمل المكلف به. (ه) البدلات:ما يعطى للعامل لقاء ظروف أو مخاطر معينة،يتعرض لها فى أداء عمله. (و) نصيب العامل فى الأرباح:ما يصرف للعامل من صافى الأرباح المحققة وفقًا للقوانين المنظمة لها. (ز) الوهبة:المقابل الذى يحصل عليه العامل من غير صاحب العمل إذا جرت العادة بدفعها،وكانت لها قواعد تسمح بتحديدها وفقًا للائحة المنشأة أو العرف السائد. (ح) مقابل الخدمة:المقابل النقدى الذى قد يدفعه العملاء فى المنشآت السياحية والفندقية،وغيرها من المنشآت الأخرى،ويصدر قرار من الوزير المختص بالاتفاق مع الوزراء المعنيين والمنظمة النقابية المعنية ومنظمات أصحاب الأعمال بكيفية توزيعها على العاملين. (ط) المزايا العينية:ما يلتزم به صاحب العمل من مزايا غير نقدية لا تستلزمها مقتضيات العمل.<<CR>>
5- الأجر التأمينى:أجر الاشتراك الوارد بقانون التأمينات الاجتماعية والمعاشات الصادر بالقانون رقم 148 لسنة 2019<<CR>>
6- العمل المؤقت:العمل الذى يدخل بطبيعته فيما يزاوله صاحب العمل من نشاط وتقتضى طبيعة إنجازه مدة محددة،أو ينصب على عمل بذاته، وينتهى بانتهائه.<<CR>>
7- العمل العرضى:العمل الذى لا يدخل بطبيعته فيما يزاوله صاحب العمل من نشاط ولا يستغرق إنجازه أكثر من ستة أشهر.<<CR>>
8- العمل الموسمى:العمل الذى يتم فى مواسم دورية متعارف عليها.<<CR>>
9- العامل غير المنتظم:كل من يقوم بأداء عمل غير دائم بطبيعته مقابل أجر أيا كانت صورته،أو يعمل فى مهنة أو حرفة لا ينظمها قانون خاص،مثل الباعة الجائلين،وموزعى الصحف،وغيرهم.<<CR>>
10- العامل فى القطاع غير الرسمى:كل من يقوم بأداء عمل داخل المنشأة أو خارجها بشكل غير رسمى أو مستتر. 11- السخرة:كل عمل أو خدمة تفرض عنوة على أى شخص تحت التهديد بإنزال عقوبة أو إيذاء،ولم يتطوع هذا الشخص بأدائها بمحض اختياره.<<CR>>
12- الليل:الفترة ما بين غروب الشمس وشروقها.<<CR>>
13- التوجيه المهنى:مساعدة الفرد فى اختيار المهنة أو المسار المهنى الأكثر ملاءمة لقدراته واستعداده وميوله فى ضوء الدراسات المستمرة لسوق العمل والمهن المطلوبة ومقوماتها.<<CR>>
14- التدريب:عملية تُمكن الفرد من اكتساب وتنمية المعارف والمهارات الفنية وسلوكيات المهنة اللازمة لإعداده للعمل المناسب.<<CR>>
15- التلمذة الصناعية:شكل من أشكال التعلم أو تنمية المهارات داخل العمل أو خارجه،يمكن الفرد من اكتساب المهارات والمعارف والجدارات اللازمة للعمل فى مهنة أو صنعة أو حرفة من خلال تدريب منظم مقابل أجر.<<CR>>
16- مجالس المهارات القطاعية:كيانات قطاعية تعزز التعاون بين الحكومة والقطاع الخاص تنشأ لضمان استيفاء منظومة التعليم الفنى والتقنى والتدريب المهنى لاحتياجات القطاع الاقتصادى من العمالة الفنية الماهرة.<<CR>>
17- وكالات التشغيل الخاصة:شركات متخصصة فى اختيار العمال، أو تشغيلهم لدى الغير بالشروط التى أوجبها هذا القانون.<<CR>>
18- الوكلاء المفوضون:كل شخص أنابه أو فوضه صاحب العمل فى إدارة المنشأة،أو شاغلو الوظائف الرئيسية العليا بها الذين يمارسون بعض أو كل سلطات صاحب العمل.<<CR>>
19- المفاوضة الجماعية:الحوار الذى يجرى بين صاحب عمل أو منظمة أصحاب أعمال أو أكثر من جهة،وبين منظمة نقابية عمالية،أو أكثر من جهة أخرى بغرض التوافق لتحقيق مصالح الطرفين.<<CR>>
20- المنازعة الجماعية:كل نزاع ينشأ بين صاحب عمل أو مجموعة أصحاب أعمال أو منظماتهم،وبين جميع عمال المنشأة أو فريق منهم أو منظماتهم النقابية المعنية بشأن شروط العمل أو ظروفه أو التشغيل.<<CR>>
21- الشركاء الاجتماعيون:أطراف العملية الإنتاجية (الحكومة،ومنظمات أصحاب الأعمال،والمنظمات النقابية العمالية).<<CR>>
22- المفوض العمالى:أحد العاملين بالمنشأة يتفق العاملون بها على تفويضه بموجب سند رسمى لتمثيلهم أمام صاحب العمل فى حالة عدم وجود منظمة نقابية عمالية بها.<<CR>>
23- اتفاقية العمل الجماعية:اتفاق مكتوب ينظم شروط وظروف العمل وأحكام التشغيل،ويبرم بين منظمة أو أكثر من المنظمات النقابية العمالية وبين صاحب عمل أو مجموعة من أصحاب الأعمال أو منظمة أو أكثر من منظماتهم.<<CR>>
24- التوفيق:وسيلة يلجأ إليها أحد طرفى منازعة العمل الجماعية طالبا تدخل الجهة الإدارية المختصة بعد تعثر المفاوضة الجماعية بينهما.<<CR>>
25- الوساطة:وسيلة ودية لفض منازعات العمل الجماعية،يتفق بموجبها طرفا النزاع على إسناد مهمة اقتراح التسوية إلى شخص ثالث حيادى يدعى (وسيط النزاع)،يشتركان فى اختياره من القائمة المعدة لذلك.<<CR>>
26- التحكيم:وسيلة اتفاقية لإنهاء النزاع الجماعى القائم بعد فشل وسائل التسوية الودية ويتولى القيام به محكم أو أكثر يتم اختيارهم من القائمة المعدة لذلك.<<CR>>
27- شرط التحكيم:اتفاق مكتوب بين طرفى علاقة العمل على تسوية ما قد ينشأ بينهما من نزاع بشأن هذه العلاقة بواسطة التحكيم.<<CR>>
28- مشارطة التحكيم:اتفاق مكتوب بين طرفى علاقة العمل بعد نشوء النزاع.<<CR>>
29- الإضراب عن العمل:اتفاق جميع العمال أو فريق منهم على التوقف عن أداء أعمالهم بمقر العمل للمطالبة بما يرونه محققًا لمصالحهم المهنية والاقتصادية والاجتماعية،بعد تعذر التسوية الودية،فى حدود الضوابط والإجراءات المقررة قانونًا.<<CR>>
30- إصابة العمل والأمراض المزمنة:التعريفات الواردة لها فى قانون التأمينات الاجتماعية والمعاشات الصادر بالقانون رقم 148 لسنة 2019<<CR>>
31- التحرش:كل فعل أو سلوك فى مكان العمل أو بمناسبته يشكل تعرضا للغير بإتيان أمور أو إيحاءات أو تلميحات جنسية أو إباحية سواء بالإشارة أو بالقول أو بالفعل بأية وسيلة بما فى ذلك وسائل الاتصالات السلكية أو اللاسلكية أو الإلكترونية،أو أية وسيلة تقنية أخرى.<<CR>>
32- التنمر:كل فعل أو سلوك فى مكان العمل أو بمناسبته سواء بالقول أو باستعراض القوة أو السيطرة على الغير أو استغلال ضعفه أو لحالة يعتقد مرتكب ذلك الفعل أو السلوك أنها تسيء للغير كالجنس أو العرق أو الدين أو الأوصاف البدنية أو الحالة الصحية أو العقلية أو المستوى الاجتماعى بقصد تخويفه أو وضعه موضع السخرية أو الحط من شأنه أو إقصائه من محيطه الاجتماعى.بأية وسيلة بما فى ذلك وسائل الاتصالات السلكية واللاسلكية أو الإلكترونية،أو أية وسيلة تقنية أخرى.<<CR>>
33- المنشأة:كل مشروع أو مرفق يملكه أو يديره شخص من أشخاص القانون الخاص أيا كان نوعها أو تبعيتها،وذلك مع مراعاة ما نصت عليه المادة (243) من هذا القانون.<<CR>>
34- موقع العمل:هو المكان الذى يمارس فيه العامل العمل المكلف به، أو يحتمل تواجده فيه بسببه.<<CR>>
35- المهنة أو الحرفة:كل عمل يتطلب أداؤه مهارة خاصة أو خبرة محددة، ولا ينظم مزاولته قانون خاص.<<CR>>
36- الوزير المختص:الوزير المعنى بشئون العمل.<<CR>>
37- الوزارة المختصة:الوزارة المعنية بشئون العمل.<<CR>>
38- الجهة الإدارية المختصة:الوزارة المعنية بشئون العمل ومديرياتها وإداراتها التابعة لها على مستوى الجمهورية.$m216$,'<<CR>>',chr(13))),
('law',14,2025,12,0,'4fa19f7a57a96f535468df7b398c6ced','8578c17a602dc917f3b981c58103cdff',replace($m216$يستحق العاملون الذين تسرى فى شأنهم أحكام هذا القانون علاوة سنوية دورية فى تاريخ استحقاقها لا تقل عن (3%) من الأجر التأميني،وتستحق تلك العلاوة بانقضاء سنة من تاريخ التعيين،أو من تاريخ استحقاق العلاوة الدورية السابقة. وفى حالة تعرض المنشأة لظروف اقتصادية يتعذر معها صرف العلاوة الدورية المشار إليها،يعرض الأمر على المجلس القومى للأجور للبت فى تخفيضها أو الإعفاء منها وذلك خلال ثلاثين يوما من تاريخ عرض الأمر عليه.$m216$,'<<CR>>',chr(13))),
('law',14,2025,24,0,'daa0ed31cbd550d8b7f2f3a796069161','44cd8392c9a4be5b65c66469cf432134',replace($m216$تلتزم الجهات المشار إليها فى المادة (22) من هذا القانون فيما عدا البندين (2، 3) بإخطار الوزارة المختصة بالبرامج التدريبية التى تقدمها لاعتمادها،على أن تتضمن ما يأتي: الشروط التى يجب توافرها فى المتدربين للالتحاق بالبرامج. مدى كفاية العمليات التدريبية من حيث موضوعات،ومجالات التدريب،وعدد الساعات المخصصة لها. مستويات وتخصصات المدربين. مستوى المهارة التى يكتسبها المتدرب بعد الانتهاء من البرنامج. ويصدر الوزير المختص قرارا بتحديد إجراءات ومواعيد الإخطار والاعتماد بعد التنسيق مع الهيئة المصرية لضمان الجودة والاعتماد فى التعليم الفنى والتقنى والتدريب المهنى (إتقان) المنشأة بالقانون رقم 160 لسنة. 2022$m216$,'<<CR>>',chr(13))),
('law',14,2025,38,0,'3ff6c7751253586ea322e11087c4bd08','3bcba50e0ee900e6c674005ac5fe14d2',replace($m216$تلتزم جميع المنشآت الخاضعة لأحكام هذا القانون بموافاة الوزارة المختصة ورقيا أو إلكترونيا بالبيانات أو المعلومات اللازمة لإنشاء أو تحديث قواعد بيانات العمالة،ونظام معلومات سوق العمل خلال ثلاثين يوما من تاريخ طلبها. كما يجب على أصحاب الأعمال أو من يمثلونهم بذل العناية الواجبة للتعاون مع الجهة الإدارية المختصة لاستيفاء استمارات جمع البيانات أو المعلومات ورقيا أو إلكترونيا. وعلى الوزارة المختصة القيام بجمع البيانات اللازمة عن سوق العمل وإجراء الدراسات والأبحاث الميدانية منفردة أو بالتنسيق مع الجهات المختصة،وعليها أن تصدر تقارير دورية قطاعية أو جغرافية عن احتياجات سوق العمل الحالى والمستقبلى من المهن والمهارات،ورصد أية تغيرات تطرأ عليه. (الفصل الثانى) التشغيل فى الداخل والخارج$m216$,'<<CR>>',chr(13))),
('law',14,2025,41,0,'1846e84e3a254e88ed06f81972106516','bb0e1ff17e6e0bd228067784d442c317',replace($m216$مع عدم الإخلال بالشروط التى يوجبها قانون شركات المساهمة وشركات شخص ركات ال دودة وش سئولية المح شركات ذات الم هم وال ية بالأس التوص الواحد الصادر بالقانون رقم 159 لسنة 1981 يلزم للحصول على الترخيص المشار إليه فى البند (3) من المادة (40) من هذا القانون،توافر الشروط المقررة لذلك، وعلى الأخص:<<CR>>
1- أن يكون المؤسسون وأعضاء مجلس الإدارة والمديرون المختصون بعمليات التشغيل لم يسبق الحكم على أى منهم بعقوبة جناية،أو بعقوبة مقيدة للحرية فى جنحة مخلة بالشرف أو الأمانة أو الآداب العامة،ما لم يكن قد رد إليه اعتباره.<<CR>>
2- ألا يقل رأسمال الشركة المصدر أو المدفوع،بحسب الأحوال،عن مائتين وخمسين ألف جنيه وأن يكون مملوكًا بأكمله للمصريين إذا كانت الشركة تزاول عمليات التشغيل بالداخل،وألا يقل عن خمسمائة ألف جنيه إذا كانت تزاول عمليات تشغيل المصريين بالخارج أو بالداخل والخارج معا،وأن تكون الأغلبية المطلقة للمؤسسين وأعضاء مجلس الإدارة من المصريين الذين يمتلكون فى مجموعهم (51%) على الأقل من رأسمالها.<<CR>>
3- أن تقدم الشركة تأمينًا لا يقل عن مليون جنيه إما نقدا أو بخطاب ضمان غير مشروط وغير قابل للإلغاء صادر من أحد البنوك المسجلة لدى البنك المركزى، لصالح الوزارة المختصة،وأن يكون ساريا طوال مدة سريان الترخيص وذلك لضمان التزام المرخص له بالتزاماته،ويتعين استكمال قيمة التأمين بمقدار ما لم تقم بأدائه من غرامات أو تعويضات حكم بها عليها،أو مبالغ تقاضتها دون وجه حق، طبقًا لأحكام هذا القانون،وذلك خلال خمسة عشر يوما من تاريخ إخطار الشركة المرخص لها بكتاب موصى عليه بعلم الوصول بوجوب استكمال التأمين. ويكون الترخيص لمدة سنة قابلة للتجديد وفقًا للقواعد والإجراءات التى يصدر بها قرار من الوزير المختص،وذلك مقابل أداء الرسم الذى يحدده الوزير المختص لمنح الترخيص أو تجديده بما لا يجاوز عشرة آلاف جنيه،وللوزير المختص إضافة شروط أخرى للحصول على الترخيص،وله وقف إصدار تراخيص جديدة إذا اقتضت المصلحة العامة ذلك فى ضوء متغيرات سوق العمل الفعلية.$m216$,'<<CR>>',chr(13))),
('law',14,2025,43,0,'c01f00fb98a258d0c508f1a375e5661e','b038b7718ff78f83d0bd5408a1f3a9c2',replace($m216$يحظر على الجهات المشار إليها فى المادة (40) من هذا القانون تقاضى أى مبالغ مالية من العامل بطريقة مباشرة أو غير مباشرة نظير إلحاقه بالعمل،ولها أن تتقاضى مقابل ذلك من صاحب العمل. واستثناء من أحكام الفقرة الأولى من هذه المادة يجوز للشركات المشار إليها فى البند (3) من المادة (40) من هذا القانون أن تتقاضى مبلغًا لا يجاوز (1%) من أجر العامل الذى يتم إلحاقه بالعمل،وذلك عن السنة الأولى فقط كمصروفات إدارية، ويحظر تقاضى أى مبالغ أخرى من العامل تحت أى مسمى.$m216$,'<<CR>>',chr(13))),
('law',14,2025,52,0,'adf81daa0e203cc41eac994b91f99a82','19518a1cb1b477ace8f259b09b98d94f',replace($m216$لا يجوز ممارسة عمليات إلحاق المصريين بالداخل والخارج إلكترونيا من خلال مواقع أو صفحات أو منصات إلكترونية إلا بعد الحصول على ترخيص بذلك من الوزارة المختصة،ويستثنى من ذلك وكالات التشغيل المشار إليها فى البند (3) من المادة (40) ويصدر الوزير المختص بالتشاور مع الوزير المعنى بشئون الاتصالات قرارا بقواعد منح هذا الترخيص،ومدته بما لا يجاوز سنة،والرسوم المقررة عليه بما لا يقل عن ألف جنيه ولا يزيد على عشرة آلاف جنيه،وضوابط وقواعد التشغيل، والتقارير التى تقدمها عن نتائج أعمالها،وآليات التنسيق معها.<<CR>>
(الفصل الثالث) تشغيل النساء$m216$,'<<CR>>',chr(13))),
('law',14,2025,60,0,'a720b23b1a15e1faa9c5a844f10d163d','37016b70c7c8d2b9e28b918191bca514',replace($m216$مع عدم الإخلال بأحكام قانون الطفل المشار إليه على صاحب العمل الذى يستخدم مائة عاملة فأكثر فى مكان واحد أن ينشئ دا را للحضانة،أو يعهد إلى دار للحضانة برعاية أطفال العاملات. وتلتزم المنشآت التى تقع فى منطقة واحدة وتستخدم كل منها أقل من مائة عاملة،أن تشترك فى تنفيذ الالتزام المنصوص عليه فى الفقرة الأولى من هذه المادة. واستثناء من ذلك،لصاحب العمل أن يتحمل تكاليف رعاية الأطفال بدار الحضانة. وذلك كله بالضوابط والأوضاع التى يصدر بها قرار من الوزير المختص بعد التنسيق مع الوزير المعنى بشئون التضامن الاجتماعى والمجلس القومى للطفولة والأمومة. (الفصل الرابع) أحكام تشغيل وتدريب الأطفال$m216$,'<<CR>>',chr(13))),
('law',14,2025,68,0,'a5eca3bb4f5944b773d233b5fc485953','73e542f9a9fdd3b3dd818b298435cc3e',replace($m216$يحظر على الأبوين أو متولى أمر الطفل،بحسب الأحوال،تشغيل الطفل بالمخالفة لأحكام هذا القانون،والقرارات التنفيذية الصادرة له.<<CR>>
(الفصل الخامس) تنظيم عمل الأجانب$m216$,'<<CR>>',chr(13))),
('law',14,2025,82,0,'873c7f5985aa81737755b0216a21d99e','5bc1d0b96e9c9cdd1c1284d5b5801155',replace($m216$تتكون موارد الصندوق مما يأتي:<<CR>>
1- نسبة لا تقل عن (1%) ولا تزيد على (3%) من قيمة الأجور الفعلية للعمالة غير المنتظمة فى قطاع المقاولات والتشييد والبناء،فإذا تعذر الوقوف على قيمة الأجور الفعلية تقدر قيمة الأجور حكما بنسبة لا تزيد على (20%) من قيمة العملية فى المقاولات العامة،ولا تزيد على (45%) فى عمليات الخدمات والمصنعية.<<CR>>
2- نسبة لا تقل عن (1%) ولا تزيد على (3%) من قيمة الأجور الفعلية للعمالة غير المنتظمة فى قطاع المناجم والمحاجر وما فى حكمها،فإذا تعذر الوقوف على قيمة الأجور الفعلية تقدر قيمة الأجور حكما بنسبة لا تزيد على (15%) من قيمة العملية.<<CR>>
3- اشتراك قيد لفئات العمالة غير المنتظمة الأخرى،لا يقل عن 20 جنيها ولا يزيد على 200 جنيه شهريا.<<CR>>
4- نسبة (0,5%) نصف فى المائة من قيمة مبيعات المنتجات الزراعية التى تشتريها الدولة.<<CR>>
5- مبلغ 100 جنيه عن كل طلب توثيق أو طلب صحة توقيع أو صحة نفاذ عقود بيع الأراضى الزراعية.<<CR>>
6- مبلغ لا يجاوز 50 جنيها عن كل رخصة قيادة مهنية تصدر لأول مرة أو عند تجديدها.<<CR>>
7- كافة أموال حسابات العمالة غير المنتظمة بمديريات العمل،وعوائد الأصول والودائع الخاصة بها.<<CR>>
8- التبرعات والهبات العينية والنقدية التى يوافق عليها مجلس الإدارة،وبما لا يخالف القوانين واللوائح المعمول بها.<<CR>>
9- عائد الخدمات التى يقدمها الصندوق بمقابل رمزى (إن وجدت).<<CR>>
10- عائد استثمار أموال الصندوق. ويصدر بتحديد فئات الرسوم والاشتراكات المشار إليها فى هذه المادة، وبما لا يزيد على الحد الأقصى المقرر،ومواعيد الوفاء بها،قرار من رئيس مجلس إدارة الصندوق.$m216$,'<<CR>>',chr(13)));
INSERT INTO m216_fix VALUES
('law',14,2025,95,0,'0bdc1f83814bd552f70d14f017943d82','90663f7a9a6a31dab589fa535963c352',replace($m216$يلتزم العامل الذى تم تدريبه على نفقة صاحب العمل بأن يقضى لديه المدة المتفق عليها،وفى حالة تركه العمل قبل انقضاء هذه المدة يلتزم بسداد نفقات التدريب،دون إخلال بحق صاحب العمل فى التعويض،ما لم ينص عقد العمل على خلاف ذلك. (الفصل الثانى) أنماط العمل الجديدة$m216$,'<<CR>>',chr(13))),
('law',14,2025,100,0,'760d30600bde80354926a786f51d15f1','b0babe35cfb8b502db1fb83760909b26',replace($m216$يصدر الوزير المختص بالتشاور مع المنظمات النقابية العمالية ومنظمات أصحاب الأعمال القرارات اللازمة لتنظيم أنماط العمل الجديدة،وتحديد صورها والنماذج الاسترشادية لعقود ولوائح العمل،وطرق إثبات علاقة العمل،وآليات حصول الطرفين على حقوقهم،وذلك فى موعد لا يتجاوز ستة أشهر من تاريخ إصدار هذا القانون. (الفصل الثالث) الأجور$m216$,'<<CR>>',chr(13))),
('law',14,2025,116,0,'b2fd24cba1998dbbe181ab17f27f55ed','8ab90e49ae10b313337f40683f7077f2',replace($m216$مع مراعاة حكم المادة (115) من هذا القانون،يسلم صاحب العمل إلى عماله من الأطفال أجورهم أو مكافآتهم أو غير ذلك مما يستحقونه قانونًا.ويكون هذا التسليم مبرئًا لذميه.<<CR>>
(الفصل الرابع) ساعات العمل وفترات الراحة$m216$,'<<CR>>',chr(13))),
('law',14,2025,121,0,'f85d900a061f0e687d177763e8504321','1948ce79ecc47fd0d6efd5e1b92c1de1',replace($m216$يجوز لصاحب العمل عدم التقيد بالأحكام الواردة بالمواد )، 119، 118، 117 (120 من هذا القانون،إذا كان التشغيل بقصد مواجهة ضرورات عمل غير عادية، أو ظروف استثنائية،ويشترط فى هذه الحالات إبلاغ الجهة الإدارية المختصة فى خلال سبعة أيام من وقوع ظروف العمل غير العادية أو الظروف الاستثنائية بمبررات التشغيل الإضافى والمدة اللازمة لإتمام العمل. وفى هذه الحالة يستحق العامل بالإضافة إلى أجره عن ساعات العمل الأصلية، أجرا عن ساعات التشغيل الإضافية حسبما يتم الاتفاق عليه فى عقد العمل الفردى أو الجماعى،بحيث لا يقل عن الأجر الذى يستحقه العامل مضافًا إليه (35%) عن ساعة العمل النهارية،و (70%) عن ساعة العمل الليلية تحسب على أساس أجر ساعة عمله الأصلية،فإذا وقع التشغيل فى يوم الراحة استحق العامل مثل أجره تعويضا عن هذا اليوم،ويمنحه صاحب العمل يوما آخر عوضا عنه خلال الأسبوع التالي. وفى جميع الأحوال،لا يجوز أن تزيد ساعات وجود العامل بالمنشأة على اثنتى عشرة ساعة.$m216$,'<<CR>>',chr(13))),
('law',14,2025,131,0,'fa9ba29da040a6813adce6073546ac5b','ac5a56bcf0c07da0c7a5d885c65497e2',replace($m216$للعامل الذى يثبت مرضه،أو إصابته على نحو يحول بينه وبين أداء عمله الحق فى إجازة مرضية تحددها الجهة الطبية المختصة،ويستحق العامل خلالها تعويضا عن الأجر،تحدد نسبته ومدته،وفقًا لأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه. ويكون للعامل الذى يثبت مرضه فى المنشآت الصناعية التى يسرى فى شأنها قانون تيسير منح تراخيص المنشآت الصناعية الصادر بالقانون رقم 15 لسنة، 2017 الحق فى إجازة مرضية كل ثلاث سنوات تقضى فى الخدمة على أساس ثلاثة أشهر بأجر،<<CR>>
ثم ستة أشهر بأجر يعادل (85%) من أجره،ثم ثلاثة أشهر بأجر يعادل (75%) من أجره، وذلك إذا قررت الجهة الطبية المختصة احتمال شفائه. ويخصم من الأجر الذى يلتزم به صاحب العمل،ما يلتزم بأدائه نظام التأمين الاجتماعى من تعويض عن الأجر. وللعامل أن يستفيد من متجمد إجازاته السنوية إلى جانب ما يستحقه من إجازة مرضية،كما له أن يطلب تحويل الإجازة المرضية إلى إجازة سنوية،إذا كان له رصيد يسمح بذلك.$m216$,'<<CR>>',chr(13))),
('law',14,2025,133,0,'aa20df37bc25a905627cb9cbd32d6224','254617267d8b66bd1e198d32fba9dafc',replace($m216$تثبت عدم اللياقة للخدمة صحيا وفقًا لأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه. (الفصل السادس) واجبات العمال ومساءلتهم$m216$,'<<CR>>',chr(13))),
('law',14,2025,149,0,'0fbdfc843ef8a53befe90673ea6eb792','f587711d619dc0f0a42f07914fa35a01',replace($m216$مع عدم الإخلال بحق التقاضي،إذا نشأ نزاع فردى بين صاحب العمل والعامل بشأن تطبيق أحكام هذا القانون،أو أى من القوانين ذات الصلة كان لأى منهما خلال عشرة أيام من تاريخ نشوء النزاع أن يطلب تسويته وديا بمعرفة لجنة تشكل على النحو الآتي:<<CR>>
1- مدير مديرية العمل،أو من ينيبه (رئيسا).<<CR>>
2- العامل،أو من يمثله (عضوا).<<CR>>
3- صاحب العمل،أو من يمثله (عضوا). ولرئيس اللجنة أن يستعين بذوى الخبرة حسب الموضوع المعروض.<<CR>>
ويجب أن تنتهى اللجنة من أعمالها خلال واحد وعشرين يوما من تاريخ تقديم الطلب،فإذا تمت التسوية الودية،يثبت رئيس اللجنة ذلك فى محضر يوقعه طرفا النزاع،ويلحق بمحضر الجلسة التى تم فيها،ويحال إلى قاضى الأمور الوقتية بالمحكمة العمالية المختصة،ويكون قابلاً للتنفيذ بالأمر الذى يصدره وينتهى به النزاع فى حدود ما تمت التسوية الودية فيه. ويصدر الوزير المختص قرارا بنظام عمل اللجنة والنماذج والسجلات التى تستعين بها.$m216$,'<<CR>>',chr(13))),
('law',14,2025,153,0,'40ae014c4a7b1a03960f4fd20cde7848','2fbd8a59743764236c1e1d96b8cc4e20',replace($m216$يجب على صاحب العمل أن يمسك سجلاً ورقيا أو إلكترونيا لقيد الجزاءات المالية الموقعة على العمال،مع بيان سبب توقيعها واسم العامل ومقدار أجره، وأن يفرد لحصيلتها حسابا خاصا للصرف على عمال المنشأة فى الأغراض الاجتماعية والثقافية والرياضية،ولا يجوز صرف هذه المبالغ للوفاء بالالتزامات المنصوص عليها فى المادة (272) من هذا القانون وتوزع حصيلة تلك الأموال عند تصفية المنشأة بالتساوى على العمال الموجودين بها وقت التصفية. (الفصل السابع) انتهاء علاقة العمل الفردية$m216$,'<<CR>>',chr(13))),
('law',14,2025,178,0,'d78d1c70aaa8ec64c44e109cb9b48c19','4ab735f9cebe861620b06b23e556a75a',replace($m216$تشكل كل دائرة من دوائر المحكمة العمالية من ثلاثة من القضاة بالمحاكم الابتدائية،يكون أحدهم على الأقل بدرجة رئيس من الفئة (أ). وتشكل كل دائرة من الدوائر الاستئنافية المتخصصة من ثلاثة من قضاة الاستئناف يكون أحدهم على الأقل بدرجة رئيس بمحكمة الاستئناف.$m216$,'<<CR>>',chr(13))),
('law',14,2025,179,0,'541647abe1aad88cea16acd703d060ae','dd4fe88c9ac72a7f852ccb5d8380898c',replace($m216$تعين الجمعية العمومية للمحكمة الابتدائية فى بداية كل عام قضائى قاضيا بدرجة رئيس محكمة من الفئة (أ) ليحكم بصفة مؤقتة مع عدم المساس بأصل الحق فى المسائل المستعجلة التى يخشى عليها من فوات الوقت،وإصدار الأوامر على عرائض،والأوامر الوقتية،وأوامر الأداء فى تلك المسائل أيا كانت قيمة الحق محل الطلب الذى تختص به المحاكم العمالية.$m216$,'<<CR>>',chr(13))),
('law',14,2025,193,0,'1004b48e11eb441e639defde119a5d75','b65ad5b083b2d6dddeb28d2bbfd72a59',replace($m216$يجوز للمجلس قبول الهبات والمنح والتبرعات بعد العرض على مجلس إدارته وموافقة ثلثى أعضائه على الأقل،ووفقًا للقواعد والإجراءات المقررة قانونًا.<<CR>>
ويكون للمجلس حساب خاص ضمن حساب الخزانة الموحد لدى البنك المركزى، وله أن يفتح حسابا لدى أحد البنوك المسجلة لدى البنك المركزى بعد موافقة وزير المالية،ويرحل فائض أمواله من سنة مالية إلى أخرى،وله أن يستثمر أمواله استثمارا أمنًا،ويخضع حسابه لرقابة الجهاز المركزى للمحاسبات. (الفصل الثانى) المفاوضة الجماعية$m216$,'<<CR>>',chr(13))),
('law',14,2025,198,0,'b2a7cb9c85c4b3e6ab12d2ebebf5ffc2','44ba323b08f217e711982aa51f637f19',replace($m216$يحظر على طرفى علاقة العمل أثناء المفاوضة اتخاذ إجراءات،أو إصدار قرارات تتعلق بالموضوعات محل التفاوض،إلا فى حالة الضرورة والاستعجال ويشترط أن يكون الإجراء أو القرار فى هذه الحالة مؤقتًا. (الفصل الثالث) اتفاقيات العمل الجماعية$m216$,'<<CR>>',chr(13))),
('law',14,2025,212,0,'670a2b4cad1a1075a20528ac57c655c9','391bf9f548f2e0e8609a9535fc4b5e03',replace($m216$مع عدم الإخلال بحق التقاضي،تخضع المنازعات الناشئة عن الاتفاقية الجماعية للإجراءات التى يتفق عليها الطرفان،مع مراعاة الأحكام الواردة فى الباب الثالث من هذا الكتاب. (الفصل الرابع) منازعات العمل الجماعية الفرع الأول أحكام عامة$m216$,'<<CR>>',chr(13))),
('law',14,2025,230,0,'d67cb0813b1e8914c4a6de5d3e6aa256','bddad72edacfa0d92fe55cf5127e8d99',replace($m216$تشكل بقسم التحكيم دائرة عليا أو أكثر،لإعادة النظر،مكونة من خمسة محكمين من المقيدين بقائمتها للطعن فى الأحكام المشار إليها فى المادة (229) من هذا القانون. وإذا تضمن شرط أو مشارطة التحكيم أن يكون على درجتين،يحال النزاع إلى تلك الدائرة خلال خمسة عشر يوما من تاريخ صدور حكم أول درجة،ويتعين عليها الفصل فى النزاع خلال خمسة وأربعين يوما من تاريخ الإحالة إليها. (الفصل الخامس) الإضراب والإغلاق$m216$,'<<CR>>',chr(13))),
('law',14,2025,246,0,'1737c91750be3c60571a4be218b8c969','42aeb090f3cb6cc6da2670a499191229',replace($m216$تلتزم المنشأة،وفروعها،بتوفير وسائل السلامة والصحة المهنية،وتأمين بيئة العمل فى أماكن العمل،وفقًا لمعايير التعرض والحدود العتبية،وبما يكفل الوقاية من المخاطر الفيزيائية الناجمة عما يلى:<<CR>>
1- الوطأة الحرارية والبرودة.<<CR>>
2- الضوضاء والاهتزازات.<<CR>>
3- شدة الاستضاءة.<<CR>>
4- الإشعاعات الضارة والخطرة (مؤينة -غير مؤينة).<<CR>>
5- تغيرات الضغط الجوى.<<CR>>
6- مخاطر الانفجار.$m216$,'<<CR>>',chr(13))),
('law',14,2025,247,0,'33b24049ecd2aa269a41bf3500dce17a','ef05bac711b658f4771f81c42fa52d27',replace($m216$تلتزم المنشأة،وفروعها باتخاذ الاحتياطات والتدابير اللازمة لتوفير وسائل السلامة والصحة المهنية وتأمين بيئة العمل،بما يكفل الوقاية من المخاطر الهندسية (ميكانيكية -كهربائية -تشييد وبناء -المواءمة)،وعلى الأخص ما يأتي:<<CR>>
1- كل خطر ينشأ عن معدات وأدوات رفع وجر،ووسائل الانتقال،والتداول، ونقل الحركة.<<CR>>
2- كل خطر ينشأ عن أعمال التشييد والبناء،والحفر،ومخاطر الانهيار،والسقوط.<<CR>>
3- كل خطر ينشأ عن الكهرباء (الديناميكية والاستاتيكية).<<CR>>
4- كل خطر ينشأ عن عدم مراعاة التناسب بين البنية الجسدية للعامل والمعدات والآلات،وبين مكان العمل.$m216$,'<<CR>>',chr(13))),
('law',14,2025,256,0,'1cd2a44b5a9285458ec387af1b6c1db9','a3d9622df24b1b0d4edc96e9e4064e12',replace($m216$مع مراعاة الأحكام الواردة فى الكتاب الخامس من هذا القانون،تلتزم الجهة الإدارية المختصة بما يأتي:<<CR>>
1- تشكيل جهاز متخصص يسمى (جهاز تفتيش السلامة والصحة المهنية وتأمين بيئة العمل)،من أعضاء تتوافر فيهم المؤهلات العلمية والعملية فى مجالات الطب البشرى،والبيطرى،والصيدلة،والهندسة والعلوم،والبيئة وإدارة المخلفات للتفتيش على المنشآت ومراقبة تنفيذ أحكام السلامة والصحة المهنية وتأمين بيئة العمل على أن يكون التفتيش على فترات دورية مناسبة.<<CR>>
2- تنظيم برامج تدريبية متخصصة ونوعية لرفع كفاءة ومستوى أداء أعضاء جهاز التفتيش المشار إليه فى البند (1) من هذه المادة،وتزويدهم بالخبرات الفنية والتطورات الحديثة بما يضمن أفضل مستويات السلامة والصحة المهنية وتأمين بيئة العمل.<<CR>>
3- تزويد جهاز التفتيش المشار إليه بأجهزة ومعدات القياس،وجميع الإمكانيات اللازمة لأداء مهمته. ويكون التفتيش على المنشآت المتعلق عملها بالأمن القومى،والتى تحدد بقرار من رئيس مجلس الوزراء،بمعرفة الجهة التى يحددها هذا القرار.$m216$,'<<CR>>',chr(13))),
('law',14,2025,273,0,'37607c19239937fa556a4bbade7c0cce','9576711f1e243dd87ed692428c29aea9',replace($m216$يتمتع صندوق الخدمات الاجتماعية والصحية والثقافية بالشخصية الاعتبارية، ويهدف إلى تقديم الخدمات اللازمة للنهوض بالمستوى الاجتماعى والصحى والثقافى للعاملين بمنشآت القطاع العام،وقطاع الأعمال العام،والقطاع الخاص. ويصدر رئيس مجلس الوزراء قرارا بتشكيل مجلس إدارة الصندوق برئاسة الوزير المختص،وعضوية ممثلى المنظمات النقابية العمالية المعنية ومنظمات أصحاب الأعمال بالتساوى فيما بينهما،ترشحهم منظماتهم،وممثلى الوزارات والجهات المعنية ويحدد القرار اختصاصات المجلس والنظام الأساسى للصندوق والمعاملة المالية لرئيس وأعضاء مجلس الإدارة،على أن تكون من موارده الذاتية، والنظام المحاسبى الواجب إتباعه. ويكون للصندوق حساب خاص لدى أحد البنوك التجارية المسجلة لدى البنك المركزى المصرى،وموازنة مستقلة،ويعد الصندوق سنويا القوائم الدالة على المركز المالى وفقًا لنظام المحاسبة المالية،وتبدأ السنة المالية للصندوق مع السنة المالية للدولة،وتنتهى بانتهائها وتخضع أمواله لرقابة الجهاز المركزى للمحاسبات، ويرحل فائض أمواله من سنة إلى أخرى. وتلتزم المنشآت المشار إليها بالفقرة الأولى من هذه المادة والتى يبلغ عدد عمالها عشرون عاملاً فأكثر بسداد اشتراك سنوى لا يقل عن ثمانية جنيهات ولا يجاوز ستة عشر جنيها عن كل عامل سنويا لتمويل هذا الصندوق،ويصدر بتحديد قيمة الاشتراك السنوى قرار من الوزير المختص،بعد العرض على مجلس إدارة الصندوق،ويحق للمنشأة حال تقديمها للخدمات الواردة بالمادة 274 من هذا القانون،أو تقديمها لميزة أفضل للعاملين لديها خصم قيمة تلك الخدمات أو الميزة أو خصم (70%) من المبلغ المستحق عليها للصندوق سنويا،أيهما أقل.$m216$,'<<CR>>',chr(13)));

DO $m216$
DECLARE
  v_expected int := 178;
  v_total int; v_found int; v_todo int; v_done int; v_skipped int;
  v_art_before int; v_ver_before int; v_upd_art int; v_upd_ver int; v_bad int;
BEGIN
  SELECT count(*) INTO v_total FROM m216_fix;
  IF v_total <> v_expected THEN
    RAISE EXCEPTION '[216] تحميل البيانات ناقص: % من %', v_total, v_expected;
  END IF;

  CREATE TEMP TABLE m216_tgt ON COMMIT DROP AS
    SELECT a.id AS article_id, f.old_md5, f.new_md5, f.new_body, md5(a.body) AS cur_md5
    FROM m216_fix f
    JOIN laws l ON l.country_code = 'EG' AND l.kind = f.kind AND l.law_no = f.law_no AND l.law_year = f.law_year
    JOIN articles a ON a.law_id = l.id AND a.article_no = f.article_no AND a.article_suffix_order = f.suffix;
  SELECT count(*) INTO v_found FROM m216_tgt;
  SELECT count(*) INTO v_done FROM m216_tgt WHERE cur_md5 = new_md5;
  SELECT count(*) INTO v_todo FROM m216_tgt WHERE cur_md5 = old_md5 AND old_md5 <> new_md5;
  v_skipped := v_total - v_done - v_todo;

  SELECT count(*) INTO v_art_before FROM articles;
  SELECT count(*) INTO v_ver_before FROM article_versions;

  INSERT INTO migration_216_backup (article_id, version_id, old_body)
    SELECT a.id, NULL, a.body FROM m216_tgt t JOIN articles a ON a.id = t.article_id
    WHERE t.cur_md5 = t.old_md5 AND t.old_md5 <> t.new_md5
    ON CONFLICT DO NOTHING;
  INSERT INTO migration_216_backup (article_id, version_id, old_body)
    SELECT v.article_id, v.id, v.body FROM m216_tgt t JOIN article_versions v ON v.article_id = t.article_id
    WHERE md5(v.body) = t.old_md5 AND t.old_md5 <> t.new_md5
    ON CONFLICT DO NOTHING;

  UPDATE article_versions v SET body = t.new_body
    FROM m216_tgt t
    WHERE v.article_id = t.article_id AND md5(v.body) = t.old_md5 AND t.old_md5 <> t.new_md5;
  GET DIAGNOSTICS v_upd_ver = ROW_COUNT;
  UPDATE articles a SET body = t.new_body
    FROM m216_tgt t
    WHERE a.id = t.article_id AND md5(a.body) = t.old_md5 AND t.old_md5 <> t.new_md5;
  GET DIAGNOSTICS v_upd_art = ROW_COUNT;

  IF (SELECT count(*) FROM articles) <> v_art_before OR (SELECT count(*) FROM article_versions) <> v_ver_before THEN
    RAISE EXCEPTION '[216] تغيّر عدد المواد أو النسخ';
  END IF;
  IF v_upd_art <> v_todo THEN
    RAISE EXCEPTION '[216] عدد المواد المعدلة % لا يطابق المتوقع %', v_upd_art, v_todo;
  END IF;
  SELECT count(*) INTO v_bad FROM m216_tgt t JOIN articles a ON a.id = t.article_id
   WHERE t.cur_md5 IN (t.old_md5, t.new_md5) AND md5(a.body) <> t.new_md5;
  IF v_bad <> 0 THEN
    RAISE EXCEPTION '[216] % مادة نصها بعد التعديل لا يطابق النص المُختبَر', v_bad;
  END IF;

  -- ختام: لا بقايا من العيوب المعالَجة فى المواد المعدلة
  SELECT count(*) INTO v_bad FROM m216_tgt t JOIN articles a ON a.id = t.article_id
   WHERE md5(a.body) = t.new_md5
     AND (a.body ~ '\)[ \t]*[.]?[ \t]*\([ \t]*%'
          OR a.body ~ 'الجريدة[ \t]+الرسمية[ \t]*[–-][ \t]*العدد[ \t]+43[ \t]+مكرر'
          OR a.body ~ '[^[:space:]][ \t]+[،؛][^[:space:][:digit:]]');
  IF v_bad <> 0 THEN
    RAISE EXCEPTION '[216] % مادة فيها بقايا من العيوب المعالَجة', v_bad;
  END IF;

  RAISE NOTICE '[216] مواد مستهدفة: % | وُجدت: % | عُدِّلت الآن: % | معدَّلة سابقاً: % | نسخ عُدِّلت: % | تُخطّيت (نص مختلف أو غير موجودة): %',
    v_total, v_found, v_upd_art, v_done, v_upd_ver, v_skipped;
  IF v_skipped > 0 THEN
    RAISE WARNING '[216] % مادة تُخطّيت لأن نصها الحالى يختلف عن المتوقع أو لم توجد — راجعها يدوياً', v_skipped;
  END IF;
END
$m216$;
